insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_directives','auto_apply_allowed','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Let agents create and change things without asking','When this is off, an agent that wants to create, update or delete something shows you what it intends to do and waits for you to confirm. Turn it on only for agents and workflows you want to act on your data unattended.','agent','DD-118 (2026-09-12): the apply-policy cascade let an agent definition''s own auto_apply flag resolve to auto with no organization in the loop; walk K-1 wrote a project and four tasks into an organization that had never configured the agent. Law 6 gives this decision to the organization; off is the safe default before anyone has chosen.','2026-12-12'::date,'7e6f5a07-44a4-4568-8f1b-c035cd7bdb13'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{"help": "Off means an agent always asks first. On means agents you have set up to act unattended can write straight away.", "group": "Agents", "order": 10, "control": "toggle"}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_exemplars','auto_capture_target','3'::jsonb,'3'::jsonb,'number','test cases','0'::numeric,'20'::numeric,NULL::jsonb,'Auto-capture target per agent/mandate','Until an agent (or mandate) holds this many captured candidate test cases, successful real runs self-capture their inputs+output as source=captured candidates. 0 disables auto-capture.','agent','Carried over from the hardcoded AUTO_CAPTURE_TARGET=3 in aidream services/mandates/service.py (limits-are-knobs conversion, 2026-08-26). 3 matches Arman''s 1-3 samples-per-agent ruling.','2026-11-01'::date,'706da68d-6670-4baf-ac12-7fb6765c99d3'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_exemplars','capture_max_chars','60000'::jsonb,'60000'::jsonb,'integer','characters','1000'::numeric,'1000000'::numeric,NULL::jsonb,'Exemplar auto-capture size ceiling','A run whose serialized inputs or output exceed this is SKIPPED by auto-capture, never truncated — a truncated exemplar would silently test a different input than production ran. Failure captures deliberately ignore this ceiling.','agent','Carried over from TWO identical hardcoded constants it replaces: AUTO_CAPTURE_MAX_CHARS=60_000 (aidream/services/mandates/service.py) and CAPTURE_MAX_CHARS=60_000 (aidream/services/agent_testing/capture.py) — one number, one row. PLATFORM-LOCKED: exemplars attach to SYSTEM-owned mandates/agents and form the platform''s shared bench corpus, so a per-org ceiling would let one tenant''s runs govern another tenant''s bench. Blast-radius/storage backstop, not tenant policy.','2026-10-31'::date,'706da68d-6670-4baf-ac12-7fb6765c99d3'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_exemplars','count_cache_ttl_seconds','300'::jsonb,'300'::jsonb,'integer','seconds','5'::numeric,'3600'::numeric,NULL::jsonb,'Exemplar count cache TTL','How long the per-mandate / per-agent exemplar COUNT is trusted before it is re-counted. The count decides whether auto-capture still has room under auto_capture_target.','agent','Carried over from the hardcoded _CACHE_TTL_SECONDS=300.0 that both auto-capture paths reused (aidream/services/mandates/service.py exemplar count cache, aidream/services/agent_testing/capture.py). PLATFORM-LOCKED for the same reason as capture_max_chars: the corpus is system-owned.','2026-10-31'::date,'706da68d-6670-4baf-ac12-7fb6765c99d3'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_exemplars','max_approved_per_agent','3'::jsonb,'3'::jsonb,'number','test cases','1'::numeric,'20'::numeric,NULL::jsonb,'Max approved test cases per agent','Ceiling on APPROVED sample-input test cases per agent (candidates are unlimited). Enforced by public.agx_exemplar_approve.','agent','Arman specified 1-3 samples per agent (2026-08-25) on conflict (feature,key) do nothing; 3 is the stated maximum. Candidates are capped separately by the auto-capture target.','2026-11-01'::date,'706da68d-6670-4baf-ac12-7fb6765c99d3'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_impact','auto_advance_green','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Advance green pins automatically after an agent is saved','When you save an agent, the jobs pinned to it whose change is green or identical, whose settings check ran clean, whose duplicates are no worse, and whose new version is older than the minimum version age are moved to the new version by themselves. Every automatic move announces itself with a Put back button. Off means nothing moves without a click.','agent','Agent Change Impact I9 (mandate: earned later, on instrumented batches — off by default). Read live through platform.knob_resolve in features/mandates/admin/impact.ts; the hard conditions are not knobs.','2026-10-13'::date,'883847a0-5900-41c4-bf64-f65d24222655'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_impact','max_agent_ids','500'::jsonb,'500'::jsonb,'integer','agents','1'::numeric,'5000'::numeric,NULL::jsonb,'Most agents in one impact request','The most agents one impact request may ask about at once. Above it the request is refused with the number and the cap, so the caller can split it.','agent','Replaces MAX_AGENT_IDS = 500 in aidream/services/agent_impact/service.py; read live through knob_int.','2026-10-13'::date,'883847a0-5900-41c4-bf64-f65d24222655'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_impact','max_batch_tokens','500'::jsonb,'500'::jsonb,'integer','rows','1'::numeric,'5000'::numeric,NULL::jsonb,'Most rows in one batch pin advance','The most jobs one batch advance or revert may write at once. Above it the request is refused with the number and the cap, so the caller can split it.','agent','New with the batch pin advance (Agent Change Impact I3) on conflict (feature,key) do nothing; read live through knob_int in aidream/services/agent_impact/advance.py.','2026-10-13'::date,'883847a0-5900-41c4-bf64-f65d24222655'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_impact','max_principal_groups','64'::jsonb,'64'::jsonb,'integer','groups','1'::numeric,'1000'::numeric,NULL::jsonb,'Most principal groups in one set-aside read','The most distinct groups of people one set-aside read will look up. Past it the request is refused with the remedy rather than answered partially.','agent','Replaces MAX_PRINCIPAL_GROUPS = 64 in aidream/services/agent_impact/set_aside.py; read live through knob_int.','2026-10-13'::date,'883847a0-5900-41c4-bf64-f65d24222655'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_impact','minimum_version_age_hours','24'::jsonb,'24'::jsonb,'integer','hours','0'::numeric,'720'::numeric,NULL::jsonb,'Minimum age of a version before it auto-advances','A new agent version must be at least this many hours old before any pin moves to it automatically. Younger versions can still be advanced by a person; the impact table says how old the version is and how long this organization waits.','agent','Agent Change Impact I9; was the constant MINIMUM_VERSION_AGE_HOURS = 24 in aidream/services/agent_impact/service.py, now read per row organization through scoped_knob_int there.','2026-10-13'::date,'883847a0-5900-41c4-bf64-f65d24222655'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_impact','post_edit_auto_open','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Open the impact panel automatically after saving an agent','After you save an agent that a job pins, a badge and a toast always say how many jobs the change reaches and offer to open the impact panel. Turn this on to open that panel every time without clicking.','agent','New with the post-edit badge (Agent Change Impact I6) on conflict (feature,key) do nothing; read live through platform.knob_resolve in features/mandates/admin/impact.ts. Off by default so a save never pops a window uninvited.','2026-10-13'::date,'883847a0-5900-41c4-bf64-f65d24222655'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agent_impact','revert_window_hours','72'::jsonb,'72'::jsonb,'integer','hours','1'::numeric,'720'::numeric,NULL::jsonb,'Hours a batch pin advance stays revertible','After a batch moves jobs to a newer agent version, this is how long the one-click revert stays open for that batch. Past it the ledger still shows what happened, but undoing it is a new deliberate change rather than a revert. Three days is long enough to notice a regression over a weekend.','agent','New with the batch pin advance (Agent Change Impact I3/I9) on conflict (feature,key) do nothing; read live through scoped_knob_int in aidream/services/agent_impact/advance.py. 72h follows Stripe''s reversal window.','2026-10-13'::date,'883847a0-5900-41c4-bf64-f65d24222655'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agents.model_catalog','authoring_successor_hop_limit','5'::jsonb,'5'::jsonb,'integer','hops','1'::numeric,'50'::numeric,NULL::jsonb,'Successor hops followed for a retired model','When an agent names a retired model, the catalog follows the model''s successor chain this many steps before calling the catalog broken.','agent','Replaces AUTHORING_SUCCESSOR_HOP_LIMIT = 5 in matrx-ai catalog/lifecycle.py; the host binds the row through configure_catalog_knobs, the package default is a KNOB MIRROR for standalone use.','2026-10-13'::date,'0167cccf-9e3b-439c-bb2d-b1c39bf4fc29'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agents.model_prefs','agent_authoring_default_model','null'::jsonb,'null'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Preferred model for building agents','The model that powers the agent builder when you create or revise an agent.','human','USD-12 / done-bar item 3: a preferred model for building agents exists and is honoured; null = the platform''s primary text model.','2026-12-10'::date,'883847a0-5900-41c4-bf64-f65d24222655'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{"help": "Building an agent is heavier work than chatting; a stronger model here pays off.", "group": "AI", "order": 2, "control": "model"}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agents.model_prefs','chat_default_model','null'::jsonb,'null'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Default AI model for basic work','The model that answers when you have not picked one — chat, quick questions, everyday drafting.','human','USD-12: the first screen carries a default model for basic work; null = the platform''s primary text model.','2026-12-10'::date,'0167cccf-9e3b-439c-bb2d-b1c39bf4fc29'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{"help": "Pick the model you want by default. Your organization can set one for everyone; yours wins for you.", "group": "AI", "order": 1, "control": "model"}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agents.request_snapshot','assistant_text_announce_bytes','4194304'::jsonb,'4194304'::jsonb,'integer','bytes','65536'::numeric,'104857600'::numeric,NULL::jsonb,'Size at which a recorded AI answer raises a warning','Every AI answer is recorded in full so Run history and replay can show exactly what the model said. When a single answer is larger than this, it is still recorded in full, and the server logs a warning naming the call and its size so an unexpectedly huge answer is noticed. Lower it to hear about big answers sooner; raise it if the warning fires for answers that are normal for your work.','agent','The largest structured answers seen live (keyword classifier, 2026-09) are ~73 KB; 4 MiB is roughly fifty times that, so it only fires for answers far outside anything observed.','2026-12-14'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agents.tool_dispatch','default_timeout_seconds','120'::jsonb,'120'::jsonb,'integer','seconds','5'::numeric,'1800'::numeric,NULL::jsonb,'How long any tool call may run before it is cancelled','The deadline the agent tool executor gives a tool call whose own registry row declares no timeout. When it passes, the call is cancelled and the agent is told what it was doing and that it may retry. Raise it if agents legitimately lose long work; lower it to fail faster.','agent','The value the code carried as an unturnable literal until 2026-09-13, kept as the starting point so behaviour did not change with the knob.','2026-12-13'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agents.tool_dispatch','per_tool_timeout_seconds','{"workflow_plan": 300}'::jsonb,'{"workflow_plan": 300}'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Per-tool deadlines, by tool name','Overrides the default deadline for named tools. `workflow_plan` is here because its build_agent action runs the agent-builder meta-agent end to end: at 120s it was cancelled mid-build on 2026-09-12 and a Masterwork Expert could not change how her desk''s writer thinks. Add a tool name only when its honest ceiling really is different.','agent','Measured against the live failure: the builder run that was cancelled at 120s. 300s leaves room for a full meta-agent build plus its one write.','2026-12-13'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('agents.tool_results','outbox_interval_ms','20000'::jsonb,'20000'::jsonb,'integer','ms','5000'::numeric,'120000'::numeric,NULL::jsonb,'Retry interval for undelivered tool answers','When an answer to an agent''s tool request could not be delivered right away, the browser keeps trying once per this interval until it lands or the tab closes. Slow on purpose: the fast path already retried for several seconds.','agent','Replaces OUTBOX_INTERVAL_MS = 20_000 in matrx-frontend features/agents/api/submit-tool-results.ts (KNOB MIRROR: the interval is armed at module load, before any async read can run).','2026-10-13'::date,'7e6f5a07-44a4-4568-8f1b-c035cd7bdb13'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('auto_ingest','background_urgency','"batch"'::jsonb,'"batch"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,'["live", "batch", "auto"]'::jsonb,'Background ingest urgency','How automatic ingestion (after a chat turn, on save, the scheduled sweepers) reaches AI providers when nobody is waiting. "batch" queues PDF page cleaning through provider Batch APIs at about half price and finishes the document when results land (typically minutes to hours). "auto" batches only documents at or above content_processing.clean_batch_min_pages. "live" pays full price for immediate results. Anything a person starts by hand is always live.','agent','census F7 (2026-09-14): nobody waits on background ingest; the urgency hint was being dropped and every batch caller paid live','2026-12-14'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('batch.deadline','escalation_headroom','1800'::jsonb,'1800'::jsonb,'number','seconds','300'::numeric,'21600'::numeric,NULL::jsonb,'Escalation headroom (seconds)','How early the supervisor escalates to still make the deadline. Provider cancel-settle latency (up to 10 min on OpenAI/Azure/Groq) is added ON TOP per provider, inside the remaining window.','agent','30 min > 10-min worst-case cancel settle + one live fill pass','2026-11-29'::date,'be47aa8f-c586-401e-88a9-138b6fad07de'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('batch.deadline','max_hours','10'::jsonb,'10'::jsonb,'number','hours','0.5'::numeric,'9999'::numeric,NULL::jsonb,'Default job deadline (hours)','Relative deadline applied when processing_mode = deadline and the caller set none. 9999 = MAX (no deadline).','agent','batch-deadline-escalation PLAN §1 worked example (10h multi-step promise)','2026-11-29'::date,'be47aa8f-c586-401e-88a9-138b6fad07de'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('batch.deadline','processing_mode','"batch"'::jsonb,'"batch"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,'["batch", "instant", "deadline"]'::jsonb,'Batch processing mode','Default routing for batchable AI work when the caller sets no explicit deadline: batch = pure batching (pre-deadline behaviour), instant = always live, deadline = apply the max_hours default.','agent','batch-deadline-escalation build 2026-08-29 — conservative default keeps today''s behaviour','2026-11-29'::date,'be47aa8f-c586-401e-88a9-138b6fad07de'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('batch.deadline','salvage_partial','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Salvage partial batch results','After a cancel, wait one settle window for the provider''s completed (discounted) results before filling synchronously — when the deadline still allows it.','agent','batch-deadline-escalation PLAN §4 default','2026-11-29'::date,'be47aa8f-c586-401e-88a9-138b6fad07de'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('batch.deadline','supervisor_enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Batch deadline supervisor enabled','Master switch for the batch_deadline_supervisor system tick (escalates provider batches that cannot make their deadline; runs frontier items live).','agent','Arman''s 2026-08-29 config ruling; the supervisor is the deadline promise''s enforcement and should run wherever deadline jobs exist.','2026-10-15'::date,'be47aa8f-c586-401e-88a9-138b6fad07de'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('batch.deadline','supervisor_tick_minutes','5'::jsonb,'5'::jsonb,'integer','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'Batch deadline supervisor cadence','Minutes between supervisor passes. The sch_trigger ticks every 5 minutes; this knob is the effective cadence the handler enforces.','agent','batch-deadline-escalation design: escalation_headroom is 30 min, so a 5-minute check loses at most 1/6 of the headroom.','2026-10-15'::date,'be47aa8f-c586-401e-88a9-138b6fad07de'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('cloud_browser.checkpoint','reverify_mode','"hash_only"'::jsonb,'"hash_only"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["full", "hash_only", "background"]'::jsonb,'How thoroughly a saved browser session is re-checked before it opens','Every cloud browser stores its session as one encrypted archive. "Fast" trusts the fingerprint taken when the session was saved and lets the browser itself confirm the bytes as it opens them. "Verify in the background" is the same speed, and re-reads the whole archive afterwards so you hear about a damaged session sooner. "Verify first" re-reads and decrypts the whole archive before the browser starts — the strongest check, and it adds the size of your saved session to every single start. In all three, a damaged session is retired and the previous one is opened instead.','agent','Default hash_only: the re-read this replaces is duplicated work — the browser worker performs the identical ciphertext and plaintext hash check on the bytes it installs, and the revision was already verified at capture. It bought only earlier notice and charged every start the full archive size: 404 MB for one live profile, growing ~20 MB per capture, and on 2026-09-16 run b01eb13a held its activation lease 211 s without one request reaching a healthy worker. Under hash_only the same corruption is caught by the party restoring the bytes and costs one retry; the fallback-to-a-prior-revision guard is preserved in every mode. full is offered unchanged for an organization that wants the check before dispatch, background for one that wants the speed and an early alarm.','2026-12-16'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{"help": "Affects how long a cloud browser takes to open. A damaged saved session is retired and the previous one opened in every setting.", "group": "Cloud Browser", "order": 20, "control": "select", "options": [{"label": "Fast (recommended)", "value": "hash_only"}, {"label": "Fast, verify in the background", "value": "background"}, {"label": "Verify the whole session first", "value": "full"}]}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('code.source_control','attachment_diff_characters','100000'::jsonb,'100000'::jsonb,'integer','characters','1000'::numeric,'1000000'::numeric,NULL::jsonb,'Maximum characters per Git diff attachment','The maximum staged or unstaged diff text attached to one Code chat snapshot. Omitted tail content is reported explicitly.','agent','A 100k-character diff is about 25k tokens and covers a substantial code review; larger generated or vendored changes must be inspected by path instead of consuming one chat attachment.','2026-10-27'::date,'15f30e38-3928-43c5-a336-fef91ad86ced'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('code.source_control','attachment_untracked_file_characters','25000'::jsonb,'25000'::jsonb,'integer','characters','1000'::numeric,'250000'::numeric,NULL::jsonb,'Maximum characters per untracked file attachment','The maximum text from any one untracked file included in a Code chat Git snapshot.','agent','A 25k-character file is enough for a typical source module while avoiding a single lockfile or generated artifact using the entire untracked budget.','2026-10-27'::date,'15f30e38-3928-43c5-a336-fef91ad86ced'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('code.source_control','attachment_untracked_file_count','20'::jsonb,'20'::jsonb,'integer','files','1'::numeric,'200'::numeric,NULL::jsonb,'Maximum untracked files read for a Git attachment','The number of untracked files Source Control may inspect for one Code chat Git snapshot. Remaining paths are attached as documented omissions.','agent','Twenty source files is enough for a normal feature-sized working set; the cap prevents an untracked dependency tree from turning one attach action into an unbounded read fan-out.','2026-10-27'::date,'15f30e38-3928-43c5-a336-fef91ad86ced'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('code.source_control','attachment_untracked_total_characters','100000'::jsonb,'100000'::jsonb,'integer','characters','1000'::numeric,'1000000'::numeric,NULL::jsonb,'Maximum total untracked attachment characters','The combined untracked text budget for one Code chat Git snapshot. Files outside it are named as omitted before content is read.','agent','100k characters is a generous review-sized total while keeping the snapshot bounded even when a repository has many new files.','2026-10-27'::date,'15f30e38-3928-43c5-a336-fef91ad86ced'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('coding_session_bridge','agent_run_daily_dispatch_ceiling','100'::jsonb,'100'::jsonb,'integer','runs per day','0'::numeric,'5000'::numeric,NULL::jsonb,'AI Matrx agent runs a coding tool may start each day','How many times each person may run one of your AI Matrx agents from inside a coding tool (Claude Code, Codex, Cursor) in a 24-hour period. Every run is a paid model call, and a coding agent can ask for them in a loop, so this is the backstop. An organization can lower it (0 switches the capability off for everyone in it) on conflict (feature,key) do nothing; each person can lower their own further, and nobody can raise it above the platform ceiling. When someone reaches it they are told the number, which rung set it, and that nothing was run.','agent','XT-02 (2026-09-14): agent_run became user-tier so every customer can trigger our agents from a coding host, and dispatch had no cost ceiling of any kind (plan-attack F11). The $250/48h Spend Explorer finding of 2026-09-12 came from an unbounded agent-chat loop of the same shape. 100/day/account is well above observed deliberate use and far below a runaway loop. XT-FIX-1 (2026-09-15): the user rung was proven INERT on production — a user-scope 0 still billed a run — so the rung is now permitted and the whole register row is lower_only, which is the only shape where a per-user rung cannot raise the spender''s own ceiling.','2026-12-14'::date,'7e6f5a07-44a4-4568-8f1b-c035cd7bdb13'::uuid,'{organization,user}'::text[],'lower_only',NULL::jsonb,'{"help": "Applies per person, per 24 hours. 0 turns off running AI Matrx agents from coding tools. An organization or a person can only lower this, never raise it.", "group": "Agents", "order": 20, "control": "number"}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('coding_session_bridge','agent_run_duplicate_wait_seconds','120'::jsonb,'120'::jsonb,'integer','seconds','0'::numeric,'900'::numeric,NULL::jsonb,'How long a repeated agent run waits for the first one''s answer','When a coding tool asks for the exact same AI Matrx agent run twice at once — a retry, or two copies of the same automation — only the first one actually runs. This is how long the second one waits for the first one''s answer before giving up and saying so. It never runs a second paid copy either way; 0 makes it give up immediately.','agent','XT-FIX-2 (2026-09-15): agent_run''s idempotency was a read-then-run check, so two identical concurrent calls produced one message and two billed model requests. The key is now claimed before the model call, and the loser waits for the winner. 120s is generous against our observed run times (seconds to under a minute) and well inside a coding host''s own tool timeout.','2026-12-15'::date,'7e6f5a07-44a4-4568-8f1b-c035cd7bdb13'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{"help": "Applies when the identical run is asked for twice at the same time. A second paid run never happens regardless of this value.", "group": "Agents", "order": 21, "control": "number"}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.intake','disposal_hold_days','30'::jsonb,'30'::jsonb,'integer','days','0'::numeric,'365'::numeric,NULL::jsonb,'Disposal hold-shelf days','How long a no_value item sits on the hold shelf before physical disposal. Client destruction windows are the org''s constraint to encode here.','agent','PLAN §5: the hold-shelf question; 30 days covers a monthly audit cycle.','2026-10-15'::date,'5ed43201-67fb-42f6-b5c1-8ac8282382fa'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.intake','gate1_mode','"exceptions_only"'::jsonb,'"exceptions_only"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["exceptions_only", "every_item"]'::jsonb,'Gate 1 review mode','Whether a human sees every intake item or only exceptions (skeptic disagreements, conditional_value, holds). REVIEW-RESPONSE §2.2 makes exceptions-only safe once the skeptic gate and hold shelf exist.','agent','REVIEW-RESPONSE §7 Q1 ruling: a knob, default exceptions-only per §2.2.','2026-10-15'::date,'5ed43201-67fb-42f6-b5c1-8ac8282382fa'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.intake','grading_standard','"r2v3"'::jsonb,'"r2v3"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["r2v3", "cosmetic_abc", "custom"]'::jsonb,'Grading standard','The condition-grading standard applied at intake. Was a column default; now a knob default (REVIEW-RESPONSE §6).','agent','REVIEW-RESPONSE: grading_standard defaulting r2v3 becomes a knob default.','2026-10-15'::date,'5ed43201-67fb-42f6-b5c1-8ac8282382fa'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.intake','policy_document','"platform-default"'::jsonb,'"platform-default"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Intake policy document reference','Reference to the org''s intake policy document (e.g. "normal wear is disregarded" — PROTOTYPE-CONCEPTS A2). "platform-default" resolves to the platform intake policy.','agent','PLAN §5: per-org intake policy is a doc ref, not prose in a knob.','2026-10-15'::date,'5ed43201-67fb-42f6-b5c1-8ac8282382fa'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.intake','skeptic_gate_enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Skeptic disposal gate','Run the skeptic model on 100% of no_value verdicts before disposal; disagreement goes to the human queue. Turning this off removes the recall safety net.','agent','REVIEW-RESPONSE §2.2: gate disposal, don''t sample it (~$10/week).','2026-10-15'::date,'5ed43201-67fb-42f6-b5c1-8ac8282382fa'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.intake','sweep_enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Intake sweep enabled','Master switch for the commerce_intake_sweep system tick. Off = the pipeline driver never runs; assets wait in their states. Cadence is the separate org-overridable trigger_cadence_minutes knob.','agent','Arman''s 2026-08-29 config ruling: existence is a knob, not code or a chat approval. On by default so flipping cadence is the only launch act.','2026-10-15'::date,'5ed43201-67fb-42f6-b5c1-8ac8282382fa'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.intake','trigger_cadence_minutes','30'::jsonb,'30'::jsonb,'integer','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'Intake trigger cadence','How often the intake pipeline sweeps for new items.','agent','Arman: "every thirty minutes" (PLAN §5).','2026-10-15'::date,'5ed43201-67fb-42f6-b5c1-8ac8282382fa'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.labels','default_template','"avery-5163"'::jsonb,'"avery-5163"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["avery-5160", "avery-5163", "avery-5164", "avery-22806", "avery-22807"]'::jsonb,'Default label template','The lib/label-print template preselected on the create-batch form and single-label prints. Avery 5163 (2in x 4in, 10-up) is the proven clothing-trial warehouse layout.','agent','PRINT-PACKAGE-DESIGN Decision 3: 5163 is the prior 2x5 layout preserved as a template; roomiest QR for scuffed warehouse scans.','2026-10-15'::date,'26ecc7f7-8675-4291-825c-4df2d4216c4b'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.labels','max_batch_size','1000'::jsonb,'1000'::jsonb,'integer','codes','1'::numeric,'10000'::numeric,NULL::jsonb,'Max codes per label batch','Ceiling on codes minted in one label batch. Bounds a single mint''s insert payload and one print run''s sheet count.','agent','1000 codes = 100 sheets of 10-up 5163 stock, a full box; larger runs should be deliberate multiple batches.','2026-10-15'::date,'26ecc7f7-8675-4291-825c-4df2d4216c4b'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.labels','qr_ec_level','"M"'::jsonb,'"M"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["L", "M", "Q"]'::jsonb,'QR error-correction level','Error correction burned into printed QR codes. M is the warehouse default; L only suits huge clean codes; Q costs density.','agent','PRINT-PACKAGE-DESIGN build recommendation: default ECC M, not L — warehouse labels get handled, scuffed, part-occluded.','2026-10-15'::date,'26ecc7f7-8675-4291-825c-4df2d4216c4b'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.market','comparable_cache_ttl_hours','6'::jsonb,'6'::jsonb,'number','hours','0.1'::numeric,'72'::numeric,NULL::jsonb,'Comparable cache TTL','Freshness ceiling on cached marketplace comparables. eBay-licence freshness clause — compliance, so platform-scoped: no org may loosen it.','agent','PLAN §5: eBay-licence freshness clause.','2026-10-15'::date,'0d386e84-7311-49ec-8c5b-64dca24f72a5'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.pipeline','cost_budget_gem_lane_usd','25.00'::jsonb,'25.00'::jsonb,'number','usd','0'::numeric,'1000'::numeric,NULL::jsonb,'Per-item spend ceiling, gem lane','Maximum AI spend on one gem candidate — gems get depth.','agent','PLAN §5 default $25.00.','2026-10-15'::date,'0d386e84-7311-49ec-8c5b-64dca24f72a5'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.pipeline','cost_budget_scrap_lane_usd','0.50'::jsonb,'0.50'::jsonb,'number','usd','0'::numeric,'100'::numeric,NULL::jsonb,'Per-item spend ceiling, scrap lane','Maximum AI spend on one low-value item. Items that would exceed it stop researching and take the cheap verdict.','agent','PLAN §5 default $0.50.','2026-10-15'::date,'0d386e84-7311-49ec-8c5b-64dca24f72a5'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.pipeline','deadline_max_hours','null'::jsonb,'null'::jsonb,'number','hours','0.5'::numeric,'9999'::numeric,NULL::jsonb,'Pipeline deadline (hours)','Relative deadline for processing_mode=deadline. JSON null = unset (no deadline; behaves as pure batch). A set value escalates via the batch supervisor.','agent','PLAN §5 lists no default ("—") on conflict (feature,key) do nothing; JSON null encodes unset without a magic number.','2026-10-15'::date,'0d386e84-7311-49ec-8c5b-64dca24f72a5'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.pipeline','processing_mode','"batch"'::jsonb,'"batch"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["batch", "instant", "deadline"]'::jsonb,'Pipeline processing mode','How a user''s commerce jobs route: batch (cheapest), instant (always live), deadline (batch with an escalation deadline). The commerce-lane counterpart of the platform batch.deadline.processing_mode router default.','agent','PLAN §5; batch is the cost-safe default.','2026-10-15'::date,'0d386e84-7311-49ec-8c5b-64dca24f72a5'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.pipeline','research_max_turns','8'::jsonb,'8'::jsonb,'integer','turns','1'::numeric,'50'::numeric,NULL::jsonb,'Research agent max turns','Caps the agentic research loop per item — the cost tail on hard-to-identify items.','agent','PLAN §5 default 8.','2026-10-15'::date,'0d386e84-7311-49ec-8c5b-64dca24f72a5'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.print_orders','allow_dev_origin_live_charges','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Allow live charges from a local development address','When off, a checkout that returns to localhost / 127.0.0.1 is refused while this server holds a live Stripe key. A local page talks to whichever backend the server toggle names, so a developer machine can reach production without knowing it — which is exactly how a real cs_live_ session was handed to a reviewer on 2026-09-07. When on, the order proceeds and every one is recorded for review.','agent','Arman 2026-09-11: settings, not blocks. Default false keeps the dev-origin law as the starting posture; an org that deliberately tests live money locally flips it and sees the record.','2026-10-26'::date,'26ecc7f7-8675-4291-825c-4df2d4216c4b'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.print_orders','require_mode_pairing','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Require Lulu and Stripe to be in the same mode','When on, a print order is refused unless the Lulu print environment (sandbox or production) and the Stripe key (test or live) are in the SAME mode. A mismatch either charges a real card for a book nobody prints, or prints and ships a real book nobody paid for. When off, the order proceeds and every one is recorded for review.','agent','Arman 2026-09-11 ruled the hard-coded refusal out and a setting in. Default true keeps the 2026-09-07 pairing law as the starting posture; the visibility half is the system_error record written on every permitted order.','2026-10-26'::date,'26ecc7f7-8675-4291-825c-4df2d4216c4b'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.printer_certification','failed_printer_behavior','"warn"'::jsonb,'"warn"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["warn", "block"]'::jsonb,'When a label printer has failed certification','What the label-batch print action does when the chosen printer and label stock have a FAILED row in the org''s printer certification register. "warn" shows a loud warning naming the printer, the stock and what failed, and lets the operator print anyway. "block" refuses the print and names this setting.','agent','Arman 2026-09-11: scare me with what is happening, do not block me. A failed certification predicts mis-registered labels, not lost money, so warn is the honest default and block is available to an org that has been burned.','2026-10-26'::date,'26ecc7f7-8675-4291-825c-4df2d4216c4b'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('commerce.publish','eps_sweep_cadence_hours','24'::jsonb,'24'::jsonb,'integer','hours','1'::numeric,'8760'::numeric,NULL::jsonb,'Orphaned-EPS sweep cadence','Hours between orphaned-EPS sweeps (24 = daily). The sch_trigger ticks hourly; this knob is the effective cadence the handler enforces.','agent','Daily is ample against a 30-day provider expiry; the sweep is a hygiene pass, not a correctness gate.','2026-10-15'::date,'0d386e84-7311-49ec-8c5b-64dca24f72a5'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
