insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('connectors','prompt.resurface_days','0'::jsonb,'0'::jsonb,'integer','days','0'::numeric,'365'::numeric,NULL::jsonb,'Bring the connector suggestion card back after (days)','How long after a person dismisses a provider''s connector suggestion card AI Matrx may show it again. 0 means never: a dismissal is final for that person.','agent','0 (never) because a dismissed suggestion that returns on its own is an advertisement, and the champion surfaces (ChatGPT/Codex connectors, Claude Code) all treat a dismissal as final. The knob exists because an organization rolling Google out to a team has a legitimate reason to re-offer it once, and that is the organization''s call, not ours. Range capped at a year so nobody can set a value that reads as "never" by accident.','2026-10-31'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('connectors','shared_account.member_default_level','"editor"'::jsonb,'"editor"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["viewer", "commenter", "editor", "admin"]'::jsonb,'What members may do with a shared connector account','The default level a member of the organization gets on a connector account an admin connected FOR the organization: viewer (see that it is connected), commenter, editor (use it — send after review, read the calendar, pick files), admin (also reconnect and disconnect it).','agent','editor because that is the point of connecting an account for the organization — the clinic''s info@ mailbox exists so the team can send from it after review, and a default of viewer would make the whole gesture do nothing. Reconnect and disconnect stay with admins, so the risky half is not handed out by default. Organization rung only: this is the organization''s policy about its own shared credential, and a member must not be able to raise their own level.','2026-10-31'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('content_ir.parity_sweep','batch_size','4'::jsonb,'4'::jsonb,'integer','cases','1'::numeric,'16'::numeric,NULL::jsonb,'Parity sweep cases per batch','How many rendering test cases the content parity sweep screenshots at once. Small so every case lands inside the browser viewport and reports its real height.','agent','Replaces BATCH_SIZE = 4 in matrx-frontend features/content-ir/sandbox/parity-sweep.ts (KNOB MIRROR: a Node-side harness with no browser knob client).','2026-10-13'::date,'2023f930-d49b-4060-a405-ba853d57ace8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('content_ir.studio','save_timeout_ms','20000'::jsonb,'20000'::jsonb,'integer','ms','3000'::numeric,'120000'::numeric,NULL::jsonb,'Studio save timeout','How long a save in the kind studio waits for the database before it gives up and tells the person nothing was confirmed saved. Long enough for a slow connection, short enough that nobody stares at a spinner forever.','agent','Replaces SAVE_TIMEOUT_MS = 20_000 in matrx-frontend features/content-ir/studio/store-kind-record.ts (KNOB MIRROR: the value is exported to a synchronous test contract).','2026-10-13'::date,'cf624dce-fe10-4e99-9489-37ed48cda401'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('content_processing','clean_batch_min_pages','40'::jsonb,'250'::jsonb,'integer','pages','1'::numeric,'100000'::numeric,NULL::jsonb,'Batch-clean threshold (pages)','At or above this page count, a document''s per-page LLM cleaning is queued through the platform Batch system (~50% price, results in hours) instead of running live. Below it, cleaning runs live so an interactive caller is not left waiting. Callers can always force either lane explicitly with clean_dispatch.','agent','Lowered 250 -> 40 on 2026-09-14 (batch wired-but-idle fix, census docs/handoffs/batch-candidates-census-2026-09-14.md Leg 3). Evidence: of the 26 documents processed in the 30 days to 2026-09-14, none reached 250 pages (0 batch cleans ever ran through this knob) on conflict (feature,key) do nothing; 12 had 1-9 pages, 4 had 46-87, 10 had 111-240. At 40, the 14 mid/large documents (the ones whose per-page cleaning is the real bill) take the ~50% Batch lane, while short uploads (<=9 pages) stay live and instant. A person who just uploaded a 40+ page PDF is not reading page-cleaning output in real time, and batch.deadline.max_hours escalation to live bounds the worst wait. Interactive callers that need the document now pass clean_dispatch="live" explicitly. Previous basis (250 = low end of the 250-4000 page range) never fired on real traffic. Review: raise it if users report mid-size uploads waiting hours; lower it if live RAG PDF Cleanup spend is still dominated by 10-40 page documents.','2026-10-14'::date,'31e2969a-9ec5-4433-b41a-70a9fd7d4d17'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('continued_access','access_cutoff_days','0'::jsonb,'0'::jsonb,'integer','days','0'::numeric,'3650'::numeric,NULL::jsonb,'Default access window after departure (days)','How long after departure the portal keeps answering, by default, for people departed from this organization. 0 means indefinitely -- the portal does not expire on its own.','agent','0 (indefinite) by default because Arman named keeping it on indefinitely as a first-class choice, and a silent expiry would quietly break the goodwill the portal exists to create. An org that wants a window sets one; the per-person access_cutoff_at overrides this.','2026-10-28'::date,'3b175e3a-0e55-4946-b360-f511ade38569'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('continued_access','portal_enabled','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Departed-member portal enabled','Whether this organization offers a portal to people whose membership has ended. OFF means a departed person sees nothing and no continued-access feature answers for them.','agent','OFF by default because this is an offering an organization makes, not a default the platform imposes. Arman: "It is something that we can make optionally available to our organizations, and they can choose which aspects of it they opt in for." An org that has not said yes has not said yes.','2026-10-28'::date,'3b175e3a-0e55-4946-b360-f511ade38569'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('continued_access','verification_consent_enabled','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Portal feature: employment/income verification consent','Whether a departed person may answer employment and income verification requests about themselves through the portal. Requires portal_enabled.','agent','OFF by default: per-feature opt-in is the shape Arman ruled -- "they can choose which aspects of it they opt in for." Turning the portal on is not consent to every aspect of it, and an income-disclosure channel is the last thing that should switch itself on.','2026-10-28'::date,'3b175e3a-0e55-4946-b360-f511ade38569'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','archive_bucket','"matrx-data-lifecycle-872515272894"'::jsonb,'"matrx-data-lifecycle-872515272894"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Cold-storage bucket','S3 bucket receiving archived Parquet. Must be in the same AWS region as the database so in-region transfer stays free.','agent','Created 2026-08-21 in us-east-1 alongside the migrated infrastructure, following the account-suffixed naming of the existing matrx-* buckets. Verified writable by the production identity aidream-dev (AmazonS3FullAccess).','2026-10-20'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','archive_max_rows_per_object','50000'::jsonb,'50000'::jsonb,'integer','rows','1000'::numeric,'1000000'::numeric,NULL::jsonb,'Rows per Parquet object','Upper bound on rows written into a single Parquet object before starting another.','agent','Parquet works best with row groups in the tens of thousands; 50k rows of a typical fact row lands roughly a few MB compressed, which is a comfortable size for Athena to scan and for a single upload to retry cheaply.','2026-10-20'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','archive_prefix_queryable','"lake"'::jsonb,'"lake"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Prefix for QUERYABLE archives','Objects here stay SQL-queryable through Athena and ride Intelligent-Tiering. This is the default for all real data.','agent','Arman ruled 2026-08-21 that actual data — including history — must remain queryable; only terminal dumps may be unqueryable. This prefix is the queryable half of that ruling.','2026-10-20'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','archive_prefix_terminal','"archive"'::jsonb,'"archive"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Prefix for TERMINAL dumps','Glacier-class storage for data nobody will query: very old dumps, and departed users/organizations held only in case of a recovery claim.','agent','The narrow exception Arman allowed for non-queryable storage. Deliberately NOT the default.','2026-10-20'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','max_entities_per_run','400'::jsonb,'400'::jsonb,'integer','entities','1'::numeric,'2000'::numeric,NULL::jsonb,'Entities considered per run','Upper bound on entities a single sweep walks, in delete-rank order.','agent','There are 336 active soft-delete entities today; 400 covers all of them with head-room, so a normal run is never truncated silently.','2026-10-20'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','max_owners_per_entity','200'::jsonb,'200'::jsonb,'integer','owners','1'::numeric,'10000'::numeric,NULL::jsonb,'Owners processed per entity per run','How many distinct owners of one entity a single run works through. A backlog drains across runs.','agent','Mirrors the education purge''s MAX_USERS_PER_BATCH of 100, doubled because this executor bounds rows per owner as well, so an owner batch can no longer be arbitrarily large.','2026-10-20'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','max_rows_per_batch','5000'::jsonb,'5000'::jsonb,'integer','rows','1'::numeric,'100000'::numeric,NULL::jsonb,'Rows deleted per transaction','Ceiling on one (entity, owner) delete transaction. Bounds lock duration and WAL for a single unit of work.','agent','The education purge bounds OWNERS per call but puts no ceiling on ROWS per owner, so one large account is one unbounded transaction. The largest owner on the platform today holds a few hundred rows in any single spine table, so 5000 is far above real use while still bounding a pathological account.','2026-10-20'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','policy_settling_hours','24'::jsonb,'24'::jsonb,'number','hours','1'::numeric,'720'::numeric,NULL::jsonb,'Retention policy settling period','How long a retention policy that can destroy data must sit visible before the resolver will honour it. Safety-increasing changes (disable, mode=never, legal hold) are exempt and apply instantly.','agent','Held at 24 hours — the value already encoded in the retention_policy.effective_from column default since the policy store shipped (2026-08-21). This migration changes WHERE the number lives and whether it is enforced, deliberately not the number itself, so nothing about the intended behaviour moves on the day enforcement lands.','2026-10-24'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','warm_bucket','"matrx-warm"'::jsonb,'"matrx-warm"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Warm-tier analytics bucket','The Supabase Analytics Bucket (Iceberg warehouse) the tiering worker writes to and the FDW reads from.','agent','Created 2026-08-25 during the tiered-storage Step 0 validation; catalog verified live.','2026-10-25'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('data_lifecycle','warn_days_default','9'::jsonb,'9'::jsonb,'integer','days','0'::numeric,'365'::numeric,NULL::jsonb,'Default warning window','How many days before permanent deletion a row enters the pending state and appears in the weekly digest, when a policy does not set its own.','agent','Arman ruled the warning stage should be small and simple. For the 30-day legal window this puts the notice at day 21, which he named explicitly; 9 days also spans at least one weekly digest send, so no user can miss their only notice.','2026-10-20'::date,'e5b45ceb-4508-4ef5-b89d-32b88e039f2e'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('durable_run','default_expected_ms','60000'::jsonb,'60000'::jsonb,'integer','ms','5000'::numeric,'3600000'::numeric,NULL::jsonb,'Default expected job length','When a screen starts a job without saying how long it should take, this is what it promises the person. One minute is what these dialogs already said out loud.','agent','Replaces DEFAULT_EXPECTED_MS = 60_000 in matrx-frontend lib/durable-run/useDurableRun.ts (KNOB MIRROR: an exported render-path default).','2026-10-13'::date,'13b4cb92-6fb5-41b6-833e-185f2e8d9c1b'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('durable_run','elapsed_tick_ms','1000'::jsonb,'1000'::jsonb,'integer','ms','250'::numeric,'10000'::numeric,NULL::jsonb,'Elapsed clock tick','How often the elapsed-time clock on a running job moves.','agent','Replaces ELAPSED_TICK_MS = 1_000 in matrx-frontend lib/durable-run/useDurableRun.ts (KNOB MIRROR: armed inside a React effect).','2026-10-13'::date,'13b4cb92-6fb5-41b6-833e-185f2e8d9c1b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','items_per_segment_deck','8'::jsonb,'8'::jsonb,'integer','cards','1'::numeric,'50'::numeric,NULL::jsonb,'Flashcards per segment','Cards requested for each coverage segment at standard depth.','agent','Eight cards per 3000 characters is roughly one card per lecture slide, which is the density students hand-build. The reported 77-slide source yields ~64 cards instead of the 10 it produced.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','items_per_segment_memory_aid','3'::jsonb,'3'::jsonb,'integer','aids','1'::numeric,'20'::numeric,NULL::jsonb,'Memory aids per segment','Mnemonics / analogies requested for each coverage segment at standard depth.','agent','Memory aids are only worth having for material that actually resists recall; three per section keeps them selective while still reaching every section, instead of the four total the whole document used to get.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','items_per_segment_mind_map','7'::jsonb,'7'::jsonb,'integer','nodes','1'::numeric,'40'::numeric,NULL::jsonb,'Mind-map nodes per segment','Nodes requested for each coverage segment at standard depth.','agent','Seven nodes per section gives a branch with real structure under it rather than a single label, and keeps the whole map (~56 nodes for a large source) legible.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','items_per_segment_practice_test','7'::jsonb,'7'::jsonb,'integer','questions','1'::numeric,'50'::numeric,NULL::jsonb,'Practice-test questions per segment','Questions requested for each coverage segment at standard depth.','agent','A practice test should feel like the real exam, so it runs denser than the quiz: ~56 questions over a large source, in exam territory.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','items_per_segment_quiz','5'::jsonb,'5'::jsonb,'integer','questions','1'::numeric,'50'::numeric,NULL::jsonb,'Quiz questions per segment','Questions requested for each coverage segment at standard depth.','agent','A quiz is a check, not a full sweep: five per segment (~40 for a large source) is a sitting-length quiz that still touches every section.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','items_per_segment_summary','4'::jsonb,'4'::jsonb,'integer','key points','1'::numeric,'20'::numeric,NULL::jsonb,'Summary key points per segment','Key points requested for each coverage segment at standard depth.','agent','Four points per section is a revision sheet a student can read end to end: ~32 points for a large source, against the 5 the whole 77-slide deck used to get.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','max_items_total','150'::jsonb,'150'::jsonb,'integer','items','5'::numeric,'1000'::numeric,NULL::jsonb,'Maximum items per artifact','Ceiling on cards / questions / mnemonics / key points a single generated artifact may contain, however large the source or however much the student asks for.','agent','A 150-card deck is already more than a student reviews in a sitting; past that the honest answer is a second deck, not a longer one. Set well above the ~64 a large source produces so the ceiling is a backstop, not the operating point.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','max_segments','40'::jsonb,'40'::jsonb,'integer','segments','1'::numeric,'200'::numeric,NULL::jsonb,'Maximum coverage segments','Blast-radius backstop on how many agent calls one artifact may fan out to. A source with more sections is re-packed evenly into this many, never truncated.','agent','At 3000 chars per segment this covers a ~120k-character source (a full textbook chapter set) in one kit. Beyond that the per-run cost and wall-clock stop being reasonable for an interactive flow, so we pack denser rather than drop the tail.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','max_source_chars','400000'::jsonb,'400000'::jsonb,'integer','characters','1000'::numeric,'5000000'::numeric,NULL::jsonb,'Maximum source length read into a kit','How much extracted text one study kit will read from an uploaded document. Anything past this is not read, and the student is told so.','agent','This was a hardcoded 48,000 because the whole source went into ONE model call, so a 90-page PDF was silently cut to roughly its first third. Generation is now segmented and no model sees the whole document at once, so the ceiling is a blast-radius backstop rather than a context limit: 400k characters is about 200 dense pages, which covers a full textbook chapter set while still bounding a single interactive run.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','min_items_total','6'::jsonb,'6'::jsonb,'integer','items','1'::numeric,'100'::numeric,NULL::jsonb,'Minimum items per artifact','Floor so a short paste still produces a usable artifact rather than one or two items.','agent','Below six items a deck or quiz is not worth opening. A source too thin to support six real items still returns fewer, because the grounding rule forbids padding: this is a floor on what we ASK for, not on what we save.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','segment_concurrency','4'::jsonb,'4'::jsonb,'integer','calls','1'::numeric,'16'::numeric,NULL::jsonb,'Concurrent segment calls','How many segment generations run at once within a single artifact. The kit also fans out across targets, so the real in-flight count is this times the number of selected targets.','agent','Seven kit targets times four segments is 28 concurrent agent runs, which is the most the execution system absorbs without the student watching everything slow down together. Raise only with rate-limit headroom measured.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('education.study_kit','segment_target_chars','3000'::jsonb,'3000'::jsonb,'integer','characters','500'::numeric,'20000'::numeric,NULL::jsonb,'Coverage segment size','How much source text one generator call is responsible for. Smaller means better coverage and more calls; larger means fewer calls and more skipped material.','agent','A model reliably attends to ~3k characters (~750 tokens) of dense study material at a time. The reported 23.5k-character, 77-slide source becomes 8 segments, so no slide sits in the tail of a call that already had enough to say.','2026-10-05'::date,'92a5110d-24e1-4353-86e8-24406ccfe70b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('emergency_access','access_log_page_size','100'::jsonb,'100'::jsonb,'integer','entries','10'::numeric,'500'::numeric,NULL::jsonb,'Emergency access log entries shown','How many of the most recent emergency-access log entries the feed shows before it says older entries are kept but not listed.','agent','Replaces PAGE_SIZE = 100 in matrx-frontend features/emergency-access/components/AccessLogFeed.tsx (KNOB MIRROR: a synchronous render path).','2026-10-13'::date,'3b175e3a-0e55-4946-b360-f511ade38569'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
