insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.ai_exposure_default','"allowed"'::jsonb,'"allowed"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["allowed", "aggregate_only", "never"]'::jsonb,'Default AI exposure','Default ai_exposure for a new definition.','agent','Forced to never when sensitivity_tier = restricted - enforced by a table CHECK, not by convention.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Custom fields enabled','Whether a registered target may carry tenant-defined fields at all.','agent','Participation is data, not a hardcoded list (RD-2). True per registered target; the allowlist row is the real gate.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.max_custom_bytes_per_row','65536'::jsonb,'65536'::jsonb,'integer','bytes','1024'::numeric,'1048576'::numeric,NULL::jsonb,'Max custom bytes per row','Ceiling on one row''s custom jsonb, counted by platform.cf_item_byte_size.','agent','Keeps a row''s jsonb inside a page-ish budget; the CMS byte-cap precedent.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.max_fields_per_target','50'::jsonb,'50'::jsonb,'integer','fields','1'::numeric,'500'::numeric,NULL::jsonb,'Max custom fields per target','Ceiling on live definitions for one token in one organization.','agent','Between BambooHR''s small HR set and Salesforce''s 25-800 per edition; generous for real HR use, far under index pain.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.max_keys_per_row','200'::jsonb,'200'::jsonb,'integer','keys','1'::numeric,'2000'::numeric,NULL::jsonb,'Max custom keys per row','Backstop against unbounded key growth in one row.','agent','The named jsonb anti-pattern is an unbounded key set; 200 is far above any real form and far below pain.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.max_option_label_chars','200'::jsonb,'200'::jsonb,'integer','characters','1'::numeric,'3000'::numeric,NULL::jsonb,'Max option label length','Ceiling on one option label.','agent','HubSpot allows 3,000; 200 is a label, not a document.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.max_options_per_select','500'::jsonb,'500'::jsonb,'integer','options','1'::numeric,'5000'::numeric,NULL::jsonb,'Max options per select','Ceiling on a single_select / multi_select option list.','agent','Attio allows 5,000; 500 keeps a dropdown usable and the validation fixture finite.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.multi_select_max_values','50'::jsonb,'50'::jsonb,'integer','values','1'::numeric,'500'::numeric,NULL::jsonb,'Default multi_select max values','Applied when a definition declares no max_values.','agent','A multi-select a person actually operates; a definition may declare its own lower value.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.promoted_indexes_per_target','12'::jsonb,'12'::jsonb,'integer','indexes','0'::numeric,'50'::numeric,NULL::jsonb,'Promoted indexes per target','Ceiling on per-org partial expression indexes on one target token.','agent','Index maintenance is a shared cost paid by every org on the table; hitting this is the make-it-a-real-column signal.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','custom_fields.validation_mode','"advisory"'::jsonb,'"advisory"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["advisory", "strict"]'::jsonb,'Default validation mode','Mode handed to platform.validate_custom_values when a target declares none.','agent','Matches the CMS default; strict is opt-in per target so adopting the primitive never breaks an existing writer.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','tier3.enabled','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Tier 3 (ext_<tenant> schemas) enabled','THE GATE of SPEC-EXTENSIBILITY 5.','agent','Section 5''s gate expressed as a knob so it is visible and auditable. No org override: opening it is a named-enterprise-requirement decision, never a per-tenant toggle.','2026-10-25'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('extensibility','user_tables.history_retention_floor_days','30'::jsonb,'30'::jsonb,'integer','days','30'::numeric,'3650'::numeric,NULL::jsonb,'How long a table row''s edit history is kept, at the least','Every edit to a row in a user-defined table is kept in that row''s history. Beyond the two most recent versions, a version is deleted once it is older than this. Thirty days is the platform floor and an organization may only RAISE it, never lower it — the history is the only copy of a value a column type change could not keep, so a shorter window is a data-loss window. Raise it for organizations that must be able to look further back.','agent','Arman''s ruled floor (Data Doctrine Rule 10, 2026-09-10), replacing the 14-day literal that lived inside udt_dataset_row_versions_trim() (DD-244 / G10).','2026-12-15'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization}'::text[],'raise_only','30'::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('google.marketing','freshness_warning_hours','72'::jsonb,'72'::jsonb,'integer','hours','1'::numeric,'720'::numeric,NULL::jsonb,'Google data — warn when the last pull is older than','How old the last successful pull from Google (Search Console or Analytics) may be before every screen showing those numbers marks them stale. The freshness line always states when the data is from; this only decides when it turns into a warning.','agent','GSC API lag is 2–3 days and our sweep runs nightly, so a healthy site sits ~48h behind; 72 hours is the first threshold that fires only when a nightly run was actually missed, matching seo.gsc_ingestion_health (2-day lag + 2 missed nights).','2026-10-31'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('google.rollout','read_only_sweep_phase','"internal_test"'::jsonb,'"internal_test"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["internal_test", "available"]'::jsonb,'Who can turn on Google Contacts, Calendar, Tasks, Tag Manager and YouTube Analytics','These five Google products are read-only and already approved by Google. "Internal testing only" keeps them to the AI Matrx review account while we finish certifying the public rollout; everyone else sees the product with no switch and the line "Turns on automatically when ready for your account". "Available to everyone" opens all five immediately, with no release needed — the change reaches every server within a minute and the Connect Google dialog starts offering them.','agent','Google certified the scopes 2026-09-12; public rollout awaits product certification (Arman''s gate). Default internal_test, which is the phase the code shipped with: seeding available would open five sensitive Google products the instant this row landed, and that decision is the one this knob exists to keep out of a deploy. Platform-locked because a customer organization cannot grant itself a product AI Matrx has not certified publicly.','2026-10-31'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,E'{"help": "Contacts, Calendar, Tasks, Tag Manager and YouTube Analytics. Switching to \\"Available to everyone\\" needs no deployment.", "group": "Google", "order": 10, "control": "select", "options": [{"label": "Internal testing only", "value": "internal_test"}, {"label": "Available to everyone", "value": "available"}]}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','drain_cap_per_pass','10'::jsonb,'10'::jsonb,'integer','reviews','1'::numeric,'200'::numeric,NULL::jsonb,'Most Hindsight reviews started in one scheduled pass','The scheduler periodically looks for watched items that are due a review. This is how many it will review in one pass; the rest stay due and are picked up on the next pass. It spreads review spend and load over time rather than letting a backlog run all at once.','agent','Carried over unchanged from the Python constant DRAIN_CAP_PER_PASS = 10 (hindsight/types.py). Reviews are the most expensive thing the drain does, so a backlog is worked down over several passes instead of in one burst.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','internal_affairs_max_findings_per_pass','3'::jsonb,'3'::jsonb,'integer','findings','0'::numeric,'20'::numeric,NULL::jsonb,'Most Internal Affairs findings filed per pass','Internal Affairs is the part of Hindsight that questions Hindsight''s own past changes (a change that was reverted too often, got more expensive, or keeps producing unused suggestions). This is how many of those findings one pass files, most serious first; the rest are logged by name and wait for a later pass.','agent','Carried over unchanged from the Python constant IA_MAX_FINDINGS_PER_PASS = 3 (hindsight/types.py). Each finding asks a person to reconsider work the platform already did, so the ceiling is kept tight.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','loop_waste_max_findings_per_pass','3'::jsonb,'3'::jsonb,'integer','findings','0'::numeric,'20'::numeric,NULL::jsonb,'Most loop-waste findings filed per pass','The loop-waste detector finds agent runs that kept retrying or iterating without progress and prices what that cost. This is how many of those cases one pass files as findings, most expensive first; the rest are logged by name and wait.','agent','Carried over unchanged from the Python constant LOOP_WASTE_MAX_FINDINGS_PER_PASS = 3 (hindsight/types.py). Findings cost a person''s attention; the most expensive cases are always the ones kept.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','loop_waste_max_judged_cases_per_pass','2'::jsonb,'2'::jsonb,'integer','cases','0'::numeric,'20'::numeric,NULL::jsonb,'Most loop-waste cases a model judges per pass','For runs that looked like they iterated without progress, the detector asks a model to compare the iterations before filing. This is how many of those paid comparisons one pass makes; later cases are filed without the comparison.','agent','Carried over unchanged from the Python constant LOOP_WASTE_MAX_JUDGED_CASES_PER_PASS = 2 (hindsight/types.py). The deterministic detectors cost nothing; this bounds the only paid step in the pass.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','max_findings_per_review','6'::jsonb,'6'::jsonb,'integer','findings','1'::numeric,'30'::numeric,NULL::jsonb,'Most findings one Hindsight review may file','A Hindsight review can suggest several improvements at once. This is how many of them one review keeps; any beyond it are dropped before they are saved. Each kept finding becomes something a person is asked to look at, so this bounds how much reading one review can create.','agent','Carried over unchanged from the Python constant MAX_FINDINGS_PER_REVIEW = 6 (hindsight/types.py). The Producer Yield register measured the flagship reviewer at 2.1% acceptance, so more findings per review would mostly add unread items; 6 keeps the strongest few.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','max_replay_findings_per_review','2'::jsonb,'2'::jsonb,'integer','findings','0'::numeric,'10'::numeric,NULL::jsonb,'How many findings per review get automatic replay evidence','When a review suggests a change the platform can apply by itself, Hindsight re-runs real past conversations or workflow runs with that change so the suggestion arrives with evidence. This is how many of a review''s findings get that treatment; the rest arrive without replay evidence. Every replay is a full, billed agent run. Zero turns automatic replay evidence off.','agent','Carried over unchanged from the Python constant MAX_REPLAY_FINDINGS_PER_REVIEW = 2 (hindsight/types.py). With max_replays_per_finding = 3 the worst case is 6 full agent runs per review, bounded by the per-item daily spend ceiling.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','max_replays_per_finding','3'::jsonb,'3'::jsonb,'integer','replays','0'::numeric,'10'::numeric,NULL::jsonb,'How many past runs are replayed to evidence one finding','For a finding that gets automatic replay evidence, this is how many real past runs are re-run with the suggested change. More replays make the evidence more convincing and cost more; each one is a full, billed agent run.','agent','Carried over unchanged from the Python constant MAX_REPLAYS_PER_FINDING = 3 (hindsight/types.py). One replay is anecdote; three shows whether the change holds across different inputs at bounded cost.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','max_review_spend_per_enrollment_per_day_usd','5'::jsonb,'5'::jsonb,'number','usd','0.5'::numeric,'500'::numeric,NULL::jsonb,'Most Hindsight may spend reviewing one watched item in a day','The total model cost of Hindsight reviews and review discussions for one watched item in any rolling 24 hours. Once it is reached, new reviews and discussion turns for that item are refused with a plain message until earlier spend leaves the window. It applies to everyone, admins included.','agent','Carried over unchanged from the Python constant MAX_REVIEW_SPEND_PER_ENROLLMENT_PER_DAY_USD = 5.0 (hindsight/types.py). A review bundle is capped at 220,000 characters (~55k input tokens), so a single frontier review costs well under a dollar; $5 admits every review the count ceiling allows plus discussion, and still stops a runaway loop within the day.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','max_reviews_per_enrollment_per_day','8'::jsonb,'8'::jsonb,'integer','reviews','1'::numeric,'100'::numeric,NULL::jsonb,'Most Hindsight reviews one watched item may run in a day','Hindsight reviews a watched agent, workflow or tool by having a frontier model read its real recent runs, and every review costs real money. This is how many reviews one watched item may run in any rolling 24 hours, counting finished, failed and still-running reviews. Past it, "Review now" and the scheduled drain are refused with a plain message until the window rolls forward. Follow-up discussion on an existing review is NOT limited by this count, only by the daily spend ceiling.','agent','Carried over unchanged from the Python constant MAX_REVIEWS_PER_ENROLLMENT_PER_DAY = 8 (hindsight/types.py). The scheduled drain reviews an item at most every review_cooldown_hours (6), i.e. about 4 a day, so 8 leaves room for the same number of manual "Review now" runs before anything is refused — the ceiling exists to stop a click loop, not ordinary use.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','proof_default_samples','2'::jsonb,'2'::jsonb,'integer','samples','1'::numeric,'20'::numeric,NULL::jsonb,'Repeats per side when Hindsight proves a finding','Proving a finding re-sends a real recorded model call twice over: once unchanged and once with the suggested fix, each repeated this many times so the spread between answers shows. Every repeat is a billed model call, so one proof costs twice this number in calls. It applies to every automatic proof and to a manual proof that does not ask for a specific number. A value above the model-call replay repeat ceiling (wire_replay_max_samples) is reduced to that ceiling.','agent','Carried over unchanged from the Python constant PROOF_DEFAULT_SAMPLES = 2 (hindsight/types.py). Two, not the replay default of three: a proof runs a control arm AND a candidate arm, so the paid-call count is 2 × samples; two per arm still shows per-sample spread (one sample is never evidence) at two thirds the cost, and proofs run far more often than operator-initiated replays. Range 1–20 matches wire_replay_max_samples, which clamps it at replay time.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','proof_max_per_detector_pass','1'::jsonb,'1'::jsonb,'integer','proofs','0'::numeric,'10'::numeric,NULL::jsonb,'Most automatic proofs the loop-waste detector runs per pass','When the loop-waste detector files a finding, it can automatically prove it by replaying a real recorded call with and without the fix. This is how many of those proofs one detector pass runs; the rest are logged by name as not yet proven. Each proof is a pair of billed replays. Zero turns automatic proofs off.','agent','Carried over unchanged from the Python constant PROOF_MAX_PER_DETECTOR_PASS = 1 (hindsight/types.py). The detector runs on a schedule and each proof costs 2 × the proof sample count in paid calls, so one per pass keeps a background sweep from becoming a spend loop.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','review_cooldown_hours','6'::jsonb,'6'::jsonb,'integer','hours','0'::numeric,'168'::numeric,NULL::jsonb,'Minimum wait between scheduled Hindsight reviews of one watched item','After a review completes, the scheduled drain will not review the same watched item again until this many hours have passed, however many new runs arrive. Lower means fresher reviews and more spend; higher means fewer, larger reviews.','agent','Carried over unchanged from the Python constant REVIEW_COOLDOWN_HOURS = 6 (hindsight/types.py): about four scheduled reviews a day per item at most, half of max_reviews_per_enrollment_per_day, so scheduled reviews alone never exhaust the daily count.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','tool_sweep_budget_tools','8'::jsonb,'8'::jsonb,'integer','tools','1'::numeric,'100'::numeric,NULL::jsonb,'Failing-tool count above which the sweep reports itself over budget','When more failing tools qualify for review than this, the tool-failure sweep marks the pass as over budget in its report, so a growing backlog of broken tools is visible rather than quietly deferred.','agent','Carried over unchanged from the Python constant TOOL_SWEEP_BUDGET_TOOLS = 8 (hindsight/types.py).','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','tool_sweep_max_enrollments_per_pass','2'::jsonb,'2'::jsonb,'integer','tools','0'::numeric,'20'::numeric,NULL::jsonb,'Most failing tools queued for review per sweep','The tool-failure sweep looks for tools that failed repeatedly and queues them for a Hindsight review. This is how many tools one sweep queues, highest priority first; the others are logged by name and wait for a later sweep. Each queued tool leads to a billed review. Zero pauses new tool reviews.','agent','Carried over unchanged from the Python constant TOOL_SWEEP_MAX_ENROLLMENTS_PER_PASS = 2 (hindsight/types.py), the hard spend ceiling on this sweep.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','wire_replay_max_arms','4'::jsonb,'4'::jsonb,'integer','arms','2'::numeric,'10'::numeric,NULL::jsonb,'Most variations one model-call replay may compare','A model-call replay re-sends one recorded call to the model unchanged (the control) and with alternative settings, to compare them. This is the total number of variations one replay may run, the control included; extra requested variations are dropped and the replay says so.','agent','Carried over unchanged from the Python constant WIRE_REPLAY_MAX_ARMS = 4 (hindsight/types.py): the control plus three candidates. Arms × samples is the worst-case paid call count of one replay (4 × 5 = 20). The minimum of 2 keeps at least one candidate beside the always-present control.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hindsight','wire_replay_max_samples','5'::jsonb,'5'::jsonb,'integer','samples','1'::numeric,'20'::numeric,NULL::jsonb,'Most repeats per variation in a model-call replay','Model answers vary between identical calls, so a replay sends each variation several times to see the spread. This is the most repeats a replay or a regression-case check may request per variation; a larger request is reduced to it. Every repeat is a billed model call.','agent','Carried over unchanged from the Python constant WIRE_REPLAY_MAX_SAMPLES = 5 (hindsight/types.py). Three is the default request and one sample is never evidence; 5 allows a tighter read on a noisy call while wire_replay_max_arms × this stays at 20 paid calls.','2026-10-29'::date,'1d54ef5c-d13b-43ee-b3a5-476f894b72e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hitl.google','agent_import','"mode_4"'::jsonb,'"mode_4"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["mode_1", "mode_2", "mode_3", "mode_4", "mode_5"]'::jsonb,'Imports an agent proposes (Google Contacts, Google Tasks)','What happens when an agent proposes bringing a Google contact or task into Matrx. Mode 4 shows you the fields it would write, and nothing lands until you accept.','agent','Mode 4 because an import writes into records other people read afterwards, and a wrong field silently becomes the truth of a Person. Proposals, not silent writes (PLAN §4.5, §4.7).','2026-10-31'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hitl.google','attended_file_write','"mode_1"'::jsonb,'"mode_1"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["mode_1", "mode_2", "mode_3", "mode_4", "mode_5"]'::jsonb,'Google file writes the person asked for','What happens when someone asks an agent, in the moment, to change one of their own Google Docs or Sheets. Mode 1 applies it; mode 4 puts every change in the approval queue first.','agent','Mode 1 because the person asked for it on their own file and Google keeps its own version history, so the change is reversible by the owner without us. Making an attended edit wait on an approval queue would mean the person approving is the person who just asked — a control that governs nobody (PLAN §7).','2026-10-31'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hitl.google','review_timeout_hours','24'::jsonb,'24'::jsonb,'integer','hours','1'::numeric,'720'::numeric,NULL::jsonb,'How long a review waits before it applies itself (mode 3)','When a capability is set to "review with a timeout", this is how many hours a pending item waits for a person before it applies on its own. The queue shows the exact time it will fire.','agent','24 hours because it is one business day: long enough that a person who works days does not lose the item to a clock, short enough that a mode-3 capability still moves. HITL policy rule 4 requires the instant to be visible before it fires, and the queue prints it.','2026-10-31'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hitl.google','unattended_file_write','"mode_4"'::jsonb,'"mode_4"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["mode_1", "mode_2", "mode_3", "mode_4", "mode_5"]'::jsonb,'Google file writes from a workflow or a schedule','What happens when a workflow, schedule or background run wants to write to a Google Doc or Sheet with nobody watching. Mode 4 means nothing is written until a person with edit rights approves it in the approval queue.','agent','Mode 4 because nobody is on screen to see the consequence, which is exactly the case the destructive-and-expensive-actions law reserves review for. A clock-driven write to a customer''s spreadsheet has no undo the customer knows about.','2026-10-31'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.access','break_glass_grant_ttl_minutes','60'::jsonb,'60'::jsonb,'integer','minutes','5'::numeric,'480'::numeric,NULL::jsonb,'Break-glass grant TTL','How long a break-glass grant lives before iam.permissions.expires_at kills it.','agent','Break-glass writes a REAL time-boxed grant, not a one-shot read, because a one-shot that forces twelve more break-glass calls is over-tightening dressed as rigour. An hour is one working session.','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.access','comp_visibility_for_managers','"none"'::jsonb,'"none"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["none", "band_only"]'::jsonb,'Compensation visibility for managers','What a manager may see of a report''s pay.','agent','`full` IS NOT A PERMITTED VALUE and the allowed set is what enforces it — a manager who can read exact pay makes every comp conversation in the org a negotiation over a number they were never given. `band_only` exists for orgs that run manager-led compensation planning.','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.access','employee_can_see_own_access_log','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Employee can see their own access log','Whether an employee may read who looked at their record.','agent','No competitor does this. It is the right default for a platform whose owner insists the right people get in without blinking — and the fastest way an over-tightened or over-loose grant gets noticed is the person it is about seeing it.','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.access','manager_visibility_depth','2'::jsonb,'2'::jsonb,'integer',NULL,'0'::numeric,'10'::numeric,NULL::jsonb,'Manager visibility depth','How far DOWN a manager may read their subtree. Direct + skip-level by default.','agent','This is the ONE depth limit in the access design that is a deliberate cap rather than a bug: a VP does not need every timesheet nine levels below, and materialising that grant set is the one place this design would not scale. Approval ROUTING depth is a different number and is unbounded (§1.3c).','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.access','manager_visibility_depth_confidential','0'::jsonb,'0'::jsonb,'integer',NULL,'0'::numeric,'3'::numeric,NULL::jsonb,'Manager visibility depth (confidential)','How far down a manager may reach Confidential-tier rows. Zero means never.','agent','A manager never reads pay, identity or medical. Zero is the default and the only value we would defend; the knob exists because AD-12 forbids a hard-coded ceiling, not because we expect anyone to raise it.','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.access','review_visibility_skip_level','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Skip-level review visibility','Whether a manager''s manager may read a performance review.','agent','The skip-level is who a review escalation actually goes to; hiding it from them makes calibration impossible. Orgs with a stricter review confidentiality posture turn it off.','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.access','ssn_reveal_daily_alert_threshold','5'::jsonb,'5'::jsonb,'integer',NULL,'1'::numeric,'100'::numeric,NULL::jsonb,'SSN reveal daily alert threshold','Reveals by one actor in one day before an alert fires.','agent','Legitimate payroll work reveals a handful; a script reveals hundreds. Five separates them without paging anyone doing their job.','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.approvals','address_change_approver','"hr_admin"'::jsonb,'"hr_admin"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["hr_admin", "hr_owner", "manager"]'::jsonb,'Address change approver','Who approves an employee''s home-address change.','agent','NOT the manager by default: home address is Confidential tier and a manager holds no identity.read, so routing it to them would be asking someone to approve a value they may not read.','2026-11-24'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.approvals','delegation_max_depth','1'::jsonb,'1'::jsonb,'integer',NULL,'0'::numeric,'3'::numeric,NULL::jsonb,'Delegation maximum depth','How many times an authority may be re-delegated.','agent','Re-delegation is how an authority ends up somewhere nobody chose. One hop keeps the delegator answerable for who holds it.','2026-11-24'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.approvals','delegation_max_horizon_days','90'::jsonb,'90'::jsonb,'integer','days','1'::numeric,'365'::numeric,NULL::jsonb,'Delegation maximum horizon','Longest window a delegated authority may cover.','agent','A delegation longer than a quarter is a reassignment nobody made explicit. Ninety days covers a sabbatical without becoming permanent by neglect.','2026-11-24'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.approvals','escalation_hours','72'::jsonb,'72'::jsonb,'integer','hours','1'::numeric,'720'::numeric,NULL::jsonb,'Approval escalation window','Hours before an unanswered approval escalates.','agent','Three days spans a weekend, which is when most approvals sit. Shorter escalates noise; longer is how a request quietly dies.','2026-11-24'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
