insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.domain_wide','employees_record_anomaly_scan_posture','"recommend"'::jsonb,'"recommend"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Employees Record Anomaly Scan Posture','Every finding it surfaces is a fact a human must act on — an expiring work permit, an exempt position under the salary threshold, a spell with no compensation row. The deterministic checks are plain queries (D6: a rule-checkable fact is never routed through a model) on conflict (feature,key) do nothing; the mandate ranks, clusters and explains them.','agent','Every finding it surfaces is a fact a human must act on — an expiring work permit, an exempt position under the salary threshold, a spell with no compensation row. The deterministic checks are plain queries (D6: a rule-checkable fact is never routed through a model); the mandate ranks, clusters and explains them.','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.domain_wide','employees_verification_letter_draft_posture','"review_and_comment"'::jsonb,'"review_and_comment"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Employees Verification Letter Draft Posture','A letter is an assertion the org is held to. The mandate drafts the BODY; what is disclosed and whether consent exists are settled before it is called, and a human approves before the PDF is rendered. `apply_final` is deliberately not a permitted value.','agent','A letter is an assertion the org is held to. The mandate drafts the BODY; what is disclosed and whether consent exists are settled before it is called, and a human approves before the PDF is rendered. `apply_final` is deliberately not a permitted value.','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.domain_wide','retention_warning_days','30'::jsonb,'30'::jsonb,'integer','days','7'::numeric,'180'::numeric,NULL::jsonb,'Retention warning horizon','Days before a disposition becomes due that the compliance surface warns.','agent','This controls only the WARNING horizon, never the statutory floor — the floors are hr.retention_rule rows with citations (§15).','2026-11-24'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
