insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.domain_wide','tasks_default_scope_employee','"mine"'::jsonb,'"mine"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["mine", "team", "queue"]'::jsonb,'Default inbox scope — employee','Which /hr/tasks scope an employee lands on. Scopes they do not hold are absent, not disabled.','agent','SPEC-UI-IA §5.9 / §10','2027-02-26'::date,'9872a297-a007-465e-98d4-37aae9ba3174'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
