insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','activation_seeds','["earning_codes", "deduction_codes", "categories_dimensions", "holiday_calendar"]'::jsonb,'["earning_codes", "deduction_codes", "categories_dimensions", "holiday_calendar"]'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Activation Seeds','All four on: an employer activated with no earning codes cannot record an hour, and discovering that on the first payroll is the worst possible moment. An org migrating from another system turns individual seeds off so its own codes are not shadowed.','agent','All four on: an employer activated with no earning codes cannot record an hour, and discovering that on the first payroll is the worst possible moment. An org migrating from another system turns individual seeds off so its own codes are not shadowed.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','adjusted_service_date_rule','"carry_if_gap_under_months:12"'::jsonb,'"carry_if_gap_under_months:12"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Adjusted Service Date Rule','Twelve months is the common bridging window and matches the sick-leave reinstatement window CA already imposes, so the two do not disagree inside one rehire.','agent','Twelve months is the common bridging window and matches the sick-leave reinstatement window CA already imposes, so the two do not disagree inside one rehire.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','blended_rate_min_cell','5'::jsonb,'5'::jsonb,'integer',NULL,'3'::numeric,'25'::numeric,NULL::jsonb,'Blended rate minimum cell','Fewest distinct employments a scope must contain before hr.blended_labor_rate returns a rate.','agent','Two people in a department means the second person''s salary is the first''s subtraction problem (§4.6). Five is the same floor the EEO aggregate uses.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','blended_rate_round_to','0.25'::jsonb,'0.25'::jsonb,'number','usd','0.01'::numeric,'5.00'::numeric,NULL::jsonb,'Blended rate rounding','Rounding increment applied to a blended labour rate before it is returned.','agent','Rounding is half of what makes the figure non-invertible; without it repeated calls across overlapping scopes can be differenced back to an individual.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','contractor_directory_visible','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Contractor Directory Visible','D8 puts contractors fully in scope and §1.4 gates only the employment-only MACHINERY off. A person who does the work and appears on the schedule belongs in the directory; hiding them is how misclassification stays invisible.','agent','D8 puts contractors fully in scope and §1.4 gates only the employment-only MACHINERY off. A person who does the work and appears on the schedule belongs in the directory; hiding them is how misclassification stays invisible.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','directory_default_view','"cards"'::jsonb,'"cards"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Directory Default View','Arman''s Q2 answer, R-L1 §F: a spreadsheet of eleven people is a worse answer than eleven faces. Cards for a small org, table one click away, and the choice is remembered PER USER (a preference, never a config key) so this default only ever decides the first visit.','agent','Arman''s Q2 answer, R-L1 §F: a spreadsheet of eleven people is a worse answer than eleven faces. Cards for a small org, table one click away, and the choice is remembered PER USER (a preference, never a config key) so this default only ever decides the first visit.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','directory_shows_hire_date','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Directory shows hire date','Whether a colleague sees the hire date on a directory card.','agent','Service anniversaries are ordinary workplace information and hiding them by default makes the directory feel evasive; an org that disagrees turns it off.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','directory_shows_manager','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Directory shows manager','Whether a colleague sees the reporting line on a directory card.','agent','Knowing who to ask is the directory''s main job; the org chart is already org-readable.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','directory_visible_to_employees','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Directory Visible To Employees','Knowing who your colleagues are is the directory''s whole job. `directory_opt_out` is the per-person answer; this is the org-wide one and switching it off should be a deliberate act.','agent','Knowing who your colleagues are is the directory''s whole job. `directory_opt_out` is the per-person answer; this is the org-wide one and switching it off should be a deliberate act.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','disclosure_existence_statements',E'{"leave_case": {"shows": [], "source": "SPEC-UI-IA 4.2 verbatim example; SPEC-LEAVE 9.6; SPEC-UI-IA 10 default \\"leave cases: on\\"", "statement": "This person has an approved leave. Details are held by HR.", "provenance": "platform_authored"}}'::jsonb,'{}'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Disclosure Existence Statements','Section 1.3''s ONE permitted disclosure: a worded statement that a record exists without showing it. `default_value` stays {} because a statement nobody wrote is not a statement; the platform `value` carries the single entry the SPEC itself wrote (leave_case, SPEC-UI-IA 4.2''s example), which is how SPEC-UI-IA 10''s declared "leave cases: on" default is honoured without fabricating any org''s voice. Per record class; org-overridable at rung 1. Presence of a statement IS the switch (SPEC-LEAVE 9.6).','agent','§1.3''s ONE permitted disclosure: a worded statement that a record exists without showing it ("This person has an approved leave. Details are held by HR."). Empty by default because a statement nobody wrote is not a statement, and a masked field is never the answer.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','display_name_rule','"preferred_first_legal_last"'::jsonb,'"preferred_first_legal_last"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Display Name Rule','Preferred-first + legal-last is how a workplace actually addresses people while keeping the surname that matches payroll and I-9. `legal_full` exists for orgs whose payroll vendor drives the directory; `preferred_full` for orgs that treat the whole name as the person''s to choose.','agent','Preferred-first + legal-last is how a workplace actually addresses people while keeping the surname that matches payroll and I-9. `legal_full` exists for orgs whose payroll vendor drives the directory; `preferred_full` for orgs that treat the whole name as the person''s to choose.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','duplicate_scan_fields','["name_trgm", "work_email", "personal_email", "ssn_hmac"]'::jsonb,'["name_trgm", "work_email", "personal_email", "ssn_hmac"]'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Duplicate Scan Fields','All four legs on by default: a duplicate person record is the defect that quietly splits somebody''s tenure, PTO and I-9 across two files. The SSN leg only runs when aidream supplies the HMAC, because the key never enters the database (SPEC-ACCESS §4.5), and the scan envelope names the legs that actually ran.','agent','All four legs on by default: a duplicate person record is the defect that quietly splits somebody''s tenure, PTO and I-9 across two files. The SSN leg only runs when aidream supplies the HMAC, because the key never enters the database (SPEC-ACCESS §4.5), and the scan envelope names the legs that actually ran.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','employee_number_format','"EMP-{seq:05}"'::jsonb,'"EMP-{seq:05}"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Employee number format','Template for generated employee numbers.','agent','A zero-padded sequence sorts correctly and is short enough to say out loud; orgs migrating from another system override it.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','future_dated_change_max_days','365'::jsonb,'365'::jsonb,'integer',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Future Dated Change Max Days','A change scheduled more than a year out is almost always a typo in the year. The ceiling is a guard against a fat finger, not a policy — and it is a knob because a 2-year fixed-term contract legitimately needs 730.','agent','A change scheduled more than a year out is almost always a typo in the year. The ceiling is a guard against a fat finger, not a policy — and it is a knob because a 2-year fixed-term contract legitimately needs 730.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','name_change_requires_document','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Name Change Requires Document','A document requirement is a KNOB, never a hard rule (§4.10) — demanding a court order before someone can correct their own legal name is a policy an org may choose and a platform may not impose.','agent','A document requirement is a KNOB, never a hard rule (§4.10) — demanding a court order before someone can correct their own legal name is a policy an org may choose and a platform may not impose.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.employees','notify_employee_on_pay_change','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Notify Employee On Pay Change','The person whose pay changed is the one party who must not learn it from a payslip. Orgs running a synchronised comp cycle turn it off for the cycle window.','agent','The person whose pay changed is the one party who must not learn it from a payslip. Orgs running a synchronised comp cycle turn it off for the cycle window.','2026-11-24'::date,'394893a0-be07-4b4a-9b50-3a0cd984bc80'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
