insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','approaching_ot_buffer_minutes','15'::jsonb,'15'::jsonb,'integer','minutes','0'::numeric,'480'::numeric,NULL::jsonb,'Approaching-OT alert buffer','How far before a resolved threshold the approaching-overtime alert fires.','agent','SPEC-TIME §4.5 platform default 15. Fires once per (employment, workweek, threshold_axis) — the dedupe key is what stops a 40-hour week producing eleven notifications.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','approaching_ot_grace_minutes','0'::jsonb,'0'::jsonb,'integer','minutes','0'::numeric,'480'::numeric,NULL::jsonb,'Unapproved-OT exception grace','How far past a threshold an employee may go before the unapproved_overtime exception opens.','agent','🚨 SPEC-TIME §4.5: NEVER affects what is computed or paid. The moment a threshold is crossed, OT is computed and owed regardless of grace, buffer, alert or approval. Platform default 0; the knob exists so a manager is not paged over a two-minute overrun.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','approval_due_hours_after_period_end','48'::jsonb,'48'::jsonb,'integer','hours','1'::numeric,'336'::numeric,NULL::jsonb,'Manager approval deadline','Hours after the pay period ends by which a manager must decide a timecard.','agent','SPEC-TIME §13 platform default 48, matching the live timecard_approval definition''s sla_hours so the flow and the register agree.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','attestation_due_hours_after_period_end','24'::jsonb,'24'::jsonb,'integer','hours','1'::numeric,'336'::numeric,NULL::jsonb,'Attestation deadline','Hours after the pay period ends by which an employee must attest before reminders escalate.','agent','SPEC-TIME §13 platform default 24. Chosen so the deadline lands the day after the period closes, ahead of the 48-hour manager approval window. Reminders fire N times and then the step auto-closes as not_attested — it NEVER auto-attests (§2.2).','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','attestation_statement','"I confirm that the hours shown are a complete and accurate record of the time I worked, that I took the meal and rest breaks recorded, and that I have reported any that I did not."'::jsonb,'"I confirm that the hours shown are a complete and accurate record of the time I worked, that I took the meal and rest breaks recorded, and that I have reported any that I did not."'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Attestation statement','The exact text an employee attests to at period close.','agent','SPEC-TIME §2.2 and §13: org-overridable, and the text SHOWN is copied onto hr.pay_period_employment.attestation_statement at the moment of attestation. An org editing this later must never retroactively change what an employee agreed to.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','auto_close_orphan_punch','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Auto-close orphan punches','Whether the engine closes an over-long open punch automatically.','agent','An open punch left forever silently corrupts every week that follows it; auto-close plus an auto_closed_estimate exception is visible, a missing clock-out is not.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','employee_attestation_required','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Employee timesheet attestation required','Whether a pay period needs the employee''s attestation before approval.','agent','AR2''s attestation half; a timesheet nobody affirmed is weak evidence in a wage dispute.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','export_auto_run_on_approval','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Auto-generate the export on period approval','Whether approving a period immediately generates the payroll export.','agent','SPEC-TIME §13 platform default false. Generating a payroll file is a deliberate act with a pre-run manifest; nobody should discover one was produced.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','export_blocks_on_open_dispute','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'An open dispute blocks the export','Whether an unresolved employee disagreement stops a payroll export run.','agent','SPEC-TIME §13 platform default false: the dispute TRAVELS to the export as evidence rather than blocking pay. Blocking would withhold correct hours over a disagreement about some of them.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','export_format_default','"generic_csv"'::jsonb,'"generic_csv"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["quickbooks_online", "quickbooks_iif", "gusto_csv", "adp_csv", "generic_csv", "json"]'::jsonb,'Default payroll export format','Format hr.payroll_export generates unless overridden.','agent','D22: a default that cannot generate a file on day one is a broken default, not an aspiration. generic_csv is the floor and the default; a QBO connector arrives on the provider seam when it is real.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','geo_required_web_punch','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Capture geo on web punches','Whether the web clock requests a location fix on every punch.','agent','SPEC-TIME §4.9 RULED (Arman, 2026-08-25): OFF by default, capture path built complete, on-state visible to the employee. A denied browser permission produces a punch with geo_missing and an exception — never a refused punch.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','grace_early_minutes','5'::jsonb,'5'::jsonb,'integer','minutes','0'::numeric,'30'::numeric,NULL::jsonb,'Early departure grace','Minutes before the scheduled end that still count as a full shift.','agent','Symmetry with the late grace; an asymmetric pair reads as employer-favourable and invites a claim.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','grace_late_minutes','5'::jsonb,'5'::jsonb,'integer','minutes','0'::numeric,'30'::numeric,NULL::jsonb,'Late arrival grace','Minutes past the scheduled start before a late_arrival exception is raised.','agent','Below five minutes the exception queue fills with traffic-light noise and managers stop reading it.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','ip_verification_mode','"off"'::jsonb,'"off"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["off", "warn", "block"]'::jsonb,'IP verification mode','What the punch RPC does about an out-of-allowlist source IP.','agent','Off by default: a home-office or hotspot punch is normal for many roles. On `block` the RPC refuses BEFORE inserting and writes an access-audit row rather than a phantom punch (§7.1).','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_confirm_dismiss_seconds','5'::jsonb,'5'::jsonb,'integer','seconds','1'::numeric,'120'::numeric,NULL::jsonb,'Confirmation card auto-dismiss','Seconds the kiosk confirmation card stays up before returning to idle.','agent','SPEC-TIME §3.3 platform default 5. Long enough for the next person not to read the last person''s name off the screen is the constraint, not comfort.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_cross_location_punch','"allow_with_flag"'::jsonb,'"allow_with_flag"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["allow", "allow_with_flag", "block"]'::jsonb,'Punching at another location','What happens when an employee punches at a kiosk outside their assigned location.','agent','SPEC-TIME §3.3 platform default allow_with_flag: the punch is stamped location_mismatch and raises an exception. A multi-site worker is never blocked.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_enabled','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Kiosk Enabled','Whether the shared-device kiosk lane is available. FALSE on purpose — a kiosk mints a device secret and admits punches with no auth.uid(), so it is the one time surface that must be switched on deliberately by somebody who has read what it does, never inherited by an org that never asked for it. SPEC-UI-IA §10 row.','agent','Whether the shared-device kiosk lane is available. FALSE on purpose — a kiosk mints a device secret and admits punches with no auth.uid(), so it is the one time surface that must be switched on deliberately by somebody who has read what it does, never inherited by an org that never asked for it. SPEC-UI-IA §10 row.','2026-11-25'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_heartbeat_seconds','60'::jsonb,'60'::jsonb,'integer','seconds','10'::numeric,'3600'::numeric,NULL::jsonb,'Idle-screen heartbeat interval','How often the kiosk idle screen re-checks its trust state.','agent','SPEC-TIME §3.3 platform default 60. This is the upper bound on how long a revoked device can keep taking punches, so it is a security value, not a polling preference.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_lockout_minutes','15'::jsonb,'15'::jsonb,'integer','minutes','1'::numeric,'120'::numeric,NULL::jsonb,'Kiosk lockout minutes','How long an employment PIN stays locked after too many wrong attempts.','agent','Long enough to make guessing pointless, short enough that somebody who fat-fingered their PIN at the start of a shift is not sent home. A manager override is the escape hatch for the rest.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_max_clock_skew_seconds','300'::jsonb,'300'::jsonb,'integer','seconds','30'::numeric,'3600'::numeric,NULL::jsonb,'Maximum kiosk clock skew','How far a device clock may drift before its punches are refused.','agent','Five minutes absorbs ordinary NTP drift on a cheap tablet without letting a mis-set clock rewrite a shift boundary.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_pending_recheck_seconds','10'::jsonb,'10'::jsonb,'integer','seconds','3'::numeric,'300'::numeric,NULL::jsonb,'Kiosk pending-trust recheck interval','How often a kiosk in pending trust state rechecks for approval.','agent','Matches the rung-4 default hr._kiosk_device_config and hr_kiosk_session_heartbeat carried in code.','2026-10-15'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_pin_length','4'::jsonb,'4'::jsonb,'integer','digits','4'::numeric,'8'::numeric,NULL::jsonb,'Kiosk PIN length','How many digits an employment PIN must have.','agent','Four digits is what every time clock in the world uses and what a break-room queue will tolerate; the second factor here is the DEVICE secret, not PIN entropy, and lockout after five attempts is what actually bounds a guessing attack. Orgs that want six can raise it.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_pin_max_attempts','5'::jsonb,'5'::jsonb,'integer',NULL,'3'::numeric,'10'::numeric,NULL::jsonb,'Kiosk PIN maximum attempts','Wrong PINs before the employment PIN locks.','agent','Five absorbs an honest mis-type on a greasy tablet twice over while making a 10,000-space guess hopeless at one attempt per lockout window. Lower than three would strand people at shift start, which is the over-tightening failure this domain weighs as heavily as a leak.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_require_geo','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Kiosk requires geolocation','Whether a kiosk punch captures coordinates.','agent','Location tracking of staff is off by default for the same reason as the photo; the geofence columns exist for orgs that opt in.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_require_photo','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Kiosk requires photo','Whether a kiosk punch captures a photo.','agent','Biometric-adjacent capture is off by default; several states regulate it and an employer should opt in knowingly.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_session_ttl_hours','12'::jsonb,'12'::jsonb,'integer','hours','1'::numeric,'24'::numeric,NULL::jsonb,'Device kiosk session TTL','Hours a wall tablet''s own device session stays valid between re-authentications.','agent','One working day, so a tablet does not need re-pairing mid-shift. This value NEVER gates a person''s session.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','kiosk_session_ttl_minutes','2'::jsonb,'2'::jsonb,'integer','minutes','1'::numeric,'30'::numeric,NULL::jsonb,'Person-bound kiosk session TTL','Minutes a PIN-authenticated interaction session stays valid.','agent','The person-bound session must expire fast or the next person in line punches as the last one. Distinct from the DEVICE session TTL below — conflating the two is the R-L3 U-05 trap.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
