insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','manager_approval_required','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Manager approval required','Whether a pay period needs manager approval before export.','agent','The second pair of eyes before money moves; orgs with a single owner-operator turn it off.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','max_geo_accuracy_m','200'::jsonb,'200'::jsonb,'integer','metres','10'::numeric,'10000'::numeric,NULL::jsonb,'Geo accuracy ceiling','Accuracy in metres beyond which a captured fix is recorded as unreliable.','agent','SPEC-TIME §13 platform default 200. Poor accuracy is RECORDED, not rejected (§2.1) — a weak GPS fix must never cost somebody a punch.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','max_shift_hours','16'::jsonb,'16'::jsonb,'integer','hours','8'::numeric,'24'::numeric,NULL::jsonb,'Maximum shift hours','Elapsed hours after which an open punch is treated as an orphan.','agent','A 16-hour cap catches a forgotten clock-out without truncating a genuine double; hr.auto_close_rule overrides it per scope where a live-in shift makes it wrong.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','near_duplicate_punch_window_seconds','120'::jsonb,'120'::jsonb,'integer','seconds','10'::numeric,'3600'::numeric,NULL::jsonb,'Near-duplicate flag window','Seconds within which a second punch of the same kind is flagged as a suspected duplicate.','agent','SPEC-TIME §13 and §3.4 platform default 120. A near duplicate is WRITTEN and flagged, never refused — refusing it would lose a fact. Distinct from exact idempotency-key duplicates, which collapse as a success.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','ot_alert_channels_employee','"push,sms,in_app"'::jsonb,'"push,sms,in_app"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'OT alert channels — the employee','Default channels for the approaching-OT alert to the employee, before the per-user rung.','agent','SPEC-TIME §4.5: the employee is the only person who can stop working, so this is the one recipient that gets SMS. Comma-separated following the live hr.workflow.route_absent_approver_action precedent (RD 3).','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','ot_alert_channels_hr','"in_app"'::jsonb,'"in_app"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'OT alert channels — HR and payroll','Default channels for the approaching-OT alert to HR and payroll.','agent','SPEC-TIME §4.5: to HR it is a cost signal, not an interruption — in-app digest only.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','ot_alert_channels_manager','"push,in_app"'::jsonb,'"push,in_app"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'OT alert channels — the manager','Default channels for the approaching-OT alert to the manager.','agent','SPEC-TIME §4.5: the manager is the only person who can authorize it. No SMS — money and record events never default to SMS.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','ot_alert_default_threshold_hours','36'::jsonb,'36'::jsonb,'integer','hours','20'::numeric,'60'::numeric,NULL::jsonb,'Default approaching-OT threshold','Weekly hours at which the default alert rule fires.','agent','Four hours before the 40-hour federal line leaves a manager time to shorten a shift instead of finding out on the timesheet.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','ot_preapproval_decision_sla_hours','4'::jsonb,'4'::jsonb,'integer','hours','1'::numeric,'168'::numeric,NULL::jsonb,'OT pre-approval decision deadline','Hours a manager has to decide an overtime pre-approval before it escalates.','agent','SPEC-TIME §4.4 platform default 4 — overtime is decided the same shift or not at all. On expiry the request ESCALATES; it never auto-approves and never auto-denies.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','ot_preapproval_required','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Overtime pre-approval required','Whether overtime is expected to carry an approved pre-approval.','agent','Off by default because most SMBs do not run the process. 🚨 Even when ON it never gates pay — the FLSA pays hours suffered or permitted, approved or not (D24a).','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','pairing_code_ttl_minutes','15'::jsonb,'15'::jsonb,'integer','minutes','5'::numeric,'120'::numeric,NULL::jsonb,'Pairing code TTL','Minutes an unclaimed device pairing code stays valid.','agent','The pairing code is the only path that mints a device secret; a short single-use window is what keeps it from becoming a standing credential.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','pin_lockout_minutes','15'::jsonb,'15'::jsonb,'integer','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'PIN lockout duration','How long a PIN is locked after too many failures.','agent','Long enough to stop a shoulder-surfing guess, short enough that a genuine employee is not sent home.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','pin_max_failed_attempts','5'::jsonb,'5'::jsonb,'integer',NULL,'3'::numeric,'10'::numeric,NULL::jsonb,'PIN failed attempts before lockout','Consecutive failures that trigger the lockout.','agent','A 4-digit PIN mistyped twice is normal; five is where a pattern starts.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','punch_enabled_worker_class_employee','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Employees may punch','Whether worker_class=employee may use the time clock.','agent','SPEC-TIME §8 default set ["employee","intern","seasonal"]. Decomposed to scalars because platform.feature_knob.value_type admits no array (RD 1). There is deliberately NO contractor key: §8 makes contractor punching a worker-classification hazard the product will not offer.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','punch_enabled_worker_class_intern','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Interns may punch','Whether worker_class=intern may use the time clock.','agent','SPEC-TIME §8 default set includes intern. See punch_enabled_worker_class_employee for why this is a scalar and why no contractor key exists.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','punch_enabled_worker_class_seasonal','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Seasonal workers may punch','Whether worker_class=seasonal may use the time clock.','agent','SPEC-TIME §8 default set includes seasonal. See punch_enabled_worker_class_employee.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','punch_enabled_worker_class_volunteer','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Volunteers may punch','Whether worker_class=volunteer may use the time clock.','agent','SPEC-TIME §8: off by default. An org tracking volunteer hours for grant reporting turns this on — and volunteers still NEVER produce OT, premiums or export lines, because those come from earning codes and rules, not from the punch lane.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','punch_enabled_worker_classes','["employee", "intern", "seasonal"]'::jsonb,'["employee", "intern", "seasonal"]'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Punch-enabled worker classes (composite)','The worker classes whose members may punch, as one array. NOTE: duplicates the four punch_enabled_worker_class_* booleans; hr.clock_state and hr.punch_record read this composite key while hr._time_punch_enabled_worker_classes reads the booleans — convergence to one shape is a recorded follow-up.','agent','Matches the rung-4 default hr.clock_state and hr.punch_record carried in code; seeded so the resolver can refuse unseeded keys instead of silently defaulting.','2026-10-15'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','remote_punch_allowed','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Remote web punch allowed','Whether the web clock accepts a punch from outside a known location.','agent','Remote and field work are ordinary; orgs that need site-bound punching turn it off and use the kiosk lane.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','remote_worker_validation','"attest"'::jsonb,'"attest"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["none", "attest", "geo"]'::jsonb,'Remote-worker validation','What a remote position assignment is asked for instead of an IP check.','agent','SPEC-TIME §4.7 platform default attest. Evaluated BEFORE IP verification: a remote assignment under none or attest is never subject to block. IP verification exists to catch a shared credential punching from a beach, not to punish a distributed workforce for existing.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','require_break_attestation','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Require break attestation','Whether a clock-out presents the meal/rest attestation prompt.','agent','In California the attestation IS the evidence that a meal was provided; defaulting it on costs a tap and defaulting it off costs a premium per shift.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','rounding_minutes','0'::jsonb,'0'::jsonb,'integer','minutes','0'::numeric,'15'::numeric,NULL::jsonb,'Punch rounding increment','Minutes the pairing engine rounds a punch to. 0 = no rounding, the neutral default.','agent','FLSA permits neutral rounding but does not require it; starting at 0 means no employer can be accused of systematic under-rounding on our default. Orgs that want 15-minute rounding opt in.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','rounding_mode','"nearest"'::jsonb,'"nearest"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["nearest", "up"]'::jsonb,'Punch rounding mode','Rounding direction. "down" is rejected by the neutrality predicate (fixture RND-02).','agent','SPEC-TIME §14 D5: the column may carry the wider enum, but the config validator accepts nearest and up and REJECTS down. "up" is always employee-favourable and therefore neutral-or-better; "down" always moves time in one direction and fails the neutrality test.','2026-11-24'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','show_raw_alongside_rounded','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Show raw values beside rounded ones','Whether an interval whose rounding delta is non-zero renders the raw in/out beside the paid in/out.','agent','PLATFORM-ONLY - NEVER ORG-OVERRIDABLE. SPEC-TIME §10 and §13, the same posture as hr.jurisdiction_rules.advisory_rules_block_money. Honesty about how a figure was derived is not an organization''s preference to switch off. platform.feature_knob has no org_overridable column and set_by admits only agent|human, so this sentence IS the marker: an org-override surface refuses any key whose basis opens with it (RD 5).','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','timesheet_attestation_required','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Timesheet Attestation Required','The UI gate on /hr/me/timesheet: whether the employee is asked to attest. DISTINCT from employee_attestation_required, which decides whether the attestation STEP EXISTS in the timecard flow (RECORDED DECISION 30) — an org can run the step while this surface is off, because kiosk-only staff attest at the kiosk. SPEC-UI-IA §10 row.','agent','The UI gate on /hr/me/timesheet: whether the employee is asked to attest. DISTINCT from employee_attestation_required, which decides whether the attestation STEP EXISTS in the timecard flow (RECORDED DECISION 30) — an org can run the step while this surface is off, because kiosk-only staff attest at the kiosk. SPEC-UI-IA §10 row.','2026-11-25'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','timesheet_bulk_approve_enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Timesheet Bulk Approve Enabled','Whether /hr/time/timesheets offers bulk approval. TRUE because a manager approving forty identical weeks one at a time will stop reading them, which is the failure this control exists to prevent; the workflow engine still refuses bulk on any flow whose definition forbids it, so this switch can widen nothing the engine has closed. SPEC-UI-IA §10 row.','agent','Whether /hr/time/timesheets offers bulk approval. TRUE because a manager approving forty identical weeks one at a time will stop reading them, which is the failure this control exists to prevent; the workflow engine still refuses bulk on any flow whose definition forbids it, so this switch can widen nothing the engine has closed. SPEC-UI-IA §10 row.','2026-11-25'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','unapproved_ot_opens_exception','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Unapproved OT opens a reviewable exception','Whether overtime worked without a matching approval raises an exception for a human to review.','agent','🚨 SPEC-TIME §4.6: setting this false STILL PAYS and STILL RECORDS — it removes only the review gate. Whether unapproved overtime is paid is a law, not a knob, and no value of this key changes it.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','variance_warn_minutes','15'::jsonb,'15'::jsonb,'integer','minutes','0'::numeric,'480'::numeric,NULL::jsonb,'Scheduled-vs-actual highlight threshold','Minutes of variance against the schedule past which route 28 highlights the row.','agent','SPEC-TIME §13 platform default 15. A display threshold only: it never adjusts pay, and where no schedule exists the column reads "Not scheduled", never 0.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','web_punch_enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Web Punch Enabled','Whether the web punch surface at /hr/me/clock exists at all. TRUE because a salaried-plus-hourly org that turns HR on expects its people to be able to clock in from the app on day one; an org that clocks only at a wall device turns it off and the route goes ABSENT, not disabled. SPEC-UI-IA §10 row; SPEC-TIME §13 reads it and must never treat an absent row as false.','agent','Whether the web punch surface at /hr/me/clock exists at all. TRUE because a salaried-plus-hourly org that turns HR on expects its people to be able to clock in from the app on day one; an org that clocks only at a wall device turns it off and the route goes ABSENT, not disabled. SPEC-UI-IA §10 row; SPEC-TIME §13 reads it and must never treat an absent row as false.','2026-11-25'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','web_punch_ip_allowlist','""'::jsonb,'""'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Web punch IP allowlist','Comma-separated CIDR ranges checked when IP verification is on. Empty means not configured.','agent','🚨 SPEC-TIME §4.7: an EMPTY allowlist never blocks anything — an unconfigured allowlist means "not configured", never "deny all". The platform default is genuinely empty. Per-org, per-location lists are data and will need a table when a real org configures one (RD 4).','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','web_punch_ip_verification','"off"'::jsonb,'"off"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Web punch IP verification (legacy fallback key)','Fallback mode consulted when ip_verification_mode resolves null at a web punch. Legacy twin of ip_verification_mode — convergence to one key is a recorded follow-up.','agent','Matches the rung-4 default hr.punch_record carried in code.','2026-10-15'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','workday_start_local','"00:00"'::jsonb,'"00:00"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Workday start (local)','The 24-hour window daily overtime is measured over.','agent','SPEC-TIME §13 platform default 00:00. A separate axis from day-column placement (§9 rule 5): where this is not 00:00 the interval detail shows BOTH attributions, because for a 04:00-workday org they are routinely different.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.time_and_attendance','workweek_start_day','"sunday"'::jsonb,'"sunday"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"]'::jsonb,'Workweek start day','The day the overtime workweek begins.','agent','SPEC-TIME §13 platform default sunday. STAMPED per workweek at creation (hr.workweek.week_start_dow) on conflict (feature,key) do nothing; changing it never re-cuts history, which is why the timesheet block header names the stamped value rather than the current setting.','2027-02-22'::date,'959be751-bf57-4770-8f9e-cc2df3209b9c'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.training','mandate_generation_enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Mandated training generation enabled','Whether the rule engine issues jurisdiction-mandated assignments.','agent','Bucket-2 item 9: mandated training is a rule, not a manual assignment. mandate_cycle_key makes the generator safely re-runnable, so leaving it on is the low-risk default.','2026-11-24'::date,'11685129-00cf-498c-9c63-08b4bee78d43'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.workflow','default_step_sla_hours','48'::jsonb,'48'::jsonb,'integer','hours','1'::numeric,'2160'::numeric,NULL::jsonb,'Default step SLA','Used when neither the step definition nor the definition declares one. §9.2 says the step inherits the instance SLA, and §9.2 leaves the instance SLA NULL — so without this a step would have no due date at all and nothing to remind against.','agent','SPEC-WORKFLOW-ENGINE §9.2 — agent-chosen, fills a NULL-cascade gap','2027-02-26'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.workflow','delegation_allow_subdelegation','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Sub-delegation permitted','Platform rung only, never org-overridable. Enforced by hr.approvals.delegation_max_depth.','agent','SPEC-WORKFLOW-ENGINE §9.3','2027-02-26'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
