insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.workflow','route_absent_approver_action','"delegated,substitute,climb,route_and_escalate"'::jsonb,'"delegated,substitute,climb,route_and_escalate"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Absent-approver action order','Ordered, comma-separated response when a resolved approver is absent. The last rung routes anyway with escalate_after_hours forced to 0, so a request never sits silently behind an out-of-office.','agent','SPEC-WORKFLOW-ENGINE §2.3 / §9.3','2027-02-26'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.workflow','sla_business_hours_only','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'SLA math uses business hours only','Step and instance due dates are computed against the org holiday calendar in the subject''s location timezone rather than wall-clock hours.','agent','SPEC-WORKFLOW-ENGINE §9.2','2027-02-26'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.workflow','tick_batch_max','500'::jsonb,'500'::jsonb,'integer','steps','1'::numeric,'5000'::numeric,NULL::jsonb,'Tick batch cap','Maximum steps one hr.wf_tick() pass touches, so a single sweep can never become an unbounded transaction.','agent','SPEC-WORKFLOW-ENGINE §1.9 — agent-chosen, no spec value','2027-02-26'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('hr.workflow','timeout_warning_lead_hours','4'::jsonb,'4'::jsonb,'integer','hours','0'::numeric,'168'::numeric,NULL::jsonb,'Mode-3 timeout warning lead','How long before an autonomy-mode-3 step auto-applies that the warning notice fires. The autonomy policy requires the timeout be visible BEFORE it fires.','agent','SPEC-WORKFLOW-ENGINE §9.2 / autonomy-modes policy rule 4','2027-02-26'::date,'a1c5680f-bc1f-4a7e-b728-836575ebaddf'::uuid,'{organization,employer_profile,pay_group,location}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','active_sandbox_capacity','5'::jsonb,'5'::jsonb,'integer','sandboxes','1'::numeric,'100'::numeric,NULL::jsonb,'Maximum active sandboxes per user','The maximum number of a user''s sandboxes that may be creating, starting, ready, or running across both hosted and EC2 tiers. The orchestrator enforces this atomically before storage or runtime work begins. This is an operational fleet safety limit, not a plan entitlement or organization preference.','agent','Default 5 retained from the existing operational create ceiling. The atomic reservation transaction must read one platform-owned value while it holds the user admission lock; user or organization overrides would let a caller alter its own safety limit. Review after measured fleet capacity evidence.','2026-11-15'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','aidream_template_forwards_master_credentials','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Hand the platform''s master credentials to aidream-template sandboxes','Only the internal "aidream" sandbox template (running the aidream server itself inside a box) ever receives the orchestrator''s platform environment. Even then, names that look like master credentials — database passwords and URLs, service tokens, admin tokens, provider API keys — are withheld unless this is on. Leave off: a box that holds the platform''s master credentials can act as the platform. Turn on only for a short, supervised dev session and rotate afterwards.','agent','Incident 2026-09-13: every user sandbox carried the platform master credentials. Off is the safety posture; the orchestrator also treats a missing row as off.','2026-10-13'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','auto_clone_attached_repos','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Clone attached GitHub repositories into the sandbox before the agent''s first turn','When on, a chat armed with a sandbox clones every GitHub repository attached to the conversation into ~/repos/<name> before the agent starts, so it never has to search or clone one itself. A clone that fails is reported in the briefing and never stops the run.','agent','On by default: the attachment IS the instruction to use the repo, and a shallow clone of an already-attached repo is work the user asked for. Set 2026-09-15 with the conversation-attachment build.','2026-10-15'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','auto_migrate','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Move idle sandboxes onto the newest image automatically','When on, the reaper''s sweep moves sandboxes still on an old image onto the current one, a few per pass, skipping any that are busy. When off, migration only happens when someone triggers it.','agent','Was MATRX_AUTO_MIGRATE: 0 on both tiers, read 2026-09-11.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','auto_update_check_interval_seconds','600'::jsonb,'600'::jsonb,'integer','seconds','60'::numeric,'86400'::numeric,NULL::jsonb,'How often the sandbox fleet checks whether a newer image is available','The reaper still checks every minute for expired or missing sandboxes. This separate interval controls only the fleet-wide comparison against the newest sandbox image. Lower values notice a newly published image sooner but make Docker inspect the fleet more often; higher values reduce that work but wait longer before an opt-in automatic migration can notice drift. The first check after an orchestrator restart is allowed immediately. This does not turn automatic migration on.','agent','Set 2026-09-15 by the approved sandbox cadence decision: image-drift inspection is fleet-wide work and should run every 600 seconds by default, while expiry and liveness remain at their existing 60-second cadence. The 60-second floor prevents this optional image check from becoming more frequent than lifecycle safety work; one day is a bounded operational maximum. Auto-migration remains controlled separately by infrastructure.sandbox.auto_migrate, whose default remains false.','2026-11-14'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','auto_update_idle_seconds','1800'::jsonb,'1800'::jsonb,'integer','seconds','1'::numeric,'86400'::numeric,NULL::jsonb,'How long an automatically updated sandbox must remain quiet','Before an opt-in automatic image migration, the sandbox must have no in-flight work, interactive session, recent local activity, or recent authoritative heartbeat for this many seconds. The interval is captured once for the migration pass and checked again after the admission drain, so an in-flight setting edit cannot shorten a swap already being admitted. This setting applies only to automatic migration; manual confirmed updates retain their existing heartbeat and interruption contract.','agent','Set 2026-09-15 by the whole-agent idle safety decision. Thirty minutes is the conservative default while durable execution activity beyond the current request/session signals is being added. A positive bounded integer lets operators lengthen the quiet period without a deploy; malformed or unavailable values fail closed before Docker discovery. This does not turn automatic migration on and does not enable the unsupported S3 migration route.','2026-11-14'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','change_feed_admission_wait_ms','1000'::jsonb,'1000'::jsonb,'integer','ms','100'::numeric,'5000'::numeric,NULL::jsonb,'How long a sandbox''s file-change check waits its turn before being turned away','When the server is already handling as many file-change checks as it allows, a new one waits briefly for a turn. This is how long it waits before the server tells it to come back later. Waiting costs the server nothing - the waiting check is not holding a database connection - so a value around the time one check takes turns a brief rush into served requests instead of refusals. Much larger and sandboxes sit waiting during a genuine slowdown; much smaller and normal bursts get turned away.','agent','Raised from 0.5 s to 1.0 s on 2026-09-14. The original half-second assumed the waiter was queueing for a database connection behind a stalled read; it is not - it waits on an in-process semaphore and holds no connection at all, so the "queueing deepens the outage" reasoning does not apply to the waiter. One measured service time (p50 0.714 s, mean 0.895 s across 91 live holder samples) converts a sub-second burst into a served poll rather than a shed one, and 1.0 s + the 4.5 s read deadline still completes inside the sandbox client''s timeout.','2026-11-13'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','change_feed_max_concurrent_reads','8'::jsonb,'8'::jsonb,'integer','reads','1'::numeric,'8'::numeric,NULL::jsonb,'How many sandbox file-change checks the server handles at the same time','Every sandbox checks in regularly to ask which of its files changed. This is how many of those checks the server will work on at once; any beyond it are politely turned away and told when to come back, which costs the sandbox nothing because the next check picks up everything it missed. Too low and healthy sandboxes get turned away for no reason; too high and these routine checks crowd out everything else the server is doing. The ceiling of 8 exists because the server keeps two of its ten database connections free for everything else, and it is enforced in the code as well as here.','agent','Sized 2026-09-14 from live evidence. 226 sandboxes polling every 30 s is 7.53 polls/second; the measured time a poll occupies a permit is ~1 s (91 samples from the 47 shed captures of 06:35-12:35 UTC: mean 0.895 s, p50 0.714 s, p90 1.577 s), so Little''s law puts ~7.5 polls in flight at any moment. The previous value of 3 was sized on 2026-09-12 when each poll held a database connection for seconds (the uncached admin.admins read per request, cached 2026-09-14 in f3057d592) on conflict (feature,key) do nothing; it then shed most of the fleet by construction - 61 sheds across 49 users in the 12:35 window with no pool saturation. 8 = pool_max (10) minus 2 reserved connections, the largest value that preserves the invariant that this fallback poll can never consume the pool. The remaining headroom comes from the poll-cadence knobs below: at 45 s the fleet arrives at 5.02/s, i.e. 63% utilisation of these 8.','2026-11-13'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','change_feed_poll_interval_seconds','30'::jsonb,'30'::jsonb,'integer','seconds','5'::numeric,'600'::numeric,NULL::jsonb,'How often each sandbox should check for file changes','The server tells every sandbox how long to wait before checking again for changed files, and sends that instruction with every answer. This is the normal cadence. Raising it means fewer requests but slower pickup of a change; lowering it means the opposite. Live file updates normally arrive instantly over the realtime channel - this checking is the fallback for when that channel is unavailable.','agent','Matches the cadence the sandbox image already used (POLL_INTERVAL_SECONDS = 30 s in matrx-sandbox cloud_sync/downstream.py) on conflict (feature,key) do nothing; making it a server-sent instruction is what lets the cadence change without shipping a new sandbox image. 226 boxes at 30 s = 7.53 requests/second, which is the arrival rate the concurrency knob above is sized against.','2026-11-13'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','change_feed_poll_interval_under_pressure_seconds','45'::jsonb,'45'::jsonb,'integer','seconds','5'::numeric,'600'::numeric,NULL::jsonb,'How often each sandbox should check for file changes while the server is busy','While the server is turning file-change checks away, it asks every sandbox it DOES answer to slow down to this cadence instead of the normal one. That is what stops a crowd from arriving together and getting refused together: the whole fleet eases off from the first refusal anywhere, rather than each sandbox learning about the congestion only by being refused itself. It goes back to the normal cadence as soon as the pressure passes.','agent','Chosen 2026-09-14 so the fleet''s arrival rate drops from 226/30 s = 7.53/s to 226/45 s = 5.02/s, which is 63% utilisation of the 8 concurrent reads above - real headroom against a measured ~1 s service time, rather than a bound sitting exactly on top of demand (rho = 0.94 at 30 s). It is deliberately a mild step: a large jump would delay every sandbox''s file pickup to fix a condition that usually lasts seconds. Ceiling lowered to 600 s on 2026-09-14 to match the band the sandbox image accepts (5-600 s in cloud_sync/downstream.py): a knob an admin can set past what the fleet will honour is a knob that governs nothing.','2026-11-13'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','container_cpu_limit','2.0'::jsonb,'2.0'::jsonb,'number','cores','0.5'::numeric,'16'::numeric,NULL::jsonb,'Processor cores per sandbox','How many processor cores a newly created sandbox machine may use, unless the request asks for a specific amount. Applies to sandboxes created after the change.','agent','Was MATRX_CONTAINER_CPU_LIMIT: 2.0 on the EC2 tier (in-code default) and 2.0 on the hosted tier (.env), read 2026-09-11.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','container_memory_limit','"4g"'::jsonb,'"4g"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Memory per sandbox','How much memory a newly created sandbox machine may use, written the way Docker writes it (for example 4g or 512m), unless the request asks for a specific amount. Applies to sandboxes created after the change.','agent','Was MATRX_CONTAINER_MEMORY_LIMIT: 4g on both tiers, read 2026-09-11.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','enable_s3_migrate','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Allow in-place migration of S3-backed sandboxes','When on, sandboxes whose files live in S3 (the EC2 tier) may be migrated in place: flush to S3, stop, start fresh, cut over. This path has NOT been validated end to end against a throwaway sandbox; leave off until it has, or the new box can come up on stale files.','agent','Was MATRX_ENABLE_S3_MIGRATE: unset on both tiers = off. Off is a safety posture, not a preference; see matrx-sandbox SERVER_AGENT_HANDOFF.md Task E.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','list_page_size','50'::jsonb,'50'::jsonb,'integer','sandboxes','5'::numeric,'500'::numeric,NULL::jsonb,'Sandboxes fetched per page','How many sandboxes the sandbox list loads at a time.','agent','Replaces SANDBOX_LIST_PAGE_SIZE = 50 in matrx-frontend hooks/sandbox/use-sandbox.ts; read live through knobInt.','2026-10-13'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','max_command_length','10000'::jsonb,'10000'::jsonb,'integer','characters','1000'::numeric,'1000000'::numeric,NULL::jsonb,'Longest command a sandbox accepts','The most characters a single command sent to a sandbox may contain; longer ones are refused with a clear message.','agent','Was MATRX_MAX_COMMAND_LENGTH: unset on both tiers = in-code 10000.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','max_session_duration_seconds','7200'::jsonb,'7200'::jsonb,'integer','seconds','300'::numeric,'86400'::numeric,NULL::jsonb,'Default sandbox lifetime','How long a sandbox lives before it expires when nobody asked for a specific lifetime, and the most any request may ask for. 7200 is two hours.','agent','Was MATRX_MAX_SESSION_DURATION_SECONDS: unset on both tiers = in-code 7200.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','migrate_max_per_pass','2'::jsonb,'2'::jsonb,'integer','sandboxes','1'::numeric,'50'::numeric,NULL::jsonb,'Sandboxes migrated per sweep','The most sandboxes one reaper sweep will move onto the newest image, so a large wave rolls gradually instead of all at once.','agent','Was MATRX_MIGRATE_MAX_PER_PASS: 2 on the EC2 tier (systemd) on conflict (feature,key) do nothing; unset on the hosted tier = in-code 2.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','migrate_recent_heartbeat_seconds','120'::jsonb,'120'::jsonb,'integer','seconds','0'::numeric,'3600'::numeric,NULL::jsonb,'Treat a sandbox as busy for','A sandbox that ran a tool call or sent a heartbeat within this many seconds counts as in use, so an automatic migration waits rather than interrupting someone mid-session.','agent','Was MATRX_MIGRATE_RECENT_HEARTBEAT_SECONDS: 120 on the EC2 tier (systemd) on conflict (feature,key) do nothing; unset on the hosted tier = in-code 120.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','persistence_read_timeout_ms','8000'::jsonb,'8000'::jsonb,'integer','ms','1000'::numeric,'60000'::numeric,NULL::jsonb,'Sandbox persistence read timeout','How long the app waits for the sandbox orchestrator to report a person''s persistence status before treating it as unreachable.','agent','Replaces PERSISTENCE_READ_TIMEOUT_MS = 8_000 in matrx-frontend lib/sandbox/persistence-read.ts; read live through knobInt.','2026-10-13'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','sdk_refresh_on_binding','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Keep sandbox tools up to date when an agent connects','When on, connecting an agent to a sandbox that was created from an older image quietly installs the current sandbox tools into the machine''s system area (never the user''s home), so older machines gain new commands without being rebuilt. Off means an older machine keeps the tools it was born with until it is migrated.','agent','New primitive 2026-09-14 (runtime SDK refresh). On by default: the alternative is that a box created before a tool existed can never run it.','2026-10-14'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','shutdown_timeout_seconds','30'::jsonb,'30'::jsonb,'integer','seconds','5'::numeric,'600'::numeric,NULL::jsonb,'Graceful shutdown allowance','How many seconds a sandbox gets to finish saving its files before it is stopped by force. Handed to each sandbox at start and used again when the orchestrator stops or migrates it.','agent','Was MATRX_SHUTDOWN_TIMEOUT_SECONDS: unset on both tiers = in-code 30.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','terminal_retention_days','7'::jsonb,'7'::jsonb,'integer','days','0'::numeric,'365'::numeric,NULL::jsonb,'Keep finished sandboxes visible for','How many days a stopped, expired or failed sandbox stays listed (and resumable) before the reaper archives it out of every default list. The record is kept for audit and the user''s files are untouched. 0 turns the sweep off.','agent','Was MATRX_TERMINAL_RETENTION_DAYS: unset on both tiers = in-code 7.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','transient_outage_retry_budget_seconds','45'::jsonb,'45'::jsonb,'number','seconds','0'::numeric,'300'::numeric,NULL::jsonb,'How long a sandbox tool call waits out a sandbox connection outage','When the sandbox service restarts (a deploy, for example), the connection to a running box is briefly unavailable even though the box and all of its files are fine. Rather than failing the assistant''s command, the platform quietly waits and retries it for up to this many seconds. If the connection is still down after that, the assistant is told once, plainly, to wait a minute and try again — instead of hammering the box and burning through its turn. Higher means fewer interruptions during a deploy but a longer pause before the assistant hears anything; lower means it gives up sooner.','agent','Chosen 2026-09-13 after conversation 6d383f43 lost a whole run to a ~30s orchestrator restart: eight sandbox calls failed in 17 seconds with a bare upstream error, the agent retried the same command seven times and its tools were disabled. An orchestrator restart/deploy cutover runs ~30-60s, so 45s covers the common case without holding one tool call hostage for minutes. Platform-locked: this is a property of our own orchestrator''s restart time, not a tenant policy.','2026-11-12'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','warm_pool_size','2'::jsonb,'2'::jsonb,'integer','sandboxes','0'::numeric,'20'::numeric,NULL::jsonb,'Sandboxes kept ready','How many pre-started, unclaimed sandboxes each orchestrator keeps warm so launching one from a chat is instant. 0 turns the warm pool off. Used by the per-template list below when an entry gives no count of its own.','agent','Was MATRX_WARM_POOL_SIZE: 2 on the EC2 tier (systemd) and 2 on the hosted tier (.env), read 2026-09-11. The in-code default was 0; the LIVE value wins.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','warm_pool_template','"slim"'::jsonb,'"slim"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Sandbox template kept warm','Which sandbox template the warm pool pre-starts, and the template a create request gets when it names none.','agent','Was MATRX_WARM_POOL_TEMPLATE: slim on both tiers, read 2026-09-11.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('infrastructure.sandbox','warm_pool_templates','""'::jsonb,'""'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Per-template warm pool','Optional. A list like "slim:1,aidream:1" keeps EACH named template warmed to its own count; a bare name uses the "Sandboxes kept ready" count. When set it replaces the single-template pool above. Empty means off.','agent','Was MATRX_WARM_POOL_TEMPLATES: unset on both tiers = empty.','2026-10-11'::date,'a6c098d8-0a11-4465-b7dc-1a26cfd81252'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('knowledge.scraper','max_headline_block_chars','1500'::jsonb,'1500'::jsonb,'integer','characters','50'::numeric,'50000'::numeric,NULL::jsonb,'Largest headline block pulled into an article','A headline block longer than this is never pulled into the article body.','agent','Replaces MAX_HEADLINE_BLOCK_CHARS = 1500 in matrx-scraper parser/main_content.py; host-bound through configure_parser_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'953d8270-009a-41ed-85c0-8d9ee7c76093'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('knowledge.scraper','max_headline_block_ratio','0.3'::jsonb,'0.3'::jsonb,'number','ratio','0.01'::numeric,'1'::numeric,NULL::jsonb,'Largest headline block relative to the body','A headline block outside the article body is pulled in only when it is at most this fraction of the body''s length — a headline and dek, never a second column.','agent','Replaces MAX_HEADLINE_BLOCK_RATIO = 0.3 in matrx-scraper parser/main_content.py; host-bound through configure_parser_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'953d8270-009a-41ed-85c0-8d9ee7c76093'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('knowledge.scraper','max_link_text_ratio','0.55'::jsonb,'0.55'::jsonb,'number','ratio','0.01'::numeric,'1'::numeric,NULL::jsonb,'Most link text an article candidate may carry','A candidate whose text is more than this fraction links is a navigation rail, not an article.','agent','Replaces MAX_LINK_TEXT_RATIO = 0.55 in matrx-scraper parser/main_content.py; host-bound through configure_parser_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'953d8270-009a-41ed-85c0-8d9ee7c76093'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('knowledge.scraper','min_article_chars','500'::jsonb,'500'::jsonb,'integer','characters','50'::numeric,'50000'::numeric,NULL::jsonb,'Shortest candidate treated as an article','A content candidate with fewer characters than this is not considered the page''s article.','agent','Replaces MIN_ARTICLE_CHARS = 500 in matrx-scraper parser/main_content.py; host-bound through configure_parser_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'953d8270-009a-41ed-85c0-8d9ee7c76093'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('knowledge.scraper','min_main_content_chars','500'::jsonb,'500'::jsonb,'integer','characters','50'::numeric,'50000'::numeric,NULL::jsonb,'Shortest main content preferred over the page','A detected main-content block thinner than this is not worth preferring over the whole page.','agent','Replaces MIN_MAIN_CONTENT_CHARS = 500 in matrx-scraper parser/core.py; host-bound through configure_parser_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'953d8270-009a-41ed-85c0-8d9ee7c76093'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('legal.courtlistener','max_requests_per_second','1.2'::jsonb,'1.2'::jsonb,'number','requests/second','0.1'::numeric,'1.39'::numeric,NULL::jsonb,'CourtListener request rate','How fast the server is allowed to call the CourtListener legal-research API. Their limit is 5,000 an hour (about 1.39 a second) on conflict (feature,key) do nothing; 1.2 keeps headroom so a burst never gets the account throttled. Applies to the next client the server opens.','agent','Was the env var COURTLISTENER_MAX_RPS (unset everywhere) over the in-code 1.2. Maximum pinned at the provider''s own ceiling.','2026-10-11'::date,'32d748cc-b838-4e9f-9f94-c7644b249650'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('legal.courtlistener','max_retries','6'::jsonb,'6'::jsonb,'integer','retries','0'::numeric,'10'::numeric,NULL::jsonb,'CourtListener retries per request','How many times a CourtListener call is retried after a timeout or connection error before the ingest gives up on that page. Their service has flaky moments; six survives them without stalling forever.','agent','Was the env var COURTLISTENER_MAX_RETRIES (unset everywhere) over the in-code 6.','2026-10-11'::date,'32d748cc-b838-4e9f-9f94-c7644b249650'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('legal.courtlistener','request_timeout_seconds','60'::jsonb,'60'::jsonb,'number','seconds','5'::numeric,'300'::numeric,NULL::jsonb,'CourtListener request timeout','How long a single CourtListener call may take before it counts as failed. Some of their court-wide queries routinely run past 30 seconds; 60 gives the slow tail room without hanging an ingest.','agent','Was the env var COURTLISTENER_DEFAULT_TIMEOUT (unset everywhere) over the in-code 60.','2026-10-11'::date,'32d748cc-b838-4e9f-9f94-c7644b249650'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('mandate_honesty','change_claim_correction_turns','1'::jsonb,'1'::jsonb,'integer','turns','0'::numeric,'3'::numeric,NULL::jsonb,'Retries when an AI claims a change it did not make','When an AI whose job is to build something tells you it saved, updated or changed your work, the platform checks whether it actually wrote anything that turn. If it did not, it is sent back with its tools this many times and told to either make the change or say plainly that it did not. Once those turns are used up you are told directly that nothing was saved, so a described change is never mistaken for a finished one. Set to 0 to skip the retry and only be told.','agent','Chosen 2026-09-12 after the Masterwork Conductor twice told an Expert her desk was saved and live with an empty tool ledger (conversation 2050e02b-c663-4b6d-99f8-7996eff7cd81). In both observed cases one plain correction was enough: at 21:18:52Z it admitted the claim was empty and at 21:19:07Z/21:19:10Z it made the real workflow_plan + workflow_author calls. One turn reproduces the only recovery there is evidence for; a second automatic retry spends the person''s money re-asking an answered question, and past one failure the honest move is disclosure. Not org-overridable: a platform honesty backstop, not tenant policy.','2026-11-12'::date,'c874bd15-f368-4545-a0f1-e1e06632af26'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('mandates','cache_stamp_max_age_seconds','5'::jsonb,'5'::jsonb,'integer','seconds','1'::numeric,'120'::numeric,NULL::jsonb,'Fleet rebind bound','The longest a running process may trust its cached mandate definition and global-binding rows before re-checking the fleet freshness stamp. This IS the published promise "a rebind reaches every server within N seconds" — it is served to callers on the resolution response. Lowering it costs two aggregate queries per process per window; raising it delays how fast a global rebind reaches the whole fleet.','agent','Chosen 2026-08-31 to close V3-CORRECTNESS N1: the global rung and the definition row were cached per ECS task with no cross-task invalidation, so 5 of 12 identical resolution reads in one second served a DELETED global binding and 6 of 12 served a stale one after a rebind. 5 seconds is under one page interaction, and costs 0.4 queries/second/task against 696 definition and 339 binding rows. The user and org rungs are read uncached and are unaffected.','2026-10-31'::date,'965aeeec-3708-4759-a4bb-16b4d8a6c2e6'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('mandates','direct_value_max_chars','100000'::jsonb,'100000'::jsonb,'integer','characters','100'::numeric,'1000000'::numeric,NULL::jsonb,'Binding literal size ceiling','The largest literal a mandate binding may store for one holder input — a direct_value, or the pre-filled answer of a prompt_user. Both are substituted into the prompt on EVERY run, so an unbounded literal is unbounded spend and an unbounded row. Exceeding it is refused at the bind gate with the measured size and the limit in words.','agent','Chosen 2026-08-31 to close V3-CORRECTNESS F7: a 2,000,000-character direct_value was accepted with a 200 and stored (binding 71fd94de-b27a-437d-8d49-4734b00249ef, consumption_map 2,000,077 chars). 100,000 characters is ~25k tokens — generous for a literal a person types or pastes, and two orders of magnitude below the blob that was accepted. PLATFORM-LOCKED for the same reason as agent_exemplars.capture_max_chars: a spend/row-size backstop over a shared registry, not tenant policy — anything larger belongs in a document that is mapped, not pasted onto a binding.','2026-10-31'::date,'965aeeec-3708-4759-a4bb-16b4d8a6c2e6'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('mandates','max_depth','4'::jsonb,'4'::jsonb,'integer','levels','1'::numeric,'16'::numeric,NULL::jsonb,'Max mandate nesting depth','Maximum depth of nested mandate invocations (a workflow-held mandate whose child workflow itself invokes mandates). Cycles are refused outright at any depth; this knob bounds acyclic chains.','agent','Starting value per SPEC-workflow-ui-contract §6.6 (Arman-approved plan, 2026-08-27) on conflict (feature,key) do nothing; no measured data yet.','2026-11-27'::date,'965aeeec-3708-4759-a4bb-16b4d8a6c2e6'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('mandates','resolution_cache_ttl_seconds','300'::jsonb,'300'::jsonb,'integer','seconds','5'::numeric,'3600'::numeric,NULL::jsonb,'Mandate resolution cache TTL','How long a resolved mandate definition (and its exemplar count) is trusted in a worker process before it is re-read from mandate.definition. Raising it delays how fast an admin rebind reaches running workers; lowering it costs a DB read per resolution.','agent','Carried over from the hardcoded _CACHE_TTL_SECONDS=300.0 in aidream/services/mandates/service.py, itself chosen to match the workflow kind catalog. PLATFORM-LOCKED (overridable_by = ''{}''): process-cache freshness over a system-owned registry belongs to no tenant — an org lowering it would tax the shared DB for no benefit of its own.','2026-10-31'::date,'965aeeec-3708-4759-a4bb-16b4d8a6c2e6'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('mandates','resolution_miss_ttl_seconds','15'::jsonb,'15'::jsonb,'integer','seconds','1'::numeric,'600'::numeric,NULL::jsonb,'Mandate resolution miss TTL','How long a NEGATIVE resolution (mandate not found) is cached. Deliberately much shorter than the hit TTL so a mandate that boot-syncs a moment later is picked up quickly instead of refusing for a full cache window.','agent','Carried over from the hardcoded _MISS_TTL_SECONDS=15.0 in aidream/services/mandates/service.py. PLATFORM-LOCKED: negative-cache freshness is platform machinery, not tenant policy. Must stay <= resolution_cache_ttl_seconds (the miss path derives its stamp from the difference).','2026-10-31'::date,'965aeeec-3708-4759-a4bb-16b4d8a6c2e6'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('mandates','test_bench_history_limit','100'::jsonb,'100'::jsonb,'integer','results','1'::numeric,'1000'::numeric,NULL::jsonb,'Mandate test-bench result history limit','How many test-bench comparison results are retained on a mandate row''s metadata before the oldest are dropped. A retention cap on an unbounded jsonb array, not a feature allowance.','agent','Carried over from the hardcoded TEST_BENCH_RESULT_HISTORY_LIMIT=100 in aidream/services/mandates/testing.py. PLATFORM-LOCKED: the bench writes onto SYSTEM-owned mandate rows through a super-admin-only surface; there is no tenant whose policy this could be.','2026-10-31'::date,'965aeeec-3708-4759-a4bb-16b4d8a6c2e6'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('marketing.run_console','run_history_page_size','50'::jsonb,'50'::jsonb,'integer','runs','10'::numeric,'200'::numeric,NULL::jsonb,'Runs per page in Run history','How many runs the Run history tab of the SEO run console reads at a time. Load more reads the next page of the same filtered view.','agent','Set 2026-09-14 while fixing the unreachable Run history. 50 rows fill roughly two screens of the dense list and the paged read measured 15 ms (default view) to 90 ms (every run, 233k scheduler rows) on live volume, so a larger page costs little; 200 is the ceiling so one page never renders an unbounded list. Arman has NOT reviewed this number.','2026-11-13'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork','outcome_weights','{"miss": 0, "match": 100, "partial": 50, "cost_weight": 2, "risk_weight": 3, "dangerous_branch_penalty": 40}'::jsonb,'{"miss": 0, "match": 100, "partial": 50, "cost_weight": 2, "risk_weight": 3, "dangerous_branch_penalty": 40}'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'How a case desk''s path is scored','When your Masterwork works a sealed case, it is scored on two things: did it reach the answer the case only reveals at the bottom, and what did the path there cost. Reaching it scores the match value, getting the neighbourhood right scores the partial value, missing scores nothing. Every fact the desk had to ask for is then charged against that: cheap questions cost little, expensive or risky ones cost more (the cost and risk weights multiply what the case itself recorded). Committing to a course the published case shows would have harmed the subject subtracts the dangerous-branch penalty outright. Raise the weights to demand a leaner, safer path; lower them to care mostly about the answer.','agent','Chosen 2026-09-12 while building the Audition outcome mode. A match bought with ~8 cheap questions still reads as good work (100 - 2*8 = 84) on conflict (feature,key) do nothing; the same match bought with two high-risk invasive tests does not (100 - 3*12 = 64). The dangerous-branch penalty (40) exceeds the cost of the single riskiest question on purpose. Org-overridable because tolerance for a risky workup is tenant judgment, not a platform spend backstop.','2026-11-12'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork','rulebook_read_page_size','25'::jsonb,'25'::jsonb,'integer','rules','1'::numeric,'200'::numeric,NULL::jsonb,'Rules per page when a running Masterwork reads its Rulebook','When a step inside a Masterwork asks its own Rulebook a question (the rulebook_read tool), this is the most rules one answer may carry. The step is told how many matched and can ask for the next page, so a smaller number costs more calls and a larger number costs more of the step''s reading budget in one go. Raise it for a small Rulebook judged by a strong model; lower it for a large Rulebook judged by a cheap one.','agent','Chosen 2026-09-12 when the rulebook_read tool was built, after a Masterwork check step died three times with no way to query its own 416-rule Rulebook (trial 9, wall W67). 25 full rule bodies is roughly 3-5k tokens — enough that a section query is usually answered in one call, small enough that a broad query cannot swallow a judge step''s context. Org-overridable because how much of a step''s budget goes to rules is tenant policy, not a platform backstop. Arman has NOT reviewed this number. Review due 2026-11-12.','2026-11-12'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_daily_drip','default_channel','"email"'::jsonb,'"email"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Where a new daily question arrives','in_app, email or sms. This is only the starting choice the opt-in box is pre-filled with — whoever turns the drip on picks their own, and that pick is stored as their notification preference like every other notice on the platform. Text messages also need a verified phone number and consent, so the door asks for that before offering it.','agent','Agent-set 2026-09-15. Email is the only channel that works for every user on day one with nothing to set up and no carrier registration; SMS gets far better answer rates and is one tap away in the door for anyone who has verified a number. Arman has NOT reviewed this.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_daily_drip','min_answers_to_distill','3'::jsonb,'3'::jsonb,'integer','answers','1'::numeric,'100'::numeric,NULL::jsonb,'Answers needed before we''ll draw rules from them','How many days need an answer before this will look for the judgment behind them. Below this number it stops and tells you exactly how many answers are in and how many more it needs — it never quietly produces nothing. Raising it means fewer, better-evidenced rules; lowering it means rules drawn from a couple of mornings.','agent','Agent-set 2026-09-15. Three is the smallest number of days across which a habit is distinguishable from a single remark, and it is the same threshold the recurrence badge uses for the same judgment. It is also small enough that somebody who starts on Monday sees their first rules by Wednesday, which is what makes the habit stick. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_daily_drip','pause_after_silent_days','7'::jsonb,'7'::jsonb,'integer','days','0'::numeric,'90'::numeric,NULL::jsonb,'How many unanswered days stop the questions','A missed day is fine and costs nothing. But when this many questions in a row go unanswered we stop asking and say so, rather than filling up a busy person''s phone forever. Nothing is lost — starting again picks up where it left off. Set it to 0 to never stop asking.','agent','Named in the build brief (2026-09-15): default 7. A week is the shortest run of silence that cannot be explained by a holiday, a conference or a bad week, and it is the threshold habit apps use before they back off. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_daily_drip','question_set','"mixed"'::jsonb,'"mixed"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Which questions get asked','mixed rotates all three: what you decided that a new hire would have gotten wrong, what you fixed in someone''s work, and what you refused and why. Pin it to one — contrast, correction_log or refusal — if this person''s job only really produces one of the three.','agent','Agent-set 2026-09-15. The three probes come from the expert-distillation doctrine (CORE.md §5): the deviation from the consensus, the correction log, and negative space. Rotating them is what stops the drip becoming a form somebody fills in on autopilot by day four. Arman has NOT reviewed this.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_daily_drip','send_hour_local','8'::jsonb,'8'::jsonb,'integer','hour of the day','0'::numeric,'23'::numeric,NULL::jsonb,'What time of day the question goes out','The hour, on the answerer''s own clock, that their one question arrives. Each person can pick their own when they turn the drip on; this is the time it starts at. Early in the working day gets an answer about yesterday; late in the day gets an answer about today, while it is still fresh.','agent','Agent-set 2026-09-15 by the standard-lane session that built this lane. 08:00 local is the slot habit-forming products converge on (Duolingo, Headspace, Daily): it lands before the day''s work buries it, and it is the one time of day almost everybody looks at their phone. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_daily_drip','send_tick_cadence_minutes','60'::jsonb,'60'::jsonb,'integer','minutes','5'::numeric,'1440'::numeric,NULL::jsonb,'How often we check whether anyone''s question is due','This is not how often anyone is asked — each person is asked once a day, at the hour they chose. This is only how often we look. Hourly catches every time zone''s chosen hour on the hour. Making it longer means some people get their question late; shorter costs a little more and changes nothing else.','agent','Agent-set 2026-09-15. Each Expert''s send hour is their own setting, so the sweep only has to be fine-grained enough to hit an hour boundary in any time zone — hourly is exactly that and no finer. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_daily_drip','send_tick_enabled','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Send the daily questions automatically','When this is on, AI Matrx checks every hour and sends each person their one question at the time they picked. With it off, nothing goes out on its own — people can still send themselves today''s question from their Rulebook, and everything else about the daily question keeps working.','agent','🚨 SHIPS OFF, and only Arman turns it on. An unattended sender is standing spend and standing side effects with no human in the loop, which is what `common-docs/policies/no-unapproved-schedules.md` reserves to him — and since 2026-08-28 the approval IS this switch in the Admin UI, never a question in chat. Agents set the cadence; the existence is his.','2026-11-15'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','coherence_scan_auto_min_input_tokens','8000'::jsonb,'8000'::jsonb,'integer','tokens','0'::numeric,'2000000'::numeric,NULL::jsonb,'Smallest scan that auto sends to Batch','Only used when coherence_scan_urgency = auto: a scan whose rendered request is estimated at or above this many input tokens is batched; smaller ones run live.','agent','At claude-sonnet-5 input pricing an 8k-token scan costs about 2.4 cents live, so batching it saves about a cent while delaying the Expert''s questions by hours; above that the saving grows linearly with the Rulebook.','2026-11-14'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','coherence_scan_debounce_seconds','60'::jsonb,'60'::jsonb,'integer','seconds','0'::numeric,'3600'::numeric,NULL::jsonb,'Quiet period before a Coherence scan is queued','After a rules write, wait this long for more writes to the same Rulebook before rendering the scan, so a burst (a 50-source import) queues ONE scan of the final rules instead of one per write.','agent','The batch flusher already holds work up to 10 minutes before submitting, so a 60-second quiet period adds no user-visible delay while collapsing ingest bursts, which land rule writes seconds apart.','2026-11-14'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','coherence_scan_urgency','"batch"'::jsonb,'"batch"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,'["batch", "live", "auto"]'::jsonb,'How the Coherence Partner scan is dispatched','batch = half-price provider Batch API (questions appear within hours) on conflict (feature,key) do nothing; live = run immediately at full price; auto = live for small Rulebooks, batch for large ones (see coherence_scan_auto_min_input_tokens).','agent','Nobody waits on a coherence scan: its output is a review queue of questions the Expert settles later (census B1, 2026-09-14, $109.62/30d on claude-sonnet-5). Anthropic batch is 50% off and stacks with prompt caching on the Rulebook prefix, so batch is the default; an organization that wants questions in-session can pick live.','2026-11-14'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','markup_voice_default_on','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Red-Pen markup box opens with the microphone available','The Red-Pen lane''s promise is a five-second mic prompt — highlight, say why, move on. Off hides the microphone and the box is typed-only.','agent','The whole reason the lane exists is that reviewing is work the Expert already does and saying why is faster than typing why, so voice is on by default. Off is for organizations whose Experts work in open-plan offices or handle material they may not read aloud. Arman has NOT reviewed this default.','2026-11-15'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','max_rules_per_section','40'::jsonb,'40'::jsonb,'integer','rules','5'::numeric,'500'::numeric,NULL::jsonb,'Most rules in one Rulebook section','A section holding more rules than this is split. About one screen of scanning at a glance.','agent','Replaces MAX_RULES_PER_SECTION = 40 in aidream/services/distillation/sectioning.py (KNOB MIRROR: a synchronous pure function with a test on the value).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','meeting_min_moment_words','8'::jsonb,'8'::jsonb,'integer','words','1'::numeric,'200'::numeric,NULL::jsonb,'Shortest meeting turn read as a judgment','A continuous turn shorter than this many words is treated as back-channel ("yeah", "agreed", "next one") and is never sent to the scavenger. Lower it to catch very short vetoes; raise it on a meeting that is mostly chatter.','agent','Eight words is the smallest span that can hold a decision plus its reason ("no, we hold the shipment until legal signs") while still dropping every acknowledgement. Below about five a transcript is mostly back-channel and the run pays for portions with no rule in them; above about fifteen the sharpest vetoes ("we never sign without the survey") start being thrown away, which costs rules rather than money. Arman has NOT reviewed this number.','2026-11-15'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','meeting_own_turns_only','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Scavenge only the expert''s own turns','On: only the turns spoken by the expert whose Rulebook this is become rules; everyone else in the meeting is context that makes those moments legible. Off: every speaker in the room is read, for an organization building a house standard from a whole team.','agent','A Rulebook is ONE person''s judgment made reusable, and the expert approves each rule as "yes, that''s mine" (Masterwork doctrine CORE.md §5). A colleague''s line distilled into the expert''s Rulebook is not a weaker rule — it is the wrong person''s rule wearing the expert''s name, and review does not catch it once the quote sits under their heading. So the narrow read is the default and the whole-room read is a deliberate choice. Arman has NOT reviewed this default.','2026-11-15'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','min_corrections_before_distilling','3'::jsonb,'3'::jsonb,'integer','corrections','1'::numeric,'50'::numeric,NULL::jsonb,'Corrections needed before the Red-Pen lane distils','How many passages you have to mark up before the Red-Pen lane will turn them into rules. Below this the Distil button says how many more you need.','agent','One correction distilled alone almost always produces a rule that restates the correction (''don''t say X here'') rather than the standard behind it; the standard only becomes visible once the same preference has been applied to several different passages. Three is the smallest count that can show a pattern rather than a reaction — the same threshold, for the same reason, as the recurrence badge. A knob because an Expert reviewing a two-paragraph email and one reviewing a 40-page proposal do not agree about it. Arman has NOT reviewed this number.','2026-11-15'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','min_density_chunk_words','900'::jsonb,'900'::jsonb,'integer','words','100'::numeric,'10000'::numeric,NULL::jsonb,'Smallest chunk planned for dense material','Even the densest material is never chunked below this many words; under it a rule loses its own context and the distiller starts inventing.','agent','Replaces MIN_DENSITY_CHUNK_WORDS = 900 in aidream/services/distillation/source_structure.py (KNOB MIRROR: a synchronous pure function with a test on the value).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','min_section_words','150'::jsonb,'150'::jsonb,'integer','words','10'::numeric,'5000'::numeric,NULL::jsonb,'Shortest detected section kept','A detected section with fewer words than this (a table-of-contents line, a repeated heading) is merged into its neighbour instead of becoming a chunk of its own.','agent','Replaces MIN_SECTION_WORDS = 150 in aidream/services/distillation/source_structure.py (KNOB MIRROR: a synchronous pure function).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','min_sections','2'::jsonb,'2'::jsonb,'integer','sections','1'::numeric,'50'::numeric,NULL::jsonb,'Boundaries needed to trust a source''s structure','The source''s own headings are only believed when at least this many are found. One heading is a title page, not a spine.','agent','Replaces MIN_SECTIONS = 2 in aidream/services/distillation/source_structure.py (KNOB MIRROR: a synchronous pure function).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','min_triage_batch','10'::jsonb,'10'::jsonb,'integer','rules','1'::numeric,'500'::numeric,NULL::jsonb,'Smallest triage batch','A triage batch is never planned smaller than this, whatever the token ceiling says; below it the agent reads rules with no sense of the pile.','agent','Replaces MIN_TRIAGE_BATCH = 10 in aidream/services/distillation/triage.py (KNOB MIRROR: a synchronous pure function with a test on the value).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','recurrence_badge_pieces','3'::jsonb,'3'::jsonb,'integer','pieces','2'::numeric,'20'::numeric,NULL::jsonb,'Pieces before a rule is badged as recurring','A rule read from one piece of a body of work is a rule — you are asked about all of them. This number only decides when the Rulebook puts a "seen in N pieces" badge on one, so you can tell at a glance which judgments the author repeats across their work and which ones appear once. Lowering it badges more rules; raising it badges fewer. It never hides anything.','agent','Renamed 2026-09-12 from evidence_promotion_pieces, which decided whether a judgment EXISTED as a rule. The number is unchanged and its reasoning still holds: two pieces agreeing is a coincidence a prolific author produces dozens of times; three independent occurrences is the smallest count that reads as a habit, and matches the threshold qualitative-research practice uses to call a code a pattern. Arman has NOT reviewed this number.','2026-11-12'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_distillation','thin_part_min_words','800'::jsonb,'800'::jsonb,'integer','words','50'::numeric,'10000'::numeric,NULL::jsonb,'Shortest source part rated for yield','A part of a source shorter than this is too small for its rule yield to mean anything, so the thin-part comparison skips it.','agent','Replaces MIN_WORDS = 800 in matrx-frontend features/masterwork/sourceSections.ts (KNOB MIRROR: a synchronous pure function).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_prediction_ledger','min_resolved_to_distill','5'::jsonb,'5'::jsonb,'integer','predictions','1'::numeric,'100'::numeric,NULL::jsonb,'Scored predictions needed before we''ll draw rules from them','How many of your calls need a real outcome before this will try to find the reasoning behind them. Below this number it stops and tells you exactly how many outcomes are in and how many it is waiting on — it never quietly produces nothing. Raising it means fewer, better-evidenced rules; lowering it means rules drawn from a handful of calls, which can be luck rather than judgment.','agent','Named in the build brief (2026-09-15): default 5. Five is the smallest set in which a run of correct calls is not comfortably explained by coin-flipping, and it is small enough that a real Expert reaches it inside one working week. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_prediction_ledger','reminder_cadence_hours','24'::jsonb,'24'::jsonb,'integer','hours','1'::numeric,'720'::numeric,NULL::jsonb,'How often to remind you about predictions you haven''t scored','You call a real case and say when you''ll know how it turned out. When that date passes, we ask you what happened — because marking the outcome is what turns the call into a rule. This is how often we ask. Raising it means fewer nudges; lowering it means we catch outcomes while the case is still fresh in your mind. It never asks about a prediction whose date has not arrived.','agent','Agent-set 2026-09-15 by the standard-lane session that built this lane. The outcomes this Approach waits on — a claim closes, a candidate answers, a bid is awarded — land on a scale of days to weeks, so a daily ask is the slowest cadence that still reaches the Expert while the case is fresh, and anything faster is nagging about a world that has not moved. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork_prediction_ledger','voice_default_on','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Arm the microphone when you open the prediction box','Calling a case should cost seconds, and talking is faster than typing. With this on, the microphone is ready the moment the box opens and you can just say it. Turn it off if people here work somewhere they can''t talk out loud — typing always works either way.','agent','Named in the build brief (2026-09-15): voice default on. The Approach''s entire premise is that a prediction is cheap; asking someone to type three fields is what makes it expensive. Arman has NOT reviewed this.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.audition','max_vanilla_brief_chars','4000'::jsonb,'4000'::jsonb,'integer','characters','200'::numeric,'50000'::numeric,NULL::jsonb,'Longest brief handed to the plain-model arm','The founder''s plain-English ask is cut to this many characters before the comparison arm without a Rulebook reads it.','agent','Replaces MAX_VANILLA_BRIEF_CHARS = 4_000 in aidream/services/masterworks/audition.py (KNOB MIRROR: a synchronous helper).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.audition','outcome_max_text_chars','30000'::jsonb,'30000'::jsonb,'integer','characters','1000'::numeric,'500000'::numeric,NULL::jsonb,'Longest outcome text sent to the judge','Each arm''s answer is cut to this many characters before the outcome judge reads it.','agent','Replaces MAX_TEXT_CHARS = 30_000 in aidream/services/masterworks/audition_outcome.py; read live through knob_int.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.audition','outcome_vanilla_case_chars','60000'::jsonb,'60000'::jsonb,'integer','characters','1000'::numeric,'500000'::numeric,NULL::jsonb,'Longest sealed case shown to the plain-model arm','The sealed case text is cut to this many characters before the comparison arm without a Rulebook reads it.','agent','Replaces MAX_VANILLA_CASE_CHARS = 60_000 in aidream/services/masterworks/audition_outcome.py; read live through knob_int.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.audition','outcome_vanilla_output_tokens','4096'::jsonb,'4096'::jsonb,'integer','tokens','256'::numeric,'32000'::numeric,NULL::jsonb,'Most tokens the plain-model arm may answer with','The output budget for the comparison arm without a Rulebook in the outcome audition.','agent','Replaces MAX_VANILLA_OUTPUT_TOKENS = 4096 in aidream/services/masterworks/audition_outcome.py; read live through knob_int.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.audition','pairwise_max_differences','12'::jsonb,'12'::jsonb,'integer','differences','1'::numeric,'100'::numeric,NULL::jsonb,'Most differences kept from a pairwise verdict','How many of the judge''s listed differences between the two arms are kept in the verdict.','agent','Replaces MAX_DIFFERENCES = 12 in aidream/services/masterworks/audition_pairwise.py; read live through knob_int.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.audition','pairwise_max_text_chars','30000'::jsonb,'30000'::jsonb,'integer','characters','1000'::numeric,'500000'::numeric,NULL::jsonb,'Longest arm text sent to the pairwise judge','Each arm''s answer is cut to this many characters before the pairwise judge compares them.','agent','Replaces MAX_TEXT_CHARS = 30_000 in aidream/services/masterworks/audition_pairwise.py; read live through knob_int.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.bad_example_probe','generator_model','""'::jsonb,'""'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Which model writes the bad examples','Leave this empty and the bad examples are written by whichever agent this lane is bound to, using that agent''s own model — which is where a model belongs, visible and changeable on the agent itself. Set a model name here only when you want this one organization''s bad examples written by something else without changing the agent for everybody.','agent','ingest.py rule 1: the distillers'' and the generator''s definitions are in the database, and "the cost tier that used to be a MODEL constant is now the agents'' own model, which is what makes it visible and tunable without a deploy." Empty is therefore the correct default and the normal answer; this knob is the per-organization escape hatch, mirroring masterwork.triad_game.generator_model. A value this platform cannot resolve fails the round LOUDLY at run time, never quietly. Arman has not reviewed this default.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.bad_example_probe','rounds','5'::jsonb,'5'::jsonb,'integer','rounds','1'::numeric,'50'::numeric,NULL::jsonb,'How many bad examples one probe shows you','The Bad Example probe deliberately writes work that looks right and is not, and asks you what is wrong with it. This is how many it will show you before it stops on its own. You can always stop earlier by saying you would never see that, and you can choose fewer for a single sitting — this number is the most it will ever show.','agent','Boundary hunting (CORE.md §5, and the masterwork.interview `probe` knob''s own wording) ends on the Expert''s signal, not on a count, so this only has to reach the edge of their judgment without outrunning their attention: rounds 1-2 land on central judgment, 3-4 on the conditions around it, 5 is where a real expert typically starts refusing the premise. Each round is two paid calls (generate + distil), so five is also where a session''s cost stops being trivial. Org/user/rulebook-overridable because pace is taste. Arman has not reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.bad_example_probe','voice_default_on','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Start each round ready for you to talk instead of type','Turns on the microphone in the "what''s wrong with this?" box as soon as a round opens, so you can say what you caught out loud. If your browser cannot do dictation, nothing appears and you type as usual — it never shows you a button that does nothing.','agent','The Approach''s own published promise is that the catch is DICTATED ("Your catch is dictated straight into the rule''s detection field"), and advantage-stack.md Part III §3.1 stage 1.1 is "Audio and video first, because most experts are not writers." The client still only arms dictation where the browser supports it; this knob only says what to do when it does. Arman has not reviewed this default.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','cadence','"daily"'::jsonb,'"daily"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["daily", "weekdays", "every_other_day", "weekly"]'::jsonb,'How often sessions come round','The rhythm the planner spaces sessions on.','agent','Daily is the default because the whole premise is small and frequent; weekdays and every-other-day exist because most experts asked for a plan are employed, and weekly exists because some engagements are one session a week by agreement.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','flatten_window','3'::jsonb,'3'::jsonb,'integer','sessions','2'::numeric,'10'::numeric,NULL::jsonb,'How many empty sessions in a row mean the plan is done','The number of consecutive completed sessions that must produce nothing at all before the plan calls the yield curve flat.','agent','Three consecutive empty sessions across DIFFERENT methods is evidence; two is a bad afternoon. Below two this stops on noise, and above ten it stops wasting the Expert''s time far too late.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','horizon_days','14'::jsonb,'14'::jsonb,'integer','days','1'::numeric,'90'::numeric,NULL::jsonb,'The longest a plan may run','The outer bound on a plan''s schedule, whatever the Expert''s stated time budget.','agent','Two weeks is long enough for a daily ten-minute plan to produce a real yield curve and short enough that nobody is signing up for a quarter. Ninety days is the ceiling because a plan longer than that is an engagement, not a plan.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','methods_allowed','"all"'::jsonb,'"all"'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Which methods the plan may use','Either the string "all" — every live method the product can actually run — or an explicit list of Approach keys. A key that is not live is refused by name, never silently dropped.','agent','"all" is the honest default: the planner already refuses any method whose lane is not live, so an allow-list here can only ever subtract. Organizations that forbid a method (a regulated inbox, say) name the ones they permit.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','reminder_channel','"preferences"'::jsonb,'"preferences"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["preferences", "in_app", "email", "sms", "off"]'::jsonb,'Where the reminder arrives','Which channel a session reminder is sent on. "preferences" means the person''s own notification settings decide, which is the platform default and the one that cannot be wrong.','agent','Defaulting to the person''s own notification preferences is the only answer that does not override a choice they already made elsewhere; the explicit values exist because an Expert setting up a plan is exactly the moment someone says "text me".','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','reminder_horizon_hours','48'::jsonb,'48'::jsonb,'integer','hours','1'::numeric,'336'::numeric,NULL::jsonb,'How far ahead reminders are queued','Sessions due within this many hours get a reminder queued now. Sessions further out get theirs the next time the plan re-plans, which happens after every session.','agent','Forty-eight hours covers today and tomorrow, which is past every cadence the plan offers except weekly, so an Expert is never left without the next reminder. It also bounds one reconcile to a handful of notices instead of a fortnight''s worth — the fifty-six-row request that timed the browser out on 2026-09-15. The ceiling is 336 hours (two weeks), the longest plan horizon a knob can set.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','reminder_lead_minutes','0'::jsonb,'0'::jsonb,'integer','minutes','0'::numeric,'1440'::numeric,NULL::jsonb,'How far ahead the reminder goes out','Minutes before a session is due that its reminder is enqueued for delivery.','agent','Zero — the reminder IS the session invitation, and a session that can be done the moment it arrives is the whole bargain. The knob exists because a morning-of reminder for an afternoon slot is a reasonable org preference.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','session_minutes','10'::jsonb,'10'::jsonb,'integer','minutes','3'::numeric,'60'::numeric,NULL::jsonb,'How long one session should be','The length the planner sizes a single capture session to. A session is one method, once — a probe question, a triad round, one marked-up piece.','agent','Ten minutes is the longest slot a busy expert reliably gives without rescheduling, and it is long enough for every live lane''s shortest real session (the triad game is three minutes, the red-pen lane about ten). Shorter than three minutes and the lane cannot finish; longer than an hour and this is not a plan, it is a workshop.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','sessions_per_day','3'::jsonb,'3'::jsonb,'integer','sessions','1'::numeric,'8'::numeric,NULL::jsonb,'How many sessions fit in one day','The most sessions the planner will put on a single day, however much time the Expert offered.','agent','Three is the point where a day still reads as "a few short things" rather than a workload; it also gives the yield ledger three different methods to compare on day one instead of one.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','stop_rule','"either"'::jsonb,'"either"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["yield_flat", "coverage_met", "either", "horizon_only"]'::jsonb,'When the plan ends itself','What makes the program stop: the yield curve flattening, the goal''s coverage being met, either of those, or nothing but the end date.','agent','"either" is the doctrine''s own answer — CORE.md §5 says a stage that moves nothing is removed, and a program that keeps asking after it has stopped paying is the thing this build exists to avoid. "horizon_only" is kept for a fixed-length engagement someone has committed to.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','target_rules','25'::jsonb,'25'::jsonb,'integer','rules','5'::numeric,'200'::numeric,NULL::jsonb,'How many approved rules count as covered','The number of rules the Expert has APPROVED at which the goal counts as covered and the plan can stop.','agent','Twenty-five approved rules is roughly where a built Masterwork stops sounding generic in an audition, measured across the rulebooks built so far; it is deliberately counted in APPROVED rules, never drafts, because a draft nobody kept is not coverage.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.capture_plan','voice_default_on','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Start the goal box with the microphone armed','Whether the "what do you want covered" box opens with dictation ready, the way every other capture surface in Masterwork does.','agent','Matches the markup and monologue lanes, which both default the microphone on: an Expert describing a goal out loud says more than one typing it.','2026-10-30'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.ingest','live_lane_probe_interval_ms','5000'::jsonb,'5000'::jsonb,'integer','ms','1000'::numeric,'60000'::numeric,NULL::jsonb,'Live ingest lane probe interval','How often the ingest dialog re-checks whether its held answer has settled — two cheap local reads on this beat, only while the tab is visible.','agent','Replaces PROBE_INTERVAL_MS = 5_000 in matrx-frontend features/masterwork/durable-run/liveIngestLane.ts (KNOB MIRROR: armed synchronously in a timer).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.ingest','min_source_chars','200'::jsonb,'200'::jsonb,'integer','characters','1'::numeric,'10000'::numeric,NULL::jsonb,'Shortest source text a Masterwork accepts','A pasted source shorter than this is refused before it is sent, because there is nothing to distil from it. The server enforces the same floor.','agent','Replaces MIN_SOURCE_CHARS = 200 in matrx-frontend features/masterwork/components/detail/IngestSourceDialog.tsx, mirroring the server''s IngestTimelineRequest.text min_length (KNOB MIRROR: a synchronous form check).','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.interview','closing_surprises','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'End each session with what surprised the interviewer','When this is on, every interview finishes by writing down the three things you said that the interviewer did not expect, and saves them with the session so you can see them later. It is the fastest way to tell whether a session found anything that was not already written down somewhere.','agent','CORE.md §5 Acquisition: the value of a session is the signal that does not exist anywhere else, and the Magic Ledger names what stayed irreducible. Three is the number because it is short enough to read at a glance and forces the interviewer to rank rather than list. Default on: a session that produced no surprises is itself the finding. Off is a real choice for a short session where the summary is noise, so it is a knob rather than a constant. Arman has not reviewed this default.','2026-12-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.interview','context_mode','"auto"'::jsonb,'"auto"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["auto", "primed", "blank_slate"]'::jsonb,'What the interviewer knows about you before it starts','There are two good ways to be interviewed, and this picks which one you get. Primed means the interviewer reads your rulebook, your uploaded sources and everything you have already said before it asks its first question — it never wastes your time asking what it could have read. Blank slate means it is handed nothing at all except your name and what you are building, so it cannot get fixated on the documents and quietly turn the session into fixing them instead of capturing how you actually work; what it captures then lands beside the rules that came from your sources, and anything the two disagree about comes back to you as a question only you can settle. Automatic gives you the blank slate when there are no sources to read and the primed interviewer when there are.','agent','Arman, 2026-09-15: "there are two ways of doing an interview: the agent has all the context, or the agent has no context to begin with. Both are great." The default is `auto` because his own stated rule — blank slate when nothing is written down, primed when it is — is the only value that is right for both kinds of Rulebook, and a fixed default would be wrong for half of them. Ruling: CORE.md §7 and §8. Org/user/rulebook-overridable because this is method and taste, never a compliance control. Arman has not reviewed this default.','2026-12-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.interview','probe','["adaptive"]'::jsonb,'["adaptive"]'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'How the interviewer digs','The ways an interviewer can get at knowledge you have never written down. Adaptive lets it choose the right move each turn. Contrast asks what a competent peer would do here that you never would. Correction log asks what you keep fixing in a junior''s work. Prediction then reveal takes a real past case, asks what a peer would have done, then what you did, then why. Withheld replay has you redo an old case cold and compares it with what you actually did at the time. Boundary hunting generates near-miss variations until you say "I would never see that". Story time asks for a time it went badly and walks the timeline decision by decision. Rewind takes a decision whose outcome you already know and asks what you saw that others missed, and what only looks right in hindsight. You can pick more than one.','agent','The five named probes are stages 1.2–1.6 of the Acquisition phase in advantage-stack.md Part III §3.1, all marked ⬜ before this change; `adaptive` is the interviewer choosing per turn. Default `["adaptive"]` because pinning one probe for a whole session is a research setting (§3.6 measures probes against each other), not a first experience — the Expert narrows it when they want one specific move. Allowed values are enforced by the client and the mandate, not by a range, because this is a multi-select. Arman has not reviewed this default. 2026-09-15, second wave: `story_time` (the critical-decision method — one bad outcome walked as a timeline, every decision point a rule candidate with the story moment as its evidence) and `rewind` (hindsight on a decision whose ending is known, which is the only probe that separates a rule the Expert used from one that only looks right afterwards) join the list. The default is unchanged: two more moves the interviewer may choose is not a reason to stop letting it choose.','2026-12-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.interview','voice_default_on','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Start interviews ready for you to talk instead of type','The interview always lets you answer out loud — the microphone in the message box is there either way, wherever your browser supports it. This setting decides whether the interview also offers the hands-free voice bar beside it, so you can hold a spoken back-and-forth instead of dictating one answer at a time.','agent','advantage-stack.md Part III §3.1 stage 1.1: "Audio and video first, because most experts are not writers." Default on because the interview lane exists for people who talk better than they write. Corrected 2026-09-15 (migration 0712): the original sentence claimed this switch controlled the composer microphone, which is always present — an Expert who turned this off would have believed they had lost dictation. Arman has not reviewed this default.','2026-12-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.recovery','lost_piece_sweep_limit','200'::jsonb,'200'::jsonb,'integer','pieces','1'::numeric,'5000'::numeric,NULL::jsonb,'Lost corpus pieces reclaimed per sweep','How many stuck corpus pieces one scheduled sweep reclaims, so a backlog drains over several passes instead of one storm.','agent','Replaces LOST_PIECE_SWEEP_LIMIT = 200 in aidream/services/distillation/corpus_ingest.py; the sweeper reads it live, the function default is a KNOB MIRROR.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.recovery','lost_run_sweep_limit','200'::jsonb,'200'::jsonb,'integer','runs','1'::numeric,'5000'::numeric,NULL::jsonb,'Lost Masterwork runs reclaimed per sweep','How many stuck Masterwork runs one scheduled sweep reclaims.','agent','Replaces LOST_RUN_SWEEP_LIMIT = 200 in aidream/services/masterwork_runs.py; the sweeper reads it live, the function default is a KNOB MIRROR.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.recovery','max_recovery_attempts','3'::jsonb,'3'::jsonb,'integer','attempts','1'::numeric,'25'::numeric,NULL::jsonb,'Resumes before a Masterwork run is given up on','How many times one run is resumed after a deploy interrupted it before it is left as a defect for a person to look at.','agent','Replaces MAX_RECOVERY_ATTEMPTS = 3 in aidream/services/masterwork_recovery.py; read live through knob_int.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.recovery','max_resumes_per_pass','2'::jsonb,'2'::jsonb,'integer','runs','1'::numeric,'50'::numeric,NULL::jsonb,'Runs resumed per recovery pass','How many interrupted Masterwork runs one recovery pass actually restarts. Small on purpose: each restart runs a whole pipeline inside the sweeper''s own time budget.','agent','Replaces MAX_RESUMES_PER_PASS = 2 in aidream/services/masterwork_recovery.py; read live through knob_int.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.recovery','recovery_sweep_limit','25'::jsonb,'25'::jsonb,'integer','runs','1'::numeric,'500'::numeric,NULL::jsonb,'Orphaned runs examined per recovery pass','How many orphaned Masterwork runs one recovery pass looks at.','agent','Replaces RECOVERY_SWEEP_LIMIT = 25 in aidream/services/masterwork_recovery.py; the sweeper reads it live, the function default is a KNOB MIRROR.','2026-10-13'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.recovery','stalled_run_seconds','900'::jsonb,'900'::jsonb,'integer','seconds','60'::numeric,'86400'::numeric,NULL::jsonb,'How long a Masterwork run may make no progress before we end it','A running Masterwork narrates itself constantly — a piece read, a draft written, a judge answered. This is how long it may go without a single one of those before the platform stops reporting it as running, ends it, and says plainly that it stopped making progress and can be started again.','agent','Chosen 2026-09-15 as the backstop BELOW which nothing should ever reach it: one workflow step is already bounded at 600s by workflow.step_clock.default_step_seconds, so 900s leaves a five-minute margin in which the step''s own clock fires first and names the step — a far more useful sentence than "the run stalled". This row only catches what is not a workflow step (a distillation chunk, a judge call, an ingest fetch). Minimum 60s because it must never be tighter than one heartbeat interval; maximum 86400s for the same reason as the step clock. Propagation is instant: the heartbeat re-reads it every beat.','2026-12-15'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'instant','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.review','agenda_panel','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Show the next session''s agenda on the Rulebook page','The panel listing every rule the expert said is not theirs, or is theirs but came out wrong, with their own words. Turning it off hides the panel only — the interviewer still receives the same list before its first turn, because that is a provision, not a panel.','agent','Chosen 2026-09-15. On by default because the list is the expert''s own words about their own rules and hiding their open review work by default would be the screen lying by omission; off exists for an organization whose experts review in a different order. Org-overridable. Arman has NOT reviewed this default. Review due 2026-11-15.','2026-11-14'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{"help": "Show the rules waiting for the next interview on the Rulebook page.", "group": "Masterwork review", "order": 2, "control": "switch"}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.review','vocabulary','"auto"'::jsonb,'"auto"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["auto", "standard", "ownership"]'::jsonb,'What the rule review calls its buttons','Auto uses the expert''s own words ("Mine", "Mine but wrong", "Not mine") for a Rulebook whose expertise comes from a person we can ask, and the neutral words ("Approve", "Request changes", "Reject") for one distilled from somebody else''s material. Ownership or Standard forces one wording everywhere. The words change; the review states they write do not.','agent','Chosen 2026-09-15 from Arman''s ruling and doctrine CORE.md §5. Default is auto rather than ownership because the ownership question is unanswerable for a Rulebook distilled from a book — a reader cannot say whether Gio Valiante''s rule is "theirs" — and a screen must never ask a question the person in front of it cannot answer. Org- and user-overridable because it is pure wording: a company that trains its people on one vocabulary sets it once, and no setting of it can change which status a click writes. Arman has NOT reviewed this default. Review due 2026-11-15.','2026-11-14'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{"help": "The words on the buttons an expert uses to review their own rules. Nothing about what the buttons do changes.", "group": "Masterwork review", "order": 1, "control": "segmented"}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.rulebooks','cas_retries','3'::jsonb,'3'::jsonb,'integer','attempts','1'::numeric,'20'::numeric,NULL::jsonb,'Rulebook write retries on a version clash','How many times a Rulebook write is retried when another writer changed the Rulebook first, before it is reported as a conflict.','agent','Replaces CAS_RETRIES = 3 in aidream/services/masterworks/sealed_case.py; read live through knob_int at every retry loop.','2026-10-13'::date,'f9a25aa1-f5b9-42c1-a696-bebf70ff09c2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.shadow_inbox','days_back','30'::jsonb,'30'::jsonb,'integer','days','1'::numeric,'365'::numeric,NULL::jsonb,'How far back into your mail this looks','When you connect a mailbox, this is how many days back we look for threads you replied to. It changes nothing about pasting or uploading a thread yourself — that always reads exactly what you give it.','agent','Thirty days is one full billing and operations cycle, so the decisions that repeat — the monthly quote, the standing objection, the seasonal exception — show up at least once, while staying inside what a person still remembers writing. That last part is load-bearing: the review asks them "is this yours?" about their own sentences, and nobody can answer that about an email from four months ago. Org/user/rulebook-overridable because how much of their own mail an organization will have read is tenant policy, and the sharpest one in this lane. Arman has not reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.shadow_inbox','generic_reply_model','""'::jsonb,'""'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Which model writes the reply yours is compared against','Before we read your reply we have an AI draft the reply anyone competent would have sent — without ever showing it yours. The difference between the two is what becomes your rules. Leave this empty and that draft is written by whichever agent this lane is bound to, using that agent''s own model. Set a model name here only when you want this one organization''s comparison written by something else.','agent','ingest.py rule 1: an agent''s definition lives in the database, so empty — "the bound agent''s own model" — is the correct default and the normal answer, mirroring masterwork.bad_example_probe.generator_model and masterwork.triad_game.generator_model. It matters more here than there: the generic reply is the BASELINE the Expert is measured against, so a weaker model makes every Expert look brilliant and a stronger one is the honest, harder test. An organization that wants to set that bar deliberately can, without taking the platform binding over. Arman has not reviewed this default.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.shadow_inbox','own_replies_only','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Only read threads you actually replied to','On, this reads only the threads where you wrote the answer yourself — the only place your own judgment is. Turn it off for a shared or delegated mailbox where someone answers on your behalf and you want their replies read too.','agent','A thread the Expert never answered has no judgment of theirs in it, and filing a colleague''s reply under the Expert''s name is not a weaker rule — it is the wrong person''s rule, the same law the Meeting Scavenger''s own-turns knob states. The Masterwork product is one person''s deviation from the consensus (CORE.md §2), so mixing two voices under one name destroys the only thing being sold. Off is a real choice, not a mistake, for a shared mailbox. Arman has not reviewed this default.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.sorting_table','boundary_questions_per_round','5'::jsonb,'5'::jsonb,'integer','questions','1'::numeric,'20'::numeric,NULL::jsonb,'Boundary questions asked at the end of a round','After you sort, we ask you about the pairs that sat closest across a line — and about any pile you named and never used. This is how many we ask before the round ends.','agent','Each question is a spoken answer plus one paid distillation, so the number is set by where the Expert''s attention runs out, not by where the arithmetic does. Five covers all three edges of a default round plus the two tightest pairs overall, which is roughly where a second question about one edge starts repeating the first. Fewer questions is a real choice for an organization whose people play this in a queue. Arman has not reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.sorting_table','cases_per_round','20'::jsonb,'20'::jsonb,'integer','cases','1'::numeric,'60'::numeric,NULL::jsonb,'Cases on the table in one round','How many cases a round of the Sorting Table puts in front of you. You sort them with your thumb, about a second each, and then we ask you about the ones that sat closest on opposite sides of a line.','agent','This lane''s instrument is STATISTICAL: the boundary pass hunts for two cases that sit close across a pile edge, and for a pile nobody used. Neither question means anything on five cases. Twenty is where a three-pile round reliably has a genuinely tight pair on every edge, and at roughly a second a case it is still under a minute of thumb work — which is what makes it a thing somebody finishes between two other tasks rather than abandons. Org/user/rulebook-overridable because how much of somebody''s attention an organization will spend in one sitting is tenant policy. Arman has not reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.sorting_table','piles','3'::jsonb,'3'::jsonb,'integer','piles','2'::numeric,'4'::numeric,NULL::jsonb,'How many piles a round opens with','Two to four. You rename every pile on screen — these are just the ones the round starts with, and the names we suggest (Approve / Reject / Escalate) are only a starting point.','agent','Two piles is a straight yes/no and produces exactly ONE edge, which is one question out of a whole minute of sorting. Three adds the answer a real expert reaches for most — "this one isn''t mine to call" — and gives three edges, so one sitting probes three different boundaries. Above four the sort stops being thumb-speed and starts being a form. Three is the default and every name is the Expert''s to change, which is the difference between a default and a hardcoded taste. Arman has not reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.sorting_table','voice_default_on','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Arm the microphone when we ask about an edge','The sorting itself is wordless. The one place words are wanted is the edge, and on a phone that means talking. Turn this off for an organization whose people do this at a desk.','agent','Matches masterwork.triad_game.voice_default_on and masterwork.interview.voice_default_on, which are the same judgment about the same person on the same device. A microphone that is armed when it should not be costs one tap to dismiss; a missing one on a phone ends the session. Arman has not reviewed this default.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.teach_back','explanation_seconds','60'::jsonb,'60'::jsonb,'integer','seconds','10'::numeric,'600'::numeric,NULL::jsonb,'How long we talk before you get to interrupt','Each round we say your method back to you out loud. This is how long that takes — about sixty seconds is a hundred and fifty spoken words, enough to carry a whole decision including its exceptions. Shorter means more rounds on smaller pieces; longer means you hear more before you can correct it. You can interrupt at any point either way.','agent','Named in the build brief (2026-09-15): default 60 seconds. Sixty is long enough that the Expert hears a METHOD rather than a fragment — a decision plus its exceptions — and short enough that a busy person sits through it. It is also the length at which a wrong explanation is still repairable in ONE correction: a three-minute misunderstanding gets ''no, all of that'' instead of the precise catch this lane exists to capture. Org/user/rulebook-overridable because attention span is taste and a shop-floor expert is not a partner in an office. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.teach_back','rounds','6'::jsonb,'6'::jsonb,'integer','rounds','1'::numeric,'50'::numeric,NULL::jsonb,'How many times we''ll try before we stop on our own','The teach-back normally ends when you say ''yes, that''s it''. This is the most times it will explain and re-explain before stopping anyway. You can also choose fewer for one sitting — this number is the ceiling, never a target.','agent','Agent-set 2026-09-15 by the standard-lane session that built this lane. Six is one more than the Bad Example probe''s five, deliberately: a teach-back round is cheaper for the Expert (they listen and react rather than reading a fabricated document and critiquing it), and the goal here is CONVERGENCE rather than boundary-finding. Rounds one and two take out the big misunderstandings, three and four the conditions, five and six are where a method that will converge converges. A session still running at seven is not converging, and the honest answer is to stop and start again on a narrower decision. Org/user/rulebook-overridable because pace is taste. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.teach_back','voice_default_on','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Say it out loud, and be ready for you to talk back','On, we read each explanation aloud and have the microphone ready in the box where you correct it. The words are always on the screen as well — the voice never replaces them — so turning this off costs you nothing but the speed. Turn it off for people who work somewhere they can''t have sound or can''t talk out loud.','agent','advantage-stack.md Part III §3.1 stage 1.1: ''Audio and video first, because most experts are not writers.'' This lane''s specific claim is that a person interrupts a VOICE far sooner than they interrupt a paragraph they are reading, and the interruption is the product. One knob rather than two because the lane is a conversation: someone turning the voice off is turning off the conversation, not half of it. The client still only arms playback and dictation where the browser supports it. Arman has NOT reviewed this default.','2026-11-15'::date,NULL::uuid,'{organization,user,rulebook}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.triad_game','default_mode','"best_one"'::jsonb,'"best_one"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["best_one", "odd_one_out"]'::jsonb,'What a Triad card asks','''Which of these would you actually use?'' (best_one) or ''two of these are alike — which is the odd one?'' (odd_one_out). Both are built and both run; this is which one a round opens with.','agent','Agent-set 2026-09-15 (blind approval). odd_one_out is the classic repertory-grid elicitation and the sharper instrument, but the first card a non-technical Expert ever sees has to be answerable without being taught what the game is for — which best_one is. Arman has NOT reviewed this.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.triad_game','generator_model','"inherit"'::jsonb,'"inherit"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Model that writes the Triad cards','''inherit'' — the normal answer — means the card writer runs on whatever model its bound agent already uses, which is where a model belongs: visible and changeable in the mandates console. Set it only to run the card writer hotter or cheaper than the platform''s binding without taking the binding over. A value that cannot be resolved fails the deal loudly; it is never ignored.','agent','Agent-set 2026-09-15 (blind approval). ''inherit'' by default on purpose: a model named in two places is a model that drifts.','2026-11-15'::date,NULL::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.triad_game','triads_per_session','10'::jsonb,'10'::jsonb,'integer','cards','1'::numeric,'30'::numeric,NULL::jsonb,'Cards dealt in one sitting of the Triad game','How many three-item cards a round of the Triad game deals. The Approach promises about fifteen seconds a card, so ten is roughly a two-and-a-half minute sitting.','agent','Agent-set 2026-09-15 (blind approval). Ten cards is ~2.5 minutes at the Approach''s own published pace — a complete sitting somebody finishes on a phone rather than abandons, and a good round is re-dealt in one tap. Arman has NOT reviewed this number.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('masterwork.triad_game','voice_default_on','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Arm the microphone when the Triad game asks why','A one-line spoken reason is the whole point of this lane on a phone, so the microphone is ready by default. Turn it off for an organization whose people play it at a desk.','agent','Agent-set 2026-09-15 (blind approval), matching masterwork.interview.voice_default_on, which is the same judgment about the same person on the same device.','2026-11-15'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('mcp.organization_discovery','max_page_size','100'::jsonb,'100'::jsonb,'integer','organizations','1'::numeric,'1000'::numeric,NULL::jsonb,'MCP organization discovery page size','Maximum organizations returned by one MCP organizations.list page. This is a platform-only response ceiling and has no tenant override.','agent','Five small identity/display fields per organization make 100 useful batching while bounding one tool response. Review after the bootstrap has real MCP usage.','2026-10-27'::date,'6defe990-b755-421c-a6ef-521b90b44199'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('media.file_service','plaintext_max_portion_chars','200000'::jsonb,'200000'::jsonb,'integer','characters','1000'::numeric,'10000000'::numeric,NULL::jsonb,'Most characters kept per portion','Each portion of an extracted text or office document is trimmed to this many characters, and the extraction records the trim.','agent','Replaces MAX_PORTION_CHARS = 200_000 in matrx-files specific_handlers/plaintext.py; host-bound through configure_extraction_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'efd7290d-b8c9-4f4f-84fe-cd6d40376d7f'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('media.file_service','plaintext_max_portions','2000'::jsonb,'2000'::jsonb,'integer','portions','1'::numeric,'100000'::numeric,NULL::jsonb,'Most portions kept from one text file','A text file or office document is split into portions; past this many the rest is dropped and the extraction says so.','agent','Replaces MAX_PORTIONS = 2_000 in matrx-files specific_handlers/plaintext.py; host-bound through configure_extraction_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'efd7290d-b8c9-4f4f-84fe-cd6d40376d7f'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('media.file_service','plaintext_max_total_chars','20000000'::jsonb,'20000000'::jsonb,'integer','characters','10000'::numeric,'1000000000'::numeric,NULL::jsonb,'Most characters read from one text file','A text file is read up to this many characters (a 40 MB log is cut here) and the extraction records what it trimmed.','agent','Replaces MAX_TOTAL_CHARS = 20_000_000 in matrx-files specific_handlers/plaintext.py; host-bound through configure_extraction_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'efd7290d-b8c9-4f4f-84fe-cd6d40376d7f'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('media.listening','voice','""'::jsonb,'""'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Default voice','The voice that reads text aloud to you everywhere in the app.','human','USD-12 / done-bar item 2: media.listening.voice resolves through the ladder; "" = the purpose default (Skylar for reading, Daniel for replies).','2026-12-10'::date,'55be29cc-1eca-4d1e-b968-27a6d623a548'::uuid,'{organization,user,device}'::text[],'any',NULL::jsonb,'{"help": "Pick a voice and hear it right away.", "group": "Voice", "order": 1, "control": "voice", "preview": "cartesia"}'::jsonb,'instant','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('media.pdf','cpu_workers','0'::jsonb,'0'::jsonb,'integer','workers','0'::numeric,'64'::numeric,NULL::jsonb,'PDF processing threads','How many PDF operations (render, redact, compose, split) the server runs at once. 0 means one per processor core on the machine, which is the normal choice. Applies when the server next starts.','agent','Was the env var MATRX_PDF_CPU_WORKERS (unset everywhere = os.cpu_count()). 0 keeps that exact behaviour.','2026-10-11'::date,'2ce5a959-1111-437f-a158-0ca0766c6af6'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('media.pdf','ocr_workers','4'::jsonb,'4'::jsonb,'integer','workers','1'::numeric,'16'::numeric,NULL::jsonb,'Most OCR jobs at once','The most text-recognition (OCR) jobs the server runs at the same time. Each one uses a whole processor core, so it is capped at the machine''s core count regardless. Applies when the server next starts.','agent','Was the env var MATRX_PDF_OCR_WORKERS (unset everywhere) over the in-code cap of 4; the cap-at-cores rule is unchanged.','2026-10-11'::date,'2ce5a959-1111-437f-a158-0ca0766c6af6'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','agent_rejoin_grace_seconds','20'::jsonb,'20'::jsonb,'integer','seconds','0'::numeric,'300'::numeric,NULL::jsonb,'Note-taker rejoin grace','D9: how long to wait after the note-taker leaves a still-live meeting before dispatching a replacement. A deploy replaces the worker in seconds, and re-dispatching instantly would race the departing job''s own teardown.','agent','Twenty seconds covers a rolling task replacement without leaving a long unminuted gap.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','auto_end_after_empty_minutes','30'::jsonb,'30'::jsonb,'integer','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'Auto-end after an empty room','MRI-A6: how long a meeting''s room may sit EMPTY before the meeting is declared over. A meeting also needs its scheduled window (scheduled_for + scheduled_duration_minutes) to have passed, and LiveKit must confirm nobody is in the room. Evaluated on the next join, agent call or webhook for that meeting — there is no scheduler. A host ending the meeting explicitly is always immediate and ignores this value.','agent','Thirty minutes is long enough for a break, a reconnect, or a late arrival, and short enough that a forgotten meeting link stops admitting people the same morning.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','guest_join_enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Guests may join by link','D6: a meeting link works for anyone, who waits in the lobby until a host admits them. An organization that must not admit outsiders turns this off and every guest token request is refused at the server.','human','Zoom-style guest join is the product default; regulated tenants disable it.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'instant','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','guest_record_access','"summary"'::jsonb,'"summary"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["none", "summary", "full"]'::jsonb,'What a guest may read of a finished meeting','MRF-1: how much of the post-meeting record a GUEST — someone who attended by link, with no account in this organization — may read afterwards. "summary" (the default) shares the wrap-up summary, the decisions, the action items, the notes taken as the meeting happened and who attended; it does NOT share the word-for-word transcript or the recording. "full" adds the transcript and the recording. "none" keeps the record members-only: a guest following the link afterwards is told plainly that the record is not shared with guests. A host can choose a different level for one meeting from that meeting''s own screen, and that per-meeting choice wins over this value. A guest is always authorized by the room token their browser received when they were admitted — never by opening the database to anonymous readers.','agent','Arman ruled 2026-09-12 that guest access to the post-meeting record is a configuration, never a question: system default, organization override, per-meeting setting. "summary" is the starting value because the wrap-up is what a guest was in the meeting for, while a verbatim transcript and a recording of everyone''s voice are the parts an organization should have to choose to share.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','live_intelligence_transcript_chars','60000'::jsonb,'60000'::jsonb,'integer','characters','1000'::numeric,'500000'::numeric,NULL::jsonb,'In-meeting Q&A transcript budget','D3/D11: the most transcript, in characters, handed to an in-meeting question. Beyond this the oldest text is dropped rather than the request failing.','agent','Roughly 15k tokens — a long meeting''s worth of context without an unbounded bill per question.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','live_notes_window_seconds','300'::jsonb,'300'::jsonb,'integer','seconds','60'::numeric,'3600'::numeric,NULL::jsonb,'Live notes window','D3/D11: how much of the meeting each live-notes pass covers. Shorter windows mean fresher notes and more model calls.','agent','Five minutes is a natural agenda beat and keeps each pass cheap.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','max_recording_minutes','240'::jsonb,'240'::jsonb,'integer','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'Maximum recording length','Ceiling on a single LiveKit Egress recording. Egress is billed per minute, so this is the cost ceiling for one forgotten recording.','agent','Four hours covers an all-hands; anything longer is almost always a recording nobody stopped.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','note_taker_consent_notice_enabled','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Announce the note-taker to everyone','D10: when the AI note-taker joins, every participant is told — in the room data channel and on the agent''s own participant attributes — that the meeting is being transcribed. Turning this off does not hide the note-taker (it is always a labelled participant) on conflict (feature,key) do nothing; it only removes the explicit notice.','agent','Recording-consent litigation in this market punishes silent capture; announcing is table stakes.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','rejoin_sweep_seconds','10'::jsonb,'10'::jsonb,'integer','seconds','2'::numeric,'300'::numeric,NULL::jsonb,'Note-taker rejoin sweep','MRI-A15: how often each live note-taker worker re-checks for meetings whose note-taker is gone (handoff_pending, or transcribing with no agent in the room) and dispatches a replacement. agent_rejoin_grace_seconds decides how long to wait before the first try; this decides how often a warm worker retries. Without it the only recurring re-dispatch path ran at worker STARTUP, so every replacement waited for a cold task boot - 119 seconds measured against a 20 second grace window. Shorter means a shorter unminuted gap and one small query per worker per interval.','agent','Ten seconds keeps the worst case (grace + one sweep + join) around half a minute while costing one indexed query per worker every ten seconds.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','room_token_ttl_seconds','21600'::jsonb,'21600'::jsonb,'integer','seconds','300'::numeric,'86400'::numeric,NULL::jsonb,'Room token lifetime','How long a minted LiveKit room token stays valid. The client refreshes at 80% of it, so this is the longest a meeting can run without a successful refresh — not a meeting length cap.','agent','A 6-hour token covers any realistic meeting with one refresh margin; shorter values shrink the blast radius of a leaked token.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','stt_idle_close_seconds','30'::jsonb,'30'::jsonb,'integer','seconds','5'::numeric,'600'::numeric,NULL::jsonb,'Transcription stream idle close','D17: each speech-to-text stream is a persistent upstream websocket billed for its life. A speaker''s stream opens on their first non-silent audio and closes after this much silence, reopening the moment they speak again. Ten silent participants must not cost ten streams.','agent','Thirty seconds is longer than a normal conversational pause, so a listener who is thinking does not pay a reconnect, while a genuinely idle participant stops costing anything within half a minute.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('meet','stt_speech_rms_threshold','300'::jsonb,'300'::jsonb,'integer',NULL,'0'::numeric,'32767'::numeric,NULL::jsonb,'Speech energy gate','The 16-bit audio frame energy (RMS, 0-32767) that counts as someone speaking rather than room noise. No voice-activity plugin is installed, so this energy gate is what decides when a transcription stream opens. Raise it in a noisy room; lower it if quiet speakers are being missed.','agent','About -40 dBFS: well above the noise floor of a normal laptop microphone and well below ordinary speech.',NULL::date,'f40e033b-16b1-408e-9395-4f0931dea23d'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('messaging.conversation_ai','transcript_message_cap','200'::jsonb,'200'::jsonb,'integer','messages','10'::numeric,'2000'::numeric,NULL::jsonb,'Messages sent to a conversation intelligence','How many of a conversation''s most recent messages are sent when someone asks for a catch-up, a summary, action items, or a reply draft. Older messages are cut, and the answer says so. Higher means a fuller answer on long threads and a more expensive call; lower means cheaper, faster, and more likely to miss earlier context.','agent','The package shipped 200 hardcoded and it has been the live figure since adoption, so it is the only value with evidence behind it. At a typical in-app message length, 200 messages is roughly 20k characters — a real working thread, comfortably inside every current model''s window, and cheap enough to run on every button press. The range 10–2000 makes the floor "the last handful" and the ceiling a blast-radius backstop rather than an operating point.','2026-10-23'::date,'17083a50-bcee-4d2e-a132-ad2cbbfa684c'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('notify.digest','window_hours','24'::jsonb,'24'::jsonb,'integer','hours','1'::numeric,'168'::numeric,NULL::jsonb,'Digest look-back window','How many hours of pending digest-eligible notices the daily hr_notification_digest rolls into one hr.digest.daily notice per opted-in user. SPEC-NOTIFICATIONS §7.3.','agent','The spec''s platform default (P → O → U rung, 24h) — one calendar day of card notices per daily digest.','2026-11-28'::date,'2a40ca85-36cf-4156-95ab-dd341460ca50'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('ops.provider_outage','open_after_consecutive_failures','5'::jsonb,'5'::jsonb,'number','consecutive refused calls','2'::numeric,'100'::numeric,NULL::jsonb,'How many refusals in a row mean an AI provider is down','When an AI provider refuses this many calls in a row — a billing, key, permission or server-side refusal, not a bad request of ours — the platform raises ONE loud alarm saying that provider is down, and closes it by itself the moment the provider answers again. Lower means faster warning and more false alarms; higher means quieter and later.','agent','Chosen 2026-09-12 after Anthropic refused 578 consecutive calls in one hour with nothing on any page saying so. 5 is the smallest number that cannot be produced by ordinary bad luck: a single refused call is routine, two can be one bad model row, and five in a row within the window has never been observed from a healthy provider in our issue-event history. The alarm is per provider and opens ONCE — the 6th through 578th refusals add nothing but a refreshed counter — so the cost of being slightly early is one row, while being late is the three-hour silence this replaces.','2026-12-12'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('ops.provider_outage','payload_refresh_minutes','5'::jsonb,'5'::jsonb,'number','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'How often an open outage alarm updates its counts','While a provider is down, the platform keeps one open alarm rather than a new one per failed call. This is how often that single alarm refreshes its numbers — how many calls have been refused, which models were hit, what answered instead.','agent','Chosen 2026-09-12. The refresh is one UPDATE of one row, so 5 minutes keeps an operator watching the alarm within a useful distance of the truth while costing at most 12 writes an hour per downed provider — against the 578 rows an hour the unbatched alternative would have written tonight.','2026-12-12'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('ops.provider_outage','window_minutes','10'::jsonb,'10'::jsonb,'number','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'How long a quiet gap before a provider''s refusals stop counting as one outage','Refusals only count toward the same outage while they keep arriving. If a provider goes this many minutes without another refusal, the count starts over — so five refusals spread across a whole day never add up to a false alarm.','agent','Chosen 2026-09-12. 10 minutes is well above the executor''s retry and reroute cadence (a refused call is re-dialled within seconds) so a genuine outage always keeps its streak alive, and well below the length of a real incident — tonight''s ran 170 minutes. A much shorter window would break the streak on a low-traffic provider that is genuinely down; a much longer one would let unrelated refusals hours apart accumulate into an alarm.','2026-12-12'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('organizations.workspace','action_wait_ms','4000'::jsonb,'4000'::jsonb,'integer','ms','500'::numeric,'30000'::numeric,NULL::jsonb,'How long a button waits for the workspace','When a person presses a button before their workspace has finished loading, the action waits this long for it before saying the workspace is not available.','agent','Replaces ACTION_WAIT_MS = 4_000 in matrx-frontend features/organizations/awaitWorkspace.ts; read live through knobInt.','2026-10-13'::date,'b19cb38d-05d1-4bb9-a670-333a7a45c501'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('orm.write_retry','contention_retries','2'::jsonb,'2'::jsonb,'integer','attempts','0'::numeric,'10'::numeric,NULL::jsonb,'Extra attempts after a cancelled statement','When a database statement is cancelled because a migration wanted the same table, it is re-issued this many extra times before the error reaches a person.','agent','Replaces CONTENTION_RETRIES = 2 in matrx-orm core/async_db_manager.py (KNOB MIRROR: the database manager cannot read the database to configure itself).','2026-10-13'::date,'25ae8f5a-1934-452b-a985-2b8299c018ed'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('orm.write_retry','deadlock_backoff_base_ms','25'::jsonb,'25'::jsonb,'integer','milliseconds','1'::numeric,'2000'::numeric,NULL::jsonb,'How long to wait before the first retry of a rolled-back save','The first pause before re-trying a save the database cancelled for contention. It doubles on each further try, up to the maximum below, and the actual wait is a random amount up to that ceiling so several cancelled saves do not all come back at the same instant and collide again.','agent','Chosen 2026-09-12. A deadlock victim is rolled back the moment Postgres detects the cycle (deadlock_timeout is 1s server-side), so the winner is already committing when the victim wakes: the pause only has to outlast that commit, not the detection. 25ms is ~1 order of magnitude above a local commit and ~2 orders below the 1s detection window, so the retry lands promptly in the common case; full jitter (a random wait up to the ceiling) is the standard de-synchroniser for N callers that failed together.','2026-12-12'::date,'25ae8f5a-1934-452b-a985-2b8299c018ed'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('orm.write_retry','deadlock_backoff_max_ms','400'::jsonb,'400'::jsonb,'integer','milliseconds','5'::numeric,'30000'::numeric,NULL::jsonb,'The longest pause between retries of a rolled-back save','The ceiling on the doubling pause above, so a save that keeps colliding never waits longer than this between tries.','agent','Chosen 2026-09-12. With base 25ms the ceilings go 25/50/100/200ms and cap at 400ms, so the full 4-retry budget adds at most ~0.8s to a request that would otherwise have FAILED — cheap against a lost workflow run. Held well under the 10s pool-acquire timeout so a retrying write can never sit on a connection long enough to look like pool saturation.','2026-12-12'::date,'25ae8f5a-1934-452b-a985-2b8299c018ed'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('orm.write_retry','deadlock_max_retries','4'::jsonb,'4'::jsonb,'integer','attempts','0'::numeric,'10'::numeric,NULL::jsonb,'How many times to re-send a save the database rolled back for contention','When two saves touch the same records at the same instant, the database picks one and cancels it — nothing was saved, so it is safe to simply try again. This is how many extra tries that save gets before the work is reported as failed. 0 means never retry (a single collision fails the run, which is what happened before this existed).','agent','Chosen 2026-09-12 after workflow run d78b70ab lost a $0.35 run to ONE deadlock on users.user_secrets. The observed fan-out was 4 parallel invocations; 4 retries means a statement survives every one of its N-1 possible victim losses at that width and then some, while the exponential ceiling keeps the worst case under ~0.8s of added latency. Max 10 because contention that survives ten rolled-back attempts is structural — the remedy is then a lock ORDER fix (lock_rows_in_pk_order) or less overlap, never a higher retry count.','2026-12-12'::date,'25ae8f5a-1934-452b-a985-2b8299c018ed'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('persistent_cloud_browser','idle_stop_seconds','600'::jsonb,'600'::jsonb,'integer','seconds','0'::numeric,'86400'::numeric,NULL::jsonb,'Idle browser stop (seconds)','PLAN §Idle and expiration policy: an agent-controlled cloud browser that has run no command and served no screenshot for this long is checkpointed and stopped, freeing its fleet slot. Its profile survives; the next navigate restores it. A person driving, or a pending handoff, is never idle-stopped. 0 disables.','agent','PLAN proposed default of 10 minutes. On the one-worker canary (max_live_browser_fleet_runs=1) an idle browser otherwise holds the platform''s only slot until someone explicitly closes it — observed 2026-08-22 when a day-old idle run blocked every other user.','2026-10-04'::date,'dc051ac9-4937-46b2-bdab-a8f812812f25'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('persistent_cloud_browser','max_live_browser_fleet_runs','1'::jsonb,'1'::jsonb,'integer','runs','1'::numeric,'1'::numeric,NULL::jsonb,'Maximum live central browser runs','Maximum number of simultaneously live runs admitted to the current central browser fleet.','agent','The first production target has exactly one singleton browser worker. The limit is fixed to one until measured multi-worker placement exists; this prevents a second profile from being admitted to the same process.','2026-10-04'::date,'dc051ac9-4937-46b2-bdab-a8f812812f25'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.access','emergency_door_justification_min_chars','40'::jsonb,'40'::jsonb,'integer','characters','20'::numeric,'500'::numeric,NULL::jsonb,'Emergency access justification minimum','The shortest justification the emergency door will accept.','agent','HR''s floor is 20, which defeats "asdf". This door opens a person''s private data rather than an employment record, so the floor is doubled: 40 characters is one real sentence. Tightening only, for the same reason as the time box.',NULL::date,'c1e026b2-df9a-4f33-ba93-643cae16ef83'::uuid,'{organization}'::text[],'raise_only',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.access','emergency_door_ttl_minutes','120'::jsonb,'120'::jsonb,'integer','minutes','5'::numeric,'480'::numeric,NULL::jsonb,'Emergency access time box','How long an emergency-door grant lives before iam.permissions.expires_at kills it.','agent','GitHub publishes 120 minutes for its own break-glass and it is the strictest published number among the champions we measured; Google Vault publishes none at all. An organization may tighten it and may not widen it — an organization may promise its people MORE privacy than the platform does, never less (VISIBILITY-BY-CLASS §3.6).',NULL::date,'c1e026b2-df9a-4f33-ba93-643cae16ef83'::uuid,'{organization}'::text[],'lower_only',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.attention','poll_ms','60000'::jsonb,'60000'::jsonb,'integer','milliseconds','15000'::numeric,'600000'::numeric,NULL::jsonb,'How often the super-admin attention dock re-checks its sources','The dock composes schedule alarms and provider outages into one card on every super-admin page. Each source is re-read on this cadence, on window focus, and after any action taken from the dock. One minute reaches the screen while the problem is still the problem, at one cheap read per source per minute per open tab.','agent','Carried over from platform.system_errors.outage_poll_ms (2026-09-13), whose consumer became a source of the dock on 2026-09-14.','2026-11-15'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.auth','active_organization_cache_ttl_seconds','60'::jsonb,'60'::jsonb,'integer','seconds','0'::numeric,'300'::numeric,NULL::jsonb,'How long the server reuses what it knows about which organizations someone belongs to','Every request that says which organization it is working in has to be checked against that person''s memberships. Rather than asking the database on every single request, the server remembers the answer for this many seconds. Belonging to an organization decides whose data a request works with - it never decides what someone is allowed to do, which is always checked separately - so a short memory here is safe. If someone is removed from an organization by this server, the memory is dropped immediately; if they are removed anywhere else, it takes effect within this many seconds. Set it to 0 to switch the memory off entirely and ask the database every time.','agent','Chosen 2026-09-14 alongside the change-feed re-sizing: the same ~226-box / 30 s sandbox storm that surfaced the admin-tier read (0682) runs this membership read on every authenticated request too. 60 s matches both the platform''s knob-cache TTL and the admin-level cache TTL so operators have one number to reason about. The ceiling of 300 s bounds how long a membership revoked in another process (the frontend writes memberships client-direct to Supabase) can still scope a request; it is deliberately lower than the admin knob''s 600 s because this cache does remember grants, where the admin cache never does. Platform-locked ({} overridable_by): an authentication-path control, not a tenant preference.','2026-11-13'::date,'50be609f-768d-4509-a30d-cbd3e849a43a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.auth','admin_level_cache_ttl_seconds','60'::jsonb,'60'::jsonb,'integer','seconds','0'::numeric,'600'::numeric,NULL::jsonb,'How long the server reuses what it knows about who is an administrator','Every signed-in request has to know whether the caller is an administrator. Rather than asking the database on every single request, the server remembers the (very short) list of administrators for this many seconds. Being an administrator is never granted from memory — whenever the answer would raise someone above an ordinary user, the server re-checks the database first, so removing an administrator takes effect on their very next request no matter what this is set to. This number only decides how quickly a NEWLY added administrator is noticed by a server that is already running. Set it to 0 to switch the memory off entirely and ask the database every time.','agent','Chosen 2026-09-14 while fixing the sandbox change-feed storm: ~226 sandbox boxes polling every 30 s (~7.5 requests/second) each forced an uncached admin.admins read that held a database pool slot for up to 7.9 s under contention, surfacing as ChangeFeedShed / ChangeFeedDeadlineExceeded. 60 s matches the platform''s existing knob-cache TTL (feature_knobs KNOB_CACHE_TTL_SECONDS) so operators have one number to reason about, and costs at most one 6-row read per minute per process. It is safe to make large because the cache can only ever withhold elevation, never grant it; the ceiling of 600 s bounds how long a newly promoted administrator can go unnoticed. Platform-locked ({} overridable_by): this is an authentication-path security control, not a tenant preference.','2026-11-13'::date,'50be609f-768d-4509-a30d-cbd3e849a43a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.debug','config_parity_shadow','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Double-check the new message builder against the old one','While the AI message layer is being rebuilt, this runs BOTH the old and the new builder on every request, compares the two results, and files a report whenever they disagree. The old result is always the one used, so turning this on can never change an answer — it only costs a little extra work per request. Turn it on while a rebuilt piece is being proven, and off again once it is.','agent','Was the env var MATRX_PARITY_SHADOW (unset everywhere = off). USD-5: a behaviour switch in env let every machine disagree invisibly. aidream binds it in package_integration; matrx-ai never reads the environment.','2026-10-11'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.debug','orm_cache_debug','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Log database-cache hits and misses','When on, the server prints a line to its error log for every cached database lookup, saying whether it was answered from memory or fetched from Postgres (and the tenant-settings cache does the same). A diagnostic for "why is this hitting the database"; very noisy. Takes effect on the next server start.','agent','Was the env var MATRX_ORM_CACHE_DEBUG (unset everywhere = off). Read once at boot because matrx-orm configures its debugger once.','2026-10-11'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.debug','orm_cache_debug_noshow','"UiSurface,ui_surface"'::jsonb,'"UiSurface,ui_surface"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Models hidden from the cache log','A comma-separated list of model or table names the cache log above should stay quiet about, so a hot lookup does not drown everything else. Takes effect on the next server start.','agent','Was the constant {UiSurface, ui_surface} plus the env var MATRX_ORM_CACHE_DEBUG_NOSHOW (unset everywhere).','2026-10-11'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.debug','rag_ingest_step_log','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Write a step-by-step log for each knowledge ingest','When on, every knowledge-ingest run that was not handed its own log writes a human-readable, stage-by-stage trace file under tests/rag_tests/logs/. For diagnosing an ingest that produced nothing; off in normal operation.','agent','Was the env var MATRX_RAG_INGEST_STEP_LOG (unset everywhere = off) on conflict (feature,key) do nothing; the e2e harness used to set it.','2026-10-11'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.debug','tool_trace_db_sink_disabled','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Stop writing tool-call traces to the database','When on, tool-call events are no longer recorded in the trace table that the admin trace views and triage agents read. The local file keeps running. Turn on only to quiet a runaway loop; triage is blind while it is on.','agent','Was the env var MATRX_TOOL_DEBUG_DB_DISABLED (unset everywhere = DB sink on).','2026-10-11'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.debug','tool_trace_file_sink_disabled','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Stop writing the tool-call trace file','When on, the server stops appending tool-call events to its local trace file (.matrx-debug/). The database trace keeps running. Turn on only for a tight local loop that would otherwise fill the disk.','agent','Was the env var MATRX_TOOL_DEBUG_LOG_DISABLED (unset everywhere = file sink on).','2026-10-11'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.debug','tool_trace_verbose','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Record every tool call in full detail','When on, the tool-call trace log records the arguments and a preview of the result for EVERY call, not only the failed ones. Useful while chasing a call that "succeeded" but did the wrong thing. Leave off normally: the log and the trace table grow fast.','agent','Was the env var MATRX_TOOL_DEBUG_VERBOSE (unset everywhere = off). USD-5: a debug switch in env let every machine disagree invisibly.','2026-10-11'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.debug','verbose_asyncpg','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Show full tracebacks for harmless database reconnects','The connection pooler closes idle database connections and the driver reports each one as an error; the server normally collapses that known-benign noise into one line. Turn this on to see the full traceback while investigating a REAL connection problem.','agent','Was the env var MATRX_VERBOSE_ASYNCPG (unset everywhere = collapsed).','2026-10-11'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.external_api_prices','brave_search_usd','0.005'::jsonb,'0.005'::jsonb,'number','USD per request','0'::numeric,'1'::numeric,NULL::jsonb,'What one Brave web search costs us','Brave charges us for every web search request the platform makes. This is that price, so each search lands on the spend dashboard.','agent','Brave Search API public pricing (brave.com/search/api, read 2026-09-12): the Search tier is $5 per 1,000 requests = $0.005 per request. Brave applies $5/month of free credit, which this number deliberately ignores: a free credit is a discount on the invoice, not evidence that a request was free, and amortising it would make every search look cheaper than the next one actually costs. The Answers tier is billed differently ($4/1,000 plus token charges) and would need its own key if we start using it.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.external_api_prices','dataforseo_keyword_usd','0.05'::jsonb,'0.05'::jsonb,'number','USD per keyword task','0'::numeric,'1'::numeric,NULL::jsonb,'Fallback price for one DataForSEO keyword-data task','The backup price for a keyword research request, used only if DataForSEO ever answers without telling us what the request cost.','agent','DataForSEO Keywords Data API list price for a Google Ads search-volume task (~$0.05 per task, which covers up to 1,000 keywords in one request). FALLBACK ONLY, exactly as dataforseo_serp_usd: the provider''s own reported `cost` wins whenever it is present.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.external_api_prices','dataforseo_serp_usd','0.002'::jsonb,'0.002'::jsonb,'number','USD per SERP task','0'::numeric,'1'::numeric,NULL::jsonb,'Fallback price for one DataForSEO search-results task','DataForSEO tells us exactly what each request cost, and that real number is what we record. This is only the backup price, used if a response ever arrives without one, so a task can never be recorded as free.','agent','DataForSEO SERP API list price for Google Organic, Live Advanced (~$0.002 per task; the queued Standard mode is ~$0.0006). FALLBACK ONLY: every DataForSEO response envelope carries a top-level `cost` in USD, and matrx-seo''s transport hands that real figure to the recorder, which prefers it over this knob every time. This row exists so an envelope missing `cost` is priced rather than screaming.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.external_api_prices','google_cse_query_usd','0.005'::jsonb,'0.005'::jsonb,'number','USD per query','0'::numeric,'1'::numeric,NULL::jsonb,'What one Google Programmable Search query costs us','The price of a search run directly against Google''s own search API. Nothing on the platform uses it today — our Google results come through SerpAPI — so this setting is here and ready rather than missing on the day something does.','agent','Google Programmable Search Engine JSON API public pricing: $5 per 1,000 queries = $0.005 per query, after the free 100/day. NO CALL SITE EXISTS TODAY (2026-09-12): every "Google" search on the platform is SerpAPI''s google engine. Seeded anyway so the first direct CSE call is priced instead of recorded unpriced — a missing price screams, and the fix for a scream should already be on the shelf.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.external_api_prices','serpapi_search_usd','0.025'::jsonb,'0.025'::jsonb,'number','USD per search','0'::numeric,'1'::numeric,NULL::jsonb,'What one SerpAPI search costs us','SerpAPI sells searches in a monthly bundle rather than billing each one, so it never tells us the price of a single search. This is the number the platform charges each search to, so every web search we run shows up on the spend dashboard next to the AI calls instead of looking free.','agent','SerpAPI public pricing (serpapi.com/pricing, read 2026-09-12): Starter $25/month for 1,000 searches = $0.025 per search. Our account is on the Free plan (250 searches/month), so a search carries no incremental invoice TODAY — but recording $0 would make the ledger claim paid searches are free, which is the exact silence this ledger exists to end. $0.025 is the honest replacement cost: the price of the first plan we buy the moment we pass 250 searches in a month. If we move to Developer ($75/5,000) this becomes 0.015; Production ($150/15,000) 0.010.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.external_api_prices','twilio_sms_segment_usd','0.0083'::jsonb,'0.0083'::jsonb,'number','USD per message segment','0'::numeric,'1'::numeric,NULL::jsonb,'What one outbound text-message segment costs us','Twilio charges per segment, and a long text is several segments — a 200-character message is billed twice. This is the price of one segment, used to put every text we send on the spend dashboard. When Twilio later tells us the exact price of a particular message, that real figure is used instead.','agent','Twilio US SMS public pricing (twilio.com/en-us/sms/pricing/us, read 2026-09-12): $0.0083 per outbound segment from a US long code / 10DLC number, the same from toll-free. Carrier pass-through fees (roughly $0.003 per segment on 10DLC, carrier-dependent) are charged ON TOP and are deliberately NOT in this number: they vary by destination carrier and Twilio reports them separately. This knob is the base rate and can be raised to an all-in blended figure once a month of real invoices is in hand. Twilio''s create response almost always carries `price: null` (it prices a message after the carrier accepts it), which is why a knob is needed at all; whenever a price IS returned it is stored on communication.sms_messages.price and recorded instead of this estimate.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.lock_storm','dedup_window_seconds','300'::jsonb,'300'::jsonb,'integer','seconds','30'::numeric,'86400'::numeric,NULL::jsonb,'How long one storm stays one row','While a storm keeps sampling positive, re-observations bump occurrences on the SAME open system_error row instead of opening a new one. A storm quiet for longer than this window opens a fresh row.','agent','The detector samples on the runtime reaper''s 15-second tick, so a minute-long storm would otherwise file four rows for one event and an unbounded error table is a table nobody reads (the same discipline as the creator alarm''s dedup). Five minutes comfortably spans the 77-second incident plus its recovery while still separating a storm this afternoon from one tomorrow.','2026-12-15'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.lock_storm','waiter_count_threshold','5'::jsonb,'5'::jsonb,'integer','sessions','1'::numeric,'1000'::numeric,NULL::jsonb,'Blocked sessions before the lock-storm alarm fires','How many database sessions must be waiting on relation locks (all of them longer than waiting_seconds_threshold) before the platform records a system_error naming the blocker.','agent','The incident queued 12–18 PostgREST sessions. Normal steady state on this database is zero waiters beyond a second; a handful can appear briefly behind an ordinary migration or a hot-row update, so 5 sits well above routine noise and well below the incident, and any single long blocker that matters drags far more than 5 sessions with it.','2026-12-15'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.lock_storm','waiting_seconds_threshold','10'::jsonb,'10'::jsonb,'integer','seconds','1'::numeric,'3600'::numeric,NULL::jsonb,'How long a session must have been blocked to count','A waiting session is only counted toward the alarm once it has been blocked for at least this many seconds. Shorter waits are ordinary lock contention, not a storm.','agent','PostgREST''s statement timeout and the frontend''s patience both sit far above a second, so sub-second queues are invisible to users and must not alarm. The incident''s blocker held for 77 seconds: at 10 seconds the alarm fires roughly a minute before the users would have given up, which is the whole point of having one.','2026-12-15'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.reachability','selfheal_pause','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Freeze the nightly reachability self-heal','The nightly job checks whether the access visibility cache still agrees with a fresh derivation, and rebuilds it when it does not. Turn this on during a cutover that is deliberately rewriting who contains what, so the rebuild does not run against a half-moved graph. Detection and the incident report keep running while this is on — only the repair stops, and every skipped repair is filed as an urgent defect, because access is knowingly left wrong until you turn it back off.','agent','Default false: the repair is the thing that restores people''s access, so it runs unless a human deliberately freezes it. DD-259 / THE PLAN v2 D-16 — read live inside platform.heal_reachability_drift() through platform.knob_resolve, never a constant.','2026-10-15'::date,'c1e026b2-df9a-4f33-ba93-643cae16ef83'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.reference_picker','common_types','["conversation", "note", "task", "project", "file", "udt_document", "agent", "dataset", "workbook", "transcript", "url"]'::jsonb,'["conversation", "note", "task", "project", "file", "udt_document", "agent", "dataset", "workbook", "transcript", "url"]'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Add a reference — types offered first','The kinds of thing the "Add a reference" picker shows up front, in this order, when someone inserts a reference from the right-click menu. Everything else stays one click away under "All types", which always lists every reference-pickable entity — this setting curates the shortcut, it never hides anything. Values are entity type tokens (for example "conversation", which people see as "Chat").','agent','Arman 2026-09-11 asked for the common things "regardless of what they''re called… by that sort of name that they know", with an advanced "see more" for the rest. The eleven starting tokens are the entity types a general user names in their own sentences; ordered by how often a reference to one appears in written text, with the four things the product is used to make first.','2026-11-11'::date,'2ec639e8-6473-4cb2-b055-65d3efe8d28a'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.spend','fixed_monthly_usd','0'::jsonb,'0'::jsonb,'number','USD per month','0'::numeric,'10000000'::numeric,NULL::jsonb,'Spend dashboard — fixed monthly costs','What the invoice-billed services come to per month: hosting (AWS, Supabase, Vercel, sandbox machines) and plan-billed services such as email. Shown on the spend dashboard as a per-day figure beside the measured AI spend; never added into it. 0 means "not entered yet" and the page says so.','agent','Arman 2026-09-12: a cost the page cannot measure must still be on the page, honestly. Starts at 0 because only the person who pays the invoices knows the number; a guess would read as measured.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.spend_explorer','context_heavy_tokens','200000'::jsonb,'200000'::jsonb,'integer','tokens per call','1000'::numeric,'10000000'::numeric,NULL::jsonb,'Spend explorer — context-heavy line','A conversation whose average context per model call (input plus cached tokens divided by calls) is above this many tokens is listed under "dig here" as context-heavy. Every call re-sends the whole history, so cost grows with the square of the conversation length.','agent','Measured 2026-09-12: Opus calls on the two $100+ days averaged ~133k tokens of context; the $20–$96 conversations ran 250k–570k. 200k separates a long session from one that re-reads a novel on every call.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.spend_explorer','hog_share_pct','5'::jsonb,'5'::jsonb,'number','% of window','0.5'::numeric,'100'::numeric,NULL::jsonb,'Spend explorer — conversation hog share','A single conversation that alone accounts for at least this percentage of the selected window''s spend is listed under "dig here" as a hog.','agent','Measured 2026-09-12: one conversation took 38% of a 48h window. Five percent keeps the list to a handful — never empty, never everything.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.spend_explorer','iteration_heavy','10'::jsonb,'10'::jsonb,'integer','model calls per request','2'::numeric,'1000'::numeric,NULL::jsonb,'Spend explorer — iteration-heavy line','A single request that called the model at least this many times (tool loops) is listed under "dig here" as iteration-heavy.','agent','Measured 2026-09-12: ordinary agentic turns ran 2–8 model calls; the requests costing $3 or more ran 10–16. Ten is where a turn becomes a loop worth reading.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.spend_explorer','repeat_burst','5'::jsonb,'5'::jsonb,'integer','requests per 10 minutes','2'::numeric,'1000'::numeric,NULL::jsonb,'Spend explorer — repeat burst line','The same person, agent and feature firing at least this many requests inside one ten-minute bucket is listed under "dig here" as a repeat burst — the loop and retry-storm signature.','agent','A person typing does not send five requests to the same agent in ten minutes; a loop or a retry storm does. Five is low enough to catch the first minutes of a runaway.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.spend_explorer','spike_multiplier','3'::jsonb,'3'::jsonb,'number','× median hour','1.5'::numeric,'100'::numeric,NULL::jsonb,'Spend explorer — spike multiplier','An hour that cost more than this many times the median non-zero hour of the selected window is listed under "dig here" as a spike.','agent','Measured 2026-09-12: the 09-11 17:00 hour ran $27.50 against a median near $5 in the 48h window. Three keeps ordinary busy hours out of the list and catches a loop or a runaway job.','2026-10-27'::date,'d317850a-4a6e-4c75-b2ab-b8e1a037042a'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.spend_popover','scare_threshold_usd','100'::jsonb,'100'::jsonb,'number','USD','0'::numeric,'100000'::numeric,NULL::jsonb,'Daily spend popover — alarm threshold','When today''s AI and provider spend passes this many dollars, the popover and the dashboard headline switch to a destructive tone. It changes the colour and the wording only — nothing is ever blocked.','agent','Arman 2026-09-11: "scare me… not by putting blocks in the code." Measured 2026-09-12, the primary ledger ran $144.85 over the last 24h and $108.26 the previous local day, so $100 is the line above which a day is running hot rather than normal.','2026-10-27'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('platform.spend_popover','times_per_day','1'::jsonb,'1'::jsonb,'integer','times per day','0'::numeric,'6'::numeric,NULL::jsonb,'Daily spend popover — times per day','How many times a day a super admin is shown the floating "spent so far today" window. 0 turns it off. Each showing is dismissible, and a dismissal is remembered for the rest of that local day.','agent','Arman 2026-09-11 asked for "once a day or a couple times a day". One is the smallest cadence that still makes the number unavoidable; a second interruption has to earn itself, so it is available but not the default.','2026-10-27'::date,'413e7d19-c404-44c7-bf2d-04b75e19b319'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press','ingest_max_entries_per_run','200'::jsonb,'200'::jsonb,'number','entries','1'::numeric,'2000'::numeric,NULL::jsonb,'Max digest entries per ingest run','A pasted digest or webhook batch is truncated to this many entries per run; the truncation is reported loudly in the result and the remainder can be re-pasted (dedupe converges the overlap).','agent','Real HARO digests run 30-75 queries; 200 covers the largest observed digest formats with headroom while bounding parse and screen work. Matches the pre-existing 200-item cap on the webhook items array.','2026-10-15'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press','ingest_max_evaluations_per_run','40'::jsonb,'40'::jsonb,'number','model runs','0'::numeric,'500'::numeric,NULL::jsonb,'Max responder evaluations per ingest run','Ceiling on paid responder-mandate runs one ingest may spend. Rows beyond it still land (status new, outcome evaluation_deferred) and are scored later via POST /seo/press/source-requests/{id}/evaluate or a re-paste.','agent','One responder pass measured ~30-90s and one model call on 2026-08-24. 40 per paste bounds the worst case (many sites x many matching requests) to a knowable spend while comfortably covering the realistic case (a few sites, a handful of genuine matches per digest).','2026-10-15'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press.coverage','analyst_max_page_chars','12000'::jsonb,'12000'::jsonb,'integer','characters','1000'::numeric,'200000'::numeric,NULL::jsonb,'Page text the coverage analyst reads','How much of a captured page the coverage analyst reads — enough to place the brand in the article''s structure, short enough that one viral longread cannot cost more than the rest of a tracker''s pass.','agent','Replaces MAX_PAGE_CHARS = 12000 in aidream/services/coverage/analyst.py; read live through knob_int.','2026-10-13'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press.coverage','feed_max_rows','200'::jsonb,'200'::jsonb,'integer','rows','10'::numeric,'5000'::numeric,NULL::jsonb,'Most coverage mentions in one feed read','The most mentions one coverage feed or share-of-voice read loads at once.','agent','Replaces MAX_FEED_ROWS = 200 in aidream/services/coverage/feed.py; read live through knob_int.','2026-10-13'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press.coverage','max_analyses_per_tracker','25'::jsonb,'25'::jsonb,'integer','pages','1'::numeric,'500'::numeric,NULL::jsonb,'Pages analysed per tracker pass','How many captured pages one tracker pass sends to the analyst; bounds one pass''s AI spend.','agent','Replaces MAX_ANALYSES_PER_TRACKER = 25 in aidream/services/coverage/service.py; read live through knob_int.','2026-10-13'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press.coverage','max_byline_chars','80'::jsonb,'80'::jsonb,'integer','characters','10'::numeric,'500'::numeric,NULL::jsonb,'Longest text accepted as a byline','A byline longer than this is almost always a sentence the extractor grabbed by mistake, so it is dropped.','agent','Replaces MAX_BYLINE_CHARS = 80 in aidream/services/coverage/bylines.py (KNOB MIRROR: a synchronous pure function).','2026-10-13'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press.coverage','max_captures_per_tracker','25'::jsonb,'25'::jsonb,'integer','pages','1'::numeric,'500'::numeric,NULL::jsonb,'Pages captured per tracker pass','How many discovered pages one tracker pass captures; the rest wait for the next pass, and the truncation is logged and counted.','agent','Replaces MAX_CAPTURES_PER_TRACKER = 25 in aidream/services/coverage/service.py; read live through knob_int.','2026-10-13'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press.coverage','max_competitors','10'::jsonb,'10'::jsonb,'integer','competitors','1'::numeric,'100'::numeric,NULL::jsonb,'Most competitors on one tracker','A tracker watching more competitors than this is refused with the number, so the person splits it.','agent','Replaces MAX_COMPETITORS = 10 in aidream/services/coverage/trackers.py; read live through knob_int.','2026-10-13'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press.coverage','max_terms','20'::jsonb,'20'::jsonb,'integer','terms','1'::numeric,'200'::numeric,NULL::jsonb,'Most terms kept on a tracker','Brand and competitor term lists are trimmed to this many entries.','agent','Replaces MAX_TERMS = 20 in aidream/services/coverage/trackers.py (KNOB MIRROR: a synchronous pure function).','2026-10-13'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('press.coverage','min_brand_terms','1'::jsonb,'1'::jsonb,'integer','terms','1'::numeric,'10'::numeric,NULL::jsonb,'Fewest brand terms a tracker needs','A tracker with fewer brand terms than this is refused: it would match nothing and quietly look healthy.','agent','Replaces MIN_BRAND_TERMS = 1 in aidream/services/coverage/trackers.py; read live through knob_int.','2026-10-13'::date,'be76760d-7442-479b-aeca-27adec59fec8'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('prompt_preflight','context_window_trip_fraction','1.0'::jsonb,'1.0'::jsonb,'number','fraction of the context window','0.5'::numeric,'1.0'::numeric,NULL::jsonb,'How full a prompt may be before the step is stopped','Before any AI step sends its prompt, the platform measures it against the model''s context window and stops the step if it cannot fit — naming the step, the size, the window and what to fix, instead of letting the AI provider refuse it minutes and dollars later. This setting is how close to the ceiling a prompt may come before that happens: 1.0 stops only prompts that are over the window, 0.9 stops them a little earlier, with more room to spare.','agent','Chosen 2026-09-12 after workflow run cdde033d was refused by Anthropic at 1,019,616 tokens against a 1,000,000 window, six steps in, with no step name and no remedy. The estimator is chars/4 (the same divisor the context-trim gate uses) and runs LOW against real tokenizers, so 1.0 means a prompt must be plainly over the ceiling before the pre-flight fires — every refusal is a call the provider would have refused anyway. Max 1.0: a fraction above the window would only let a doomed call through. Org-overridable because how close to a ceiling a tenant runs is their policy, not a platform spend backstop.','2026-12-12'::date,'a88907bf-f7b4-4922-a9ee-e240c9007d48'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('proof_runs','max_run_seconds','900'::jsonb,'900'::jsonb,'integer','seconds','30'::numeric,'7200'::numeric,NULL::jsonb,'Hard ceiling on one proof run','A single proof run is abandoned and recorded as errored after this long, so a hung provider cannot hold a CI job, an API request, or a terminal open forever.','agent','The first check completes end to end in 75-90 seconds including a web-searching judge. 900 seconds is an order of magnitude above that, which tolerates a slow provider day without ever letting a hung run masquerade as a running one.',NULL::date,'f2d166c0-98a9-47ea-b26a-44efe4624404'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('proof_runs','min_live_interval_seconds','21600'::jsonb,'21600'::jsonb,'integer','seconds','300'::numeric,'2592000'::numeric,NULL::jsonb,'Floor between LIVE runs of one check','The shortest gap the platform will allow between two money-spending runs of the SAME proof check, regardless of what that check''s own live_every_seconds says. A per-check cadence set below this is clamped up to it.','agent','A live proof run is the only thing on the platform that spends real provider money with no user asking for it, so the floor exists to make a mis-set check row harmless. Six hours means the most eager check can cost at most 4x its per-run budget per day, and it is still short enough that a developer who wants a fresh live run after a fix waits hours, not days — they can also force one explicitly, which bypasses cadence but never the spend ceiling.',NULL::date,'f2d166c0-98a9-47ea-b26a-44efe4624404'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('proof_runs','monthly_spend_ceiling_usd','25.00'::jsonb,'25.00'::jsonb,'number','usd','0'::numeric,'10000'::numeric,NULL::jsonb,'Monthly spend ceiling for ALL live proof runs','Total real provider spend allowed across every proof run in a calendar month, BOTH modes. When the month-to-date total reaches it, the gate stops running checks at all — replays included, because a replay still runs the step under test for real.','agent','MEASURED, not estimated (2026-08-26): a LIVE run of news_self_validating costs $0.2689 — 4 provider calls, 41,040 tokens, 56.7s, including an Opus judge with web access. A REPLAY of the same check costs $0.0158: the external boundary comes from the recording, but the step under test (a tool-less model answering from the assembled context) still runs for real, which is the only reason a replay can catch a regression at all. At the 6-hour floor one check runs live ~4x/day (~$32/month if it were alone), and replays land on every pytest invocation. $25 buys a realistic small fleet at sane cadences plus hundreds of replays, while making a runaway impossible to pay for. The ceiling stops EVERY mode when reached, and the gate names it in the skip reason, so hitting it is visible, never silent.',NULL::date,'f2d166c0-98a9-47ea-b26a-44efe4624404'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('proof_runs','recording_max_bytes','262144'::jsonb,'262144'::jsonb,'integer','bytes','4096'::numeric,'4194304'::numeric,NULL::jsonb,'Ceiling on a stored replay recording','A live run records the real payloads its replay twin will feed back in. This caps the serialized recording; a run whose recording exceeds it is stored without one and says so, rather than writing a multi-megabyte row.','agent','The first check''s recording — headlines, search results, five scraped pages truncated to 1500 chars each, and three model answers — serializes to roughly 40-60KB. 256KB leaves 4-6x head-room for a bigger check while keeping the row inside comfortable jsonb territory and the table cheap to scan for the KPI reads.',NULL::date,'f2d166c0-98a9-47ea-b26a-44efe4624404'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('question_desk','default_view','"one"'::jsonb,'"one"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,'["one", "table"]'::jsonb,'How an interview opens','one = one question per screen with the queue in a rail (the Typeform shape) on conflict (feature,key) do nothing; table = the dense review table with every question on one line (the Linear shape). A person can override the platform default for themselves.','agent','Question Desk in-app build 2026-09-12 (QD-013); the reference page was one-per-screen','2026-12-12'::date,'db1d73de-d312-4713-95df-f852c05cbd6b'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('question_desk','drainer_cadence_minutes','5'::jsonb,'5'::jsonb,'integer','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'Question Desk drainer cadence','Minutes between drainer passes. The sch_trigger ticks every 5 minutes; this knob is the effective cadence the handler enforces. An answer is recorded within one cadence of its undo window closing.','agent','Agent-set: a person watching the row should see "recorded" within minutes, and a pass with nothing to do costs one query.','2026-10-16'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('question_desk','drainer_enabled','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Question Desk drainer enabled','Master switch for the question_desk_drain system tick. On = every answer given in a person''s own words is written verbatim into the owning node''s DECISIONS.md in common-docs within one cadence and the question row flips from "recording…" to "recorded". Off = answers wait, and the interview screen says so.','agent','Ships OFF: common-docs/policies/no-unapproved-schedules.md — a recurring job exists only by Arman''s approval, given by flipping this knob in the admin UI (the 2026-08-28 "the ask is a URL" ruling).','2026-10-16'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('question_desk','read_aloud_parts','["question", "background", "recommendation"]'::jsonb,'["question", "background", "recommendation"]'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'What Read aloud reads','The parts of a question read aloud, in order, when the reader presses R: any of question, background, ruled_before, the_best_do, today, implications, recommendation. Voice and speed come from the listening settings.','agent','Question Desk in-app build 2026-09-12 (QD-011): the mandate names the question, the background and the recommendation','2026-12-12'::date,'db1d73de-d312-4713-95df-f852c05cbd6b'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('question_desk','review_batch_size','10'::jsonb,'10'::jsonb,'integer','rows','3'::numeric,'50'::numeric,NULL::jsonb,'Decisions shown per review batch','The "Decided in your name" review serves decisions in batches of this many, highest weight first, with a visible "10 of 117 · 3 batches done". Never the whole list at once (Arman, 2026-09-13).','agent','Question Desk QD-024 (2026-09-14): Superhuman triage — one item, one keystroke, next','2026-12-14'::date,NULL::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('question_desk','rulings_writer_user_id','"4cf62e4e-2679-484f-b652-034e697418df"'::jsonb,'"4cf62e4e-2679-484f-b652-034e697418df"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'GitHub connection that records rulings','The user id whose GitHub connection (Settings → Integrations → GitHub) the drainer uses to write common-docs. That connection must hold contents:write on the docs repository; the drainer fails loudly, and the row says why, when it does not.','agent','Agent-set to the operator account: on 2026-09-16 it is the only GitHub connection whose installation covers AI-Matrix-Engine with contents:write (users.integration_connections). Point it at a bot account once one is connected.','2026-10-16'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('question_desk','skip_ships_recommendation','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Skipping a question ships the recommendation','When true, Skip records the recommendation as the decision in force ("default, not ruled") and the asking agent proceeds on it. When false, Skip only defers the question and nothing ships.','agent','Question Desk in-app build 2026-09-12 (QD-013) on conflict (feature,key) do nothing; grilling skill §4: skipped = the recommendation ships','2026-12-12'::date,'db1d73de-d312-4713-95df-f852c05cbd6b'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('question_desk','undo_window_ms','30000'::jsonb,'30000'::jsonb,'integer','ms','3000'::numeric,'300000'::numeric,NULL::jsonb,'Undo window after saving an answer','After an answer is saved in the question desk, the Undo link stays for this long.','agent','Replaces UNDO_WINDOW_MS = 30_000 in matrx-frontend features/question-desk/components/InterviewClient.tsx (KNOB MIRROR: a synchronous render path).','2026-10-13'::date,'db1d73de-d312-4713-95df-f852c05cbd6b'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','children.fan_out_ceiling','500'::jsonb,'500'::jsonb,'integer',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'How many child records one action may write or confirm','The most owned child records ONE emission may store, and the most ONE Confirm or Archive click may cascade to. Above it the action REFUSES OUT LOUD, naming exactly how many were not stored or not confirmed and offering the retry -- never a silent truncation and never a change of storage shape (KINDS-DESIGN-V2 §3.4 rule 3). DD-131 §3.4 / REVIEW-FLAG-DESIGN §2.4.','agent','KINDS-DESIGN-V2 §3.4 (DD-131 slice 2) seeded default','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,table}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','confirmation.agent_context','"confirmed_only"'::jsonb,'"confirmed_only"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["labeled", "confirmed_only", "exclude"]'::jsonb,'Do unconfirmed records enter an agent''s context, and how','The conversation that produced a row always sees its own, and an excluded row is always counted back to the agent (DD-131 §5.2). Enforced at the context-assembly service in aidream. SEEDED WITH THE OPERATIONAL DEFAULT: §4.2 makes this `labeled` on an `output` table, which needs the table `purpose` property of §2.5 — not built. DD-131 §4.2 key 5.','agent','REVIEW-FLAG-DESIGN §4.2 key 5 (DD-131) — operational default; per-purpose default pending §2.5 `purpose`','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,table,agent}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','confirmation.agent_write_born_confirmed','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'May this agent''s writes be born confirmed','FALSE means everything this agent writes is born unconfirmed — the platform default Arman ruled on 2026-09-12. Conjunction with records.confirmation.table_allows_born_confirmed: a row is born confirmed only if BOTH resolve true, so either rung saying no yields the safe value. DD-131 §4.2 key 1.','agent','REVIEW-FLAG-DESIGN §4.2 key 1 (DD-131) platform default','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,agent}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','confirmation.confirm_on_human_edit','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Does a person editing a record confirm it','TRUE — Arman, 2026-09-12: editing confirms. Applies to a single-record interactive edit only; a bulk operation never confirms (DD-131 §3.3). DD-131 §4.2 key 3.','agent','REVIEW-FLAG-DESIGN §4.2 key 3 (DD-131) platform default','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,table}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','confirmation.duplicate_hint','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Is the duplicate hint computed for unconfirmed records','TRUE. DD-131 §3.4 / §4.2 key 7.','agent','REVIEW-FLAG-DESIGN §4.2 key 7 (DD-131) platform default','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,table}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','confirmation.list_hides_unconfirmed','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Does a list hide unconfirmed records before anyone touches the filter','FALSE everywhere, whatever the table: unconfirmed rows SHOW, badged, with a one-click filter. Hiding them is this knob. Enforced at the list query builder in the shared table component so no feature can hand-roll a different default. DD-131 §4.2 key 4 (chair R4).','agent','REVIEW-FLAG-DESIGN §4.2 key 4 (DD-131) platform default','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,table,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','confirmation.outbound_requires_confirmed','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Must a record be confirmed before an automation may act on it outside the organization','TRUE — an email, publish, order or partner call does not fire on an unconfirmed row, and the run REPORTS what it skipped. Enforced at the outbound-effect executor in aidream. DD-131 §4.2 key 6.','agent','REVIEW-FLAG-DESIGN §4.2 key 6 (DD-131) platform default','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,table}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','confirmation.rollup_includes_unconfirmed','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Do unconfirmed records count in Rule-computed values and rollups','FALSE. Displayed record COUNTS are outside this knob and always show both numbers. Enforced at the Rule/Formula evaluator. SEEDED WITH THE OPERATIONAL DEFAULT: §4.2 makes this `true` on an `output` table, which needs the table `purpose` property of §2.5 — not built. DD-131 §4.2 key 8.','agent','REVIEW-FLAG-DESIGN §4.2 key 8 (DD-131) — operational default; per-purpose default pending §2.5 `purpose`','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,table}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('records','confirmation.table_allows_born_confirmed','false'::jsonb,'false'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'May this table accept born-confirmed agent writes','FALSE means no agent write to this table is born confirmed whatever the agent rung says. Conjunction with records.confirmation.agent_write_born_confirmed. DD-131 §4.2 key 2.','agent','REVIEW-FLAG-DESIGN §4.2 key 2 (DD-131) platform default','2027-03-12'::date,'c5d29fbf-fd62-40dd-afd0-9cd96d4cca93'::uuid,'{organization,table}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
