insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('scheduler','repeat_failure_any_cause','8'::jsonb,'8'::jsonb,'integer','runs','3'::numeric,'50'::numeric,NULL::jsonb,'Any-cause failure suspension','Consecutive failures of any cause before automatic suspension for a task that previously worked.','agent','Three same failures establish a pattern; eight mixed failures protect intermittently working batch tasks while preventing indefinite cost. Approved work order 2026-08-20.','2026-10-01'::date,'15090520-930f-400d-8dbd-fae984fa627a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('scheduler','repeat_failure_same_signature','3'::jsonb,'3'::jsonb,'integer','runs','1'::numeric,'20'::numeric,NULL::jsonb,'Same-signature failure suspension','Consecutive failures with one normalized signature before automatic suspension.','agent','Three same failures establish a pattern; eight mixed failures protect intermittently working batch tasks while preventing indefinite cost. Approved work order 2026-08-20.','2026-10-01'::date,'15090520-930f-400d-8dbd-fae984fa627a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('scheduler.alarms','failing_streak','2'::jsonb,'2'::jsonb,'integer','runs','1'::numeric,'10'::numeric,NULL::jsonb,'Consecutive failed runs before a schedule is reported as failing','One failed run between successes is noise (a lease that expired during a deploy, a transient provider error). This many terminal failures in a row, with no success between them, reaches the super-admin attention dock. The repeat guard still suspends at its own thresholds.','agent','Arman, 2026-09-14: a single transient failure pinned two SEO schedules on the global alarm for a day each. Two is the smallest streak that is not one.','2026-11-15'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('scheduler.alarms','overdue_grace_minutes','90'::jsonb,'90'::jsonb,'integer','minutes','1'::numeric,'1440'::numeric,NULL::jsonb,'Minutes past due before a schedule counts as overdue','An enabled schedule whose due time passed this many minutes ago without a run is reported to super-admins as overdue. Covers a slow scanner tick and a queue that is briefly behind.','agent','Carried over from the v1 alarm read (2026-08-24), which hardcoded 90 in the client call. Review against real scanner tick latency once the fleet is under load.','2026-11-15'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('scheduler.continuation','max_continuations_per_fire','3'::jsonb,'3'::jsonb,'integer','continuations','0'::numeric,'20'::numeric,NULL::jsonb,'Continuations per scheduled fire after a worker shutdown','When the server running a scheduled job is restarted (a deploy) or dies mid-run, the run is closed as interrupted and a continuation picks the work back up right away. This is how many times one fire may be continued before it is reported as a real failure. 0 turns continuation off.','agent','Three covers a fire that spans several deploys (the train ships every 20-30 minutes; the longest approved job runs ~170 minutes) while a job that keeps killing its own worker still reaches a person the same night. Mirrors MAX_CONTINUATIONS_PER_FIRE in packages/matrx-scheduler/matrx_scheduler/continuation.py (KNOB MIRROR).','2026-10-14'::date,'15090520-930f-400d-8dbd-fae984fa627a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('scheduler.lease','min_heartbeat_interval_seconds','5'::jsonb,'5'::jsonb,'number','seconds','1'::numeric,'60'::numeric,NULL::jsonb,'Minimum heartbeat interval for a run lease','A long-running job renews its lease at a third of the lease length, but never more often than this many seconds. Lower means a stuck job is noticed sooner at the cost of more database writes.','agent','Mirrors MIN_HEARTBEAT_INTERVAL_SECONDS in packages/matrx-scheduler/matrx_scheduler/lease.py (KNOB MIRROR).','2026-10-13'::date,'15090520-930f-400d-8dbd-fae984fa627a'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('search','public_providers','"brave"'::jsonb,'"brave"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Providers Matrx Search may run','Comma-separated provider names the public /search endpoint will accept. A provider not on this list is refused with a 400 rather than run.','agent','Brave only. The Google path is fully built and translates cleanly, but it runs on the SerpAPI plan rank tracking spends from (250 searches/month) — a public search box on that allowance would drain a paying customer feature to serve strangers. Turning Google on is this knob, not a deploy, the day the allowance can carry it or Google gets its own plan.','2026-10-23'::date,'1f6b7e75-a9e7-4999-b64a-7bea0362826b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('search','rate_limit_per_hour','300'::jsonb,'300'::jsonb,'integer','searches','1'::numeric,'20000'::numeric,NULL::jsonb,'Searches per person per hour','Per-user ceiling over a rolling 60 minutes on the public search endpoint — the slow-drip backstop the per-minute limit cannot see.','agent','Five searches a minute sustained for a full hour. A person researching all afternoon stays far under it; a bot pacing itself just under the per-minute limit is stopped by it. Same per-process caveat as the minute window.','2026-10-23'::date,'1f6b7e75-a9e7-4999-b64a-7bea0362826b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('search','rate_limit_per_minute','20'::jsonb,'20'::jsonb,'integer','searches','1'::numeric,'600'::numeric,NULL::jsonb,'Searches per person per minute','Per-user ceiling over a rolling 60 seconds on the public search endpoint. Exceeding it returns 429 with a Retry-After.','agent','A person searching hard runs a handful of queries a minute; 20 is several times that, so no real use ever touches it, while a script looping the endpoint hits it within seconds. Counters are per server process, so the effective platform ceiling is this value times the running task count — sized as an abuse backstop, not a billing meter. Lower it if provider spend spikes; raise it if a genuine power user reports being stopped.','2026-10-23'::date,'1f6b7e75-a9e7-4999-b64a-7bea0362826b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo','caller_daily_ceiling_usd','1.0'::jsonb,'1.00'::jsonb,'number','usd','0'::numeric,'10000'::numeric,NULL::jsonb,'Per-caller daily ceiling (public tools)','One caller — a signed-in user OR a guest/fingerprint identity — in one UTC day, for the public tools that spend platform funds on a stranger''s behalf.','agent','Unchanged in value, but only now usable: paired with the old $5.00 worst-case-call number it could never pass, because the projection ($5.00) always exceeded the ceiling ($1.00). At $0.25 head-room it allows roughly 200 SERP-class lookups or 16 competitor pulls per caller per day, against Ubersuggest''s 3 free searches/day and Semrush''s 10.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo','global_daily_ceiling_usd','50.00'::jsonb,'50.00'::jsonb,'number','usd','0'::numeric,'100000'::numeric,NULL::jsonb,'Platform-wide daily ceiling (public tools)','Every caller combined, in one UTC day, for the public tools.','agent','Sized as 1/15th of the monthly platform ceiling so a single bad day cannot consume the month. The previous $25 was set with no cost evidence.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo','global_provider_monthly_ceiling_usd','750.00'::jsonb,'750.00'::jsonb,'number','usd','0'::numeric,'1000000'::numeric,NULL::jsonb,'Platform-wide monthly ceiling, per provider','The blast-radius backstop across every organization combined. This is not an allowance anybody is sold; it is the number at which the platform stops paying a provider this month.','agent','Measured live spend across the entire history of seo.collection_run is $13.71 on DataForSEO and under $1 elsewhere. Realistic aggregate monthly spend with the plan ladder above is well under $100. $750 is ~7x that and still small enough to be a survivable accident; the previous $500 was set with no cost evidence at all.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo','inline_payload_max_bytes','32768'::jsonb,'32768'::jsonb,'integer','bytes','1024'::numeric,'10485760'::numeric,NULL::jsonb,'Inline raw-payload ceiling','A raw provider payload larger than this is written to cloud storage and the seo.raw_payload row keeps only a cloud_file_id pointer; anything at or under it stays inline as JSONB. Reads are identical either way (repository.load_raw_payload resolves the file transparently), so this is purely a storage decision.','agent','Measured live 2026-08-21/22: seo.raw_payload held 8,881 rows in 2.6 GB (2,608 MB of it TOAST) because the previous hardcoded 1,000,000-byte ceiling sat just above the 892 KB average payload — 8.8% of the entire 29 GB database, growing ~30 GB/yr. Measured against the real size distribution: a 32,768-byte ceiling keeps 1,089 rows totalling 4 MB in Postgres and sends 7,791 rows (7.7 GB uncompressed) to S3, while 65,536 would keep 13 MB and 1,000,000 would keep 3,241 MB. 32 KB is the knee of that curve and is 4x Postgres''s own 8 KB out-of-line TOAST threshold, so anything above it was already being stored outside the main heap — it just was not leaving the database. S3 Standard is ~$0.023/GB-month against Postgres storage that also carries backups, WAL and replication.','2026-10-21'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo','max_per_request_cost_usd','0.25'::jsonb,'0.25'::jsonb,'number','usd','0'::numeric,'100'::numeric,NULL::jsonb,'Worst-case single paid call','Head-room added to measured spend before every ceiling comparison, so one more call can never silently cross a ceiling. It is NOT a per-call price cap. Because it is added to the projection, every ceiling must be comfortably larger than it — a ceiling at or below this value rejects the very first call.','agent','The most expensive known single operation is a 1,000-row competitor link-gap pull at $0.06; the measured DataForSEO maximum on live rows is $0.128. $0.25 is ~2x the observed worst case and 20x the typical one. The previous $5.00 placeholder was larger than the $1.00 caller-daily ceiling it was added to, which made that ceiling reject every first call.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo','org_provider_monthly_ceiling_usd','50.00'::jsonb,'50.00'::jsonb,'number','usd','0'::numeric,'100000'::numeric,NULL::jsonb,'Per-organization monthly ceiling (fallback)','Used only when billing has no answer for this org — a standalone matrx-seo install, or an org whose plan and tier both have no seo.provider_spend limit. The real per-account allowance is billing.plan_limit for capability seo.provider_spend.','agent','Held at the value that was hardcoded before this migration so no organization loses ceiling on the day the ladder lands (THE NO-REGRESSION RULE).','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo','unpriced_run_assumed_cost_usd','0.01'::jsonb,'0.01'::jsonb,'number','usd','0'::numeric,'100'::numeric,NULL::jsonb,'Assumed cost of a paid run with no cost evidence','What a run against a PAID provider is charged against every ceiling when the provider reported no cost and we estimated none. A provider that reports a real 0.00 (Search Console, Bing Webmaster, PageSpeed, our own crawl) is measured as free and is never charged this.','agent','SerpAPI reports no cost at all: 112 live runs carry NULL in both cost columns and therefore counted as $0.00 against every ceiling before this change. $0.01 is at the top of the observed paid-per-query range (Brave estimates $0.005/run; DataForSEO averages $0.042/run but reports its own cost, so it never uses this number).','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo_ruling_session','queue_size','10'::jsonb,'10'::jsonb,'number','keywords','3'::numeric,'50'::numeric,NULL::jsonb,'Keywords fetched per ruling batch','How many diverse, high-demand keywords the session holds at a time before asking the server for more.','agent','Ten covers a full sitting at the five-ruling unlock with room to skip, while keeping the diversity walk cheap (the server scans forty candidates per slot).','2026-11-22'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo_ruling_session','rulings_before_trial','5'::jsonb,'5'::jsonb,'number','rulings','1'::numeric,'50'::numeric,NULL::jsonb,'Rulings before the system offers to try','How many keywords a person must rule in a session before "Let the system try the next N" unlocks. Below this the system has too few examples of the person''s reasoning to imitate anything.','agent','Arman, 2026-08-24: "maybe you answer five of these or ten of these, and then you click a button where the AI attempts to do the same thing with twenty of them." Five is the lower end of what he named, chosen so the loop is reachable in a first sitting; raise it if trial accuracy at five proves poor.','2026-11-22'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo_ruling_session','trial_batch_size','20'::jsonb,'20'::jsonb,'number','keywords','5'::numeric,'100'::numeric,NULL::jsonb,'Keywords in one trial batch','How many keywords the system proposes at once in the trial, for the person to correct.','agent','Arman named twenty explicitly. It is also about the largest grid a person can scan and correct without scrolling losing them.','2026-11-22'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.ai_autonomy','proposal_keyword_cap','500'::jsonb,'500'::jsonb,'integer',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Keywords carried by one proposal','How many keyword ids a single "this is what I would stamp" proposal carries. Beyond it the proposal names the total and carries the highest-demand slice.','agent','A proposal card has to be readable and its payload has to fit a jsonb column a reviewer will scroll. The largest situational segment measured live is All Green Recycling at 27,234 keywords (2026-08-23) — a proposal carrying that is not a review, it is a data dump. 500 is roughly the size of a full afternoon of human spot-checking and keeps the assist row under ~20 KB. The proposal always reports the true total, so the cap can never masquerade as the whole segment.','2026-11-23'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.ai_autonomy','timeout_apply_cap','200'::jsonb,'200'::jsonb,'integer',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Proposals auto-applied by one timeout pass','How many timed-out proposals one bounded pass applies before stopping. What it does not reach stays pending for the next pass.','agent','The timeout pass rides an engine run, so it must fit inside that run without turning a bounded pass into an unbounded one. Applying a stamp proposal is one keyword_facet_set call per proposal (~0.32 ms/row write, measured 2026-08-23) and real sites carry single-digit pending proposals today, so 200 is far above live volume while still bounding a pathological backlog. Raise it only after measuring a real backlog drain.','2026-11-23'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.business_discovery','reading_homepage_chars','6000'::jsonb,'6000'::jsonb,'integer','chars','500'::numeric,'60000'::numeric,NULL::jsonb,'Homepage excerpt size','How many characters of the homepage''s extracted content the cold-read document carries. The homepage states the business; it gets the largest excerpt.','agent','The sample homepage''s full extracted content is ~6k chars; the cap admits all of it. Doubled it would admit footer/nav repetition, the main noise source in extracted markdown.','2026-10-05'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.business_discovery','reading_max_pages','14'::jsonb,'14'::jsonb,'integer','pages','1'::numeric,'60'::numeric,NULL::jsonb,'Site-reading page budget','How many pages the Business Discovery Ladder includes in the cold-read document handed to each step agent: the homepage plus the shallowest real pages.','agent','Measured on the flagship sample (datadestruction.com, 2026-08-24): 14 pages composed a 50,363-char document — the homepage plus every depth-1 service/industry/compliance hub, comfortably inside one Gemini Flash call with room for the step artifacts steps 2-6 add. More pages add blog noise faster than business signal.','2026-10-05'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.business_discovery','reading_page_chars','2500'::jsonb,'2500'::jsonb,'integer','chars','200'::numeric,'30000'::numeric,NULL::jsonb,'Per-page excerpt size','How many characters of each non-homepage page''s extracted content the cold-read document carries; headings ride separately and cheaply.','agent','Service pages state their offer in the first ~2k chars (measured on the sample''s 13 depth-1 pages) on conflict (feature,key) do nothing; 2,500 keeps 14 pages near 50k chars total.','2026-10-05'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.dimension_coverage','low_coverage_click_pct','20'::jsonb,'20'::jsonb,'integer','percent','0'::numeric,'100'::numeric,NULL::jsonb,'Low dimension coverage threshold','Below this share of the window''s clicks, filtering by a dimension warns that the corpus is not classified yet.','agent','On Data Destruction''s 90-day window, platform dimensions cover between 0% and 55% of clicks. Below 20%, a filtered slice describes the backfill queue more than the business. Re-measure with multi-site data before changing it.','2026-11-23'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.dimension_coverage','window_days','90'::jsonb,'90'::jsonb,'integer','days','1'::numeric,'480'::numeric,NULL::jsonb,'Dimension coverage window','How many days of history the Dimensions screen measures coverage over.','agent','Ninety days matches the established inert-feature coverage strips and smooths weekday seasonality while remaining recent enough to expose an incomplete classification corpus.','2026-11-23'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_classification','batch_keywords','200'::jsonb,'200'::jsonb,'integer','keywords','40'::numeric,'200'::numeric,NULL::jsonb,'Keywords per backfill pass','How many keywords one scheduled pass (or one press of Classify next) claims and sends through the classifier.','agent','The classifier endpoint hard-caps a request at 200 and runs 40 keywords per model call, so 200 keywords is five calls. Measured live 2026-08-21: one 40-keyword pass takes 110 seconds end to end. Its DOLLAR cost is NOT currently measurable — this classifier path writes no chat.request / user_request / billing.usage_ledger row, so its spend is invisible to every ledger and to the seo spend ceilings (defect filed 2026-08-21). Until that is fixed, size this knob on wall-clock and on the daily ceiling below, never on a cost figure. Raising it buys nothing: the cap is the endpoint''s.','2026-10-20'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_classification','click_tail_enqueue_max','5000'::jsonb,'5000'::jsonb,'integer','keywords','0'::numeric,'50000'::numeric,NULL::jsonb,'Historical click-tail keywords enrolled per pass','Keywords that used to earn Search Console clicks but have none inside the demand window are still worth understanding — a keyword that stopped earning clicks usually means a lost ranking. This setting caps how many of them one pass may add to the classification queue. They are always worked after live demand, never instead of it. Set it to 0 to stop enrolling them at all; the count still left outside the queue is always reported.','agent','Measured live 2026-09-12: 152,197 of 228,559 live keywords were outside the queue, but only 2,073 of them have ever earned a click (118 with at least 5, 18 with at least 20). 5,000 clears that entire tail in one pass with roughly 2.4x head-room for growth, and costs about 11 classifier batches — half of one day of the approved 4,000/day ceiling, once. It is deliberately far below the ~150,000 impression-only keywords, which would cost about 38 days of the whole budget on evidence that suggests nothing. The daily_keyword_ceiling remains the real spend backstop; this knob bounds ENROLMENT, so a mis-set value costs queue rows, not model calls. Not org-overridable: the universal facet plane is one shared classification per phrase, so there is no tenant whose policy this could be. Arman has NOT reviewed this number. Review due 2026-12-12.','2026-12-12'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_classification','daily_keyword_ceiling','4000'::jsonb,'4000'::jsonb,'integer','keywords','0'::numeric,'200000'::numeric,NULL::jsonb,'Keywords classified per UTC day','The blast-radius backstop on the whole backfill. Once a UTC day has classified this many keywords, every further pass stops and reports the ceiling instead of spending more.','agent','The entire click-earning universe is 1,442 keywords (live count, 90-day window, 2026-08-21), so 4,000/day clears everything that has ever earned a click on day one and still bounds a runaway loop to twenty passes. This ceiling is the ONLY thing bounding a runaway, and it must be treated as load-bearing precisely because this path''s spend is not recorded anywhere (defect filed 2026-08-21): nothing downstream can notice an overspend, so nothing downstream can stop one. 4,000/day is 100 model calls.','2026-10-20'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_classification','demand_window_days','90'::jsonb,'90'::jsonb,'integer','days','7'::numeric,'730'::numeric,NULL::jsonb,'Demand rollup window','How far back the backfill measures Search Console clicks and impressions when it decides which keyword to classify next. Keywords with no traffic inside this window are not in the queue at all.','agent','Measured live 2026-08-21: 194,031 keywords have GSC history all-time, but only 67,884 drew any impression in the last 90 days. The older 126,000 are demand the business no longer feels, and classifying them first would spend the whole budget before reaching a single live keyword. 90 days also matches the comparison window the Insights surfaces already default to.','2026-10-20'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_classification','max_attempts','3'::jsonb,'3'::jsonb,'integer','attempts','1'::numeric,'10'::numeric,NULL::jsonb,'Attempts before a keyword is quarantined','How many times a keyword may fail to classify before it is parked as failed and skipped by every later pass. A quarantined keyword keeps its error and is never deleted.','agent','Strict priority order plus retry-forever is a permanent silent stall: one keyword the model refuses to answer for blocks the highest-value slot in the queue indefinitely. Three attempts absorbs transient model and network failures while guaranteeing the queue always drains.','2026-10-20'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_classification','min_impressions','2'::jsonb,'2'::jsonb,'integer','impressions','0'::numeric,'100000'::numeric,NULL::jsonb,'Demand floor for spending','A keyword with no clicks and fewer impressions than this inside the rollup window is measured but not classified. Any keyword that has earned a click is classified regardless of this number.','agent','Live distribution 2026-08-21: of 67,606 unclassified GSC-active keywords, 23,286 drew fewer than 2 impressions in 90 days — 34% of the work for roughly a thousandth of the demand, and mostly one-off long-tail noise. A floor of 2 is the least aggressive setting that excludes the single-impression tail. Set it to 0 to classify everything; the deferred count is always reported so the exclusion is never silent.','2026-10-20'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_classification','stale_claim_minutes','45'::jsonb,'45'::jsonb,'integer','minutes','5'::numeric,'1440'::numeric,NULL::jsonb,'Claim lease before a dead worker''s batch is reclaimed','A batch left in the running state longer than this is handed back to the queue, on the assumption its worker died.','agent','A 200-keyword pass takes about 7.5 minutes of model time. 45 minutes is 6x that, so a slow-but-alive pass is never double-classified, while a crashed worker costs one lease window rather than blocking those keywords forever.','2026-10-20'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_place_detection','batch_keywords','300'::jsonb,'300'::jsonb,'integer','keywords','50'::numeric,'20000'::numeric,NULL::jsonb,'Keywords per place-detection pass','How many keywords one bounded place pass claims from the demand ledger.','agent','This pass is pure SQL over a 1,059-row gazetteer — no model, no provider, no dollars — so the only ceiling to size against is the authenticated role''s 8s statement timeout, and a pass that trips it does not error loudly, it renders as a spinner (THE SCOPE RULE failure mode). Measured live 2026-08-22 on the real corpus, repeated: 200 keywords = 2.6s, 300 = 3.5–3.7s, 500 = 6.1s, 1000 = 11.4–11.6s. The cost is roughly 12ms/keyword and is dominated by the fact-store write (seo.keyword_facet is versioned), not by the regex match. 300 keeps a pass at well under half the ceiling. The click-earning universe is 1,442 keywords, so five presses cover everything that has ever earned a click; the full 67,884 GSC-active corpus is what the proposed nightly schedule is for. Re-measure before raising this.','2026-10-22'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_place_detection','daily_keyword_ceiling','20000'::jsonb,'20000'::jsonb,'integer','keywords','100'::numeric,'500000'::numeric,NULL::jsonb,'Nightly ceiling (runaway bound)','The most keywords the nightly place-detection handler may scan in one run. Detection is pure SQL with zero AI spend, so this bounds an accident (a loop that never sees the queue drain), not a budget.','agent','The whole unscanned corpus was ~67,800 keywords when this landed (2026-08-24: ~226 bench presses at 300). 20,000/night clears it in about four nights and re-clears daily arrivals in one pass thereafter.','2026-10-05'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_place_detection','min_impressions','1'::jsonb,'0'::jsonb,'integer','impressions','0'::numeric,'1000'::numeric,NULL::jsonb,'Demand floor','A keyword with zero clicks needs at least this many 90-day impressions for the nightly to scan it; the pass also always takes anything with a click. 0 scans everything.','agent','Detection is free, so the floor exists only to keep the queue ordering meaningful; 1 excludes nothing that ever surfaced. Deferred keywords are reported, never silent.','2026-10-05'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.keyword_value','baseline_score','100'::jsonb,'100'::jsonb,'number','points','0'::numeric,'100000'::numeric,NULL::jsonb,'Keyword score baseline','Every keyword score starts here before adds and factors. A site may override it in its own settings; this is the platform default (KI-048).','agent','The 100-baseline law: a round, legible neutral point so "below 100" reads as worse than neutral and "above" as better.','2026-11-22'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.multi_location','max_attribution_km','75'::jsonb,'75'::jsonb,'number',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Attribution radius (km)','How far a detected place may sit from a business location and still be attributed to it. Only applies when BOTH the place and the location carry coordinates; today no business location does, so this path is dormant and seo.gsc_location_readiness says so.','agent',NULL,NULL::date,'d2c50c66-ce50-468f-90d7-1283f2bf4ec4'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.multi_location','single_location_fallback','true'::jsonb,'true'::jsonb,'boolean',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Attribute every local keyword when there is only one location','When a brand has exactly one active location, attribute every local keyword to it. Turn this off for a business whose single listed location does not represent where it actually serves.','agent',NULL,NULL::date,'d2c50c66-ce50-468f-90d7-1283f2bf4ec4'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.rank_tracking','default_cadence_days','7'::jsonb,'7'::jsonb,'integer','days','1'::numeric,'365'::numeric,NULL::jsonb,'Default re-check cadence','How often a rank target is re-checked when the portfolio row does not say otherwise.','agent','Weekly matches what Semrush''s free Position Tracking gives, at a cost of roughly $0.05/keyword/year. Daily would be 7x the spend for movement most sites cannot act on.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.rank_tracking','default_country','"US"'::jsonb,'"US"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Default country','ISO country used when a rank target does not name one.','agent','The platform''s current customer base. A knob so the first non-US customer is a row, not a deploy.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.rank_tracking','default_device','"desktop"'::jsonb,'"desktop"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["desktop", "mobile"]'::jsonb,'Default device','Device profile used when a rank target does not name one.','agent','Desktop SERPs are the stabler baseline for tracking movement; mobile is available per target.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.rank_tracking','default_language','"en"'::jsonb,'"en"'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Default language','ISO language used when a rank target does not name one.','agent','Same basis as default_country.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.rank_tracking','default_provider','"brave"'::jsonb,'"brave"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["brave", "serpapi"]'::jsonb,'Default rank provider','Which SERP provider a rank check uses when the target does not name one.','agent','Brave is the cheapest lane ($0.005/run estimated) and needs no location string. SerpApi remains selectable per target.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.rank_tracking','default_serp_depth','20'::jsonb,'20'::jsonb,'integer','results','1'::numeric,'100'::numeric,NULL::jsonb,'Default SERP depth','How many results a rank check reads before deciding the target is not ranking.','agent','Matches Brave''s provider-default result count, so the common path costs one request. Page 2 is where a realistic improvement target lives; deeper costs more for positions nobody acts on.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.rank_tracking','max_history_points','500'::jsonb,'500'::jsonb,'integer','points','10'::numeric,'10000'::numeric,NULL::jsonb,'Maximum rank-history points returned','Bound on a single rank-history read. Costs nothing to serve; exists so one target cannot return an unbounded series.','agent','Roughly 10 years of weekly checks. Generous by construction — this reads first-party data we already hold, which the policy says should not be stingily metered.','2026-10-04'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.situational_stamps','max_passes_per_run','25'::jsonb,'25'::jsonb,'integer',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Round-trips one refresh run may take','One evaluation pass writes at most writes_per_pass keywords and reports what is left; this is how many times a single run will go back for the rest before it stops and says the segment is still filling.','agent','Replaces a hard-coded 25 that had been sitting in the browser loop (MAX_EVALUATION_PASSES in features/marketing/search-console/data-dig.ts) — a ceiling in code is not a knob. 25 passes x writes_per_pass (8,000) is 200,000 keyword writes, and the largest 28-day window in the whole fleet is All Green Recycling at 27,234 keywords (measured 2026-08-23), so 25 clears the worst real case seven times over while still bounding a pathological loop. Every real segment measured so far finishes in ONE pass.','2026-11-23'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.situational_stamps','stale_after_hours','24'::jsonb,'24'::jsonb,'integer',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'How old an as-of may get before a segment owes a refresh','A condition matcher whose segment was last worked out longer ago than this is owed a re-derivation, and is what the run console counts as work.','agent','Search Console data lands once a day and the situational window is 28 days (seo.situational_stamps.window_days), so a segment cannot meaningfully change more than once a day — re-deriving more often would spend statement time to confirm yesterday''s answer. 24 hours also means an as-of a person reads is never more than one Search Console delivery behind, which is the strongest honesty this data can support. The pass costs no AI dollars (pure SQL, ~0.32 ms/stamp write measured 2026-08-23), so this number is about truthfulness, not budget.','2026-11-23'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.situational_stamps','window_days','28'::jsonb,'28'::jsonb,'integer','days','1'::numeric,'480'::numeric,NULL::jsonb,'Evaluation window','How many days back a situational segment looks when it is re-derived. A situational stamp is a claim about now, so this is the definition of "now" for every Dig Here rule that fills a segment.','agent','Matches the Search Console default range (GSC_DEFAULT_RANGE = 28 days) so a segment means the same window the person was looking at when they created it — the identity between what the Dig Here table shows and what the segment holds is the whole point. Google''s own dashboards default to 28 days for the same reason: shorter windows swing on weekday seasonality, longer ones stop describing the present.','2026-10-22'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.situational_stamps','writes_per_pass','8000'::jsonb,'8000'::jsonb,'integer','keywords','500'::numeric,'100000'::numeric,NULL::jsonb,'Keywords stamped per evaluation pass','How many NEW keywords one press of Re-evaluate (or one scheduled pass) may stamp into a situational segment. It is a round-trip budget, never a cap on what the segment holds: when more remain the pass reports them and the next pass continues, and the release step waits until the fill is complete so a half-filled segment is never emptied.','agent','Measured live 2026-08-23: stamp writes cost ~0.32 ms/row (4,471 rows in 1.43s on Data Destruction, Inc.), and the unlimited dig that feeds them costs ~1s regardless of result size. The `authenticated` role — the PostgREST path a person''s Re-evaluate press takes — carries statement_timeout = 8s. 8,000 writes ≈ 2.6s, leaving roughly 5s of head-room for the dig and the release pass on the slowest site. The largest 28-day window in the entire fleet is All Green Recycling at 27,234 keywords, so even a pathological no-conditions segment completes in four passes; every real segment measured so far (DDI parked = 1,563) completes in one.','2026-10-22'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topic_placement','batch_keywords','50'::jsonb,'50'::jsonb,'integer','keywords','10'::numeric,'200'::numeric,NULL::jsonb,'Keywords per placement pass','How many keywords one scheduled pass (or one press of Place next) claims and hands to the Topic Assigner.','agent','The assigner is ONE model call carrying the whole shared topic tree (330 nodes live 2026-08-22) plus the batch, and it must reason about every keyword against every node — so batch size trades directly against how carefully each keyword is placed. 50 is the size the shipped unplaced-queue button has always used, and the endpoint hard-caps at 200. Raise it only with evidence that placement quality holds.','2026-10-21'::date,'9a49913d-b785-4487-9b39-2371ef0542e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topic_placement','confidence_floor','90'::jsonb,'90'::jsonb,'integer','confidence','0'::numeric,'100'::numeric,NULL::jsonb,'Confidence at or above which a placement is a ruling, not a proposal','The Topic Assigner reports how sure it is (0-100) about each placement. At or above this number the placement is applied as a ruling; below it, the placement still lands but is flagged as a proposal and waits in the topics screen until a human confirms or replaces it.','agent','Measured over every agent placement that exists (157 rows, live 2026-08-22): confidence runs 88-99, mean 95, and NOT ONE is below 80. A floor of 70 or 80 would confirm everything and the proposal queue would be a feature that never fires — the silent no-op this whole system exists to prevent. 90 sits just below the mean and puts roughly the least-sure decile in front of a human. Once the first real backfill has run, re-read the distribution and move this number to where the disagreements actually are.','2026-10-21'::date,'9a49913d-b785-4487-9b39-2371ef0542e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topic_placement','daily_keyword_ceiling','8000'::jsonb,'2000'::jsonb,'integer','keywords','0'::numeric,'200000'::numeric,NULL::jsonb,'Keywords placed per UTC day, per site','The blast-radius backstop on the whole backfill. Once a site has had this many keywords placed by the agent in a UTC day, every further pass stops and reports the ceiling instead of spending more.','agent','gsc-ideas 2026-08-26: 63,543 keywords pending; measured ~$0.001/keyword from attributed AI calls, so the whole remainder costs ~$60 REGARDLESS of pace — the ceiling only decides 27 nights vs ~8. Raised to finish inside a week. Arman owns the spend; a lower number is one field on the knobs page.','2026-09-25'::date,'9a49913d-b785-4487-9b39-2371ef0542e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topic_placement','demand_window_days','90'::jsonb,'90'::jsonb,'integer','days','7'::numeric,'730'::numeric,NULL::jsonb,'Demand rollup window','How far back the backfill measures this site''s Search Console clicks and impressions when it decides which keyword to place next. Keywords with no traffic inside this window are not in the queue at all.','agent','Matches the facet backfill''s window exactly, on purpose: the two ledgers order the same corpus by the same demand, and a keyword should be classified and placed against one definition of "what this business currently feels". Measured live 2026-08-22 on datadestruction.com: a 90-day window enrols 8,455 keywords carrying 457 clicks and 1.13M impressions.','2026-10-21'::date,'9a49913d-b785-4487-9b39-2371ef0542e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topic_placement','max_attempts','3'::jsonb,'3'::jsonb,'integer','attempts','1'::numeric,'10'::numeric,NULL::jsonb,'Attempts before a keyword is quarantined','How many times a keyword may fail to be placed before it is parked as failed and skipped by every later pass. A quarantined keyword keeps its error and is never deleted.','agent','Strict priority order plus retry-forever is a permanent silent stall: one keyword the assigner will not place (it belongs to no branch and justifies no new node) blocks the highest-value slot in the queue indefinitely. Three attempts absorbs transient model and network failures while guaranteeing the queue always drains. Same value and same reasoning as the facet backfill.','2026-10-21'::date,'9a49913d-b785-4487-9b39-2371ef0542e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topic_placement','min_impressions','10'::jsonb,'10'::jsonb,'integer','impressions','0'::numeric,'100000'::numeric,NULL::jsonb,'Demand floor for spending','A keyword with no clicks and fewer impressions than this inside the rollup window is measured but not placed. Any keyword that has earned a click is placed regardless of this number.','agent','Live distribution 2026-08-22 on datadestruction.com: 3,246 of 8,455 enrolled keywords (38% of the work) have zero clicks and fewer than 10 impressions in 90 days, and together they carry 11,131 of the site''s 1,133,814 impressions — under 1% of the demand for nearly 40% of the bill. A floor of 10 buys back that spend without touching a single keyword the business has felt. Set it to 0 to place everything; the deferred count is always reported, so the exclusion is never silent.','2026-10-21'::date,'9a49913d-b785-4487-9b39-2371ef0542e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topic_placement','sites_per_scheduled_pass','3'::jsonb,'3'::jsonb,'integer','sites','1'::numeric,'100'::numeric,NULL::jsonb,'Sites visited by one scheduled run','How many sites one scheduled run works, chosen most-owed-clicks first. A site is only ever visited once someone has enrolled it by refreshing its queue from the topics screen.','agent','One site''s pass is up to daily_keyword_ceiling / batch_keywords = 40 model calls, so three sites bounds a nightly run at 120 calls in the worst case while covering every site currently enrolled (1 live on 2026-08-22). Raise it as tenants are onboarded, together with a look at the run''s wall clock.','2026-10-21'::date,'9a49913d-b785-4487-9b39-2371ef0542e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topic_placement','stale_claim_minutes','45'::jsonb,'45'::jsonb,'integer','minutes','5'::numeric,'1440'::numeric,NULL::jsonb,'Claim lease before a dead worker''s batch is reclaimed','A batch left in the running state longer than this is handed back to the queue, on the assumption its worker died.','agent','A 50-keyword assigner pass is a single multi-minute model call; 45 minutes is many times that, so a slow-but-alive pass is never double-placed, while a crashed worker costs one lease window rather than blocking those keywords forever. Matches the facet backfill so an operator has one number to reason about.','2026-10-21'::date,'9a49913d-b785-4487-9b39-2371ef0542e0'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','bulk_action_confirm','"above_n"'::jsonb,'"above_n"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["always", "above_n", "never"]'::jsonb,'Bulk page actions: when to confirm','always: confirm every bulk action. above_n: confirm once the selection passes the threshold below. never: no confirmation.','agent','Requirements §5 (2026-09-15). `never` is listed because a settings vocabulary that cannot express "stop asking me" sends people to the code.','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','bulk_action_confirm_threshold','20'::jsonb,'20'::jsonb,'integer','pages','1'::numeric,'5000'::numeric,NULL::jsonb,'Bulk page actions: the confirm threshold','With bulk_action_confirm = above_n, a selection larger than this asks for confirmation first.','agent','Requirements §5 (2026-09-15).','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','default_view','"outline"'::jsonb,'"outline"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["outline", "table", "graph", "text"]'::jsonb,'Map: the view it opens in','outline: a file-tree of labels and lines. table: indented rows with columns. graph: the drawing. text: exactly what an agent receives.','agent','Requirements §5 (2026-09-15). No view is privileged; this is only where it starts.','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','description_regeneration_mode','"queued"'::jsonb,'"queued"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["automatic", "queued", "manual"]'::jsonb,'Topic descriptions: regeneration when children change','automatic: regenerate a topic''s description whenever its children change. queued: propose the regeneration for approval. manual: never regenerate on its own.','agent','Doctrine ruling: product choice belongs to the user; this is only the starting default.','2026-12-14'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','detail_panel','"window"'::jsonb,'"window"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["window", "drawer"]'::jsonb,'Topic detail: where it opens','window: the Matrx window panel. drawer: the side drawer.','agent','Requirements §2.3 (2026-09-15).','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','graph_band_card_max','15'::jsonb,'15'::jsonb,'integer','topics','1'::numeric,'500'::numeric,NULL::jsonb,'Graph: cards up to this many topics','While at most this many topics are on screen the graph draws full cards. Above it, compact rows.','agent','Requirements §2.2 (2026-09-15): the drawing changes with how much is on screen, and the bands are settings.','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','graph_band_compact_max','40'::jsonb,'40'::jsonb,'integer','topics','1'::numeric,'2000'::numeric,NULL::jsonb,'Graph: compact rows up to this many topics','Above this many topics on screen the graph stops drawing text rows and becomes a line drawing.','agent','Requirements §2.2 (2026-09-15).','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','graph_band_line_max','200'::jsonb,'200'::jsonb,'integer','topics','1'::numeric,'10000'::numeric,NULL::jsonb,'Graph: line drawing up to this many topics','Above this many topics on screen only shapes remain; labels appear on hover or selection.','agent','Requirements §2.2 (2026-09-15).','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','graph_encoding','{"hue": "grouped_facet", "fill": "status", "ring": "tier", "size": "pages"}'::jsonb,'{"hue": "grouped_facet", "fill": "status", "ring": "tier", "size": "pages"}'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Graph: what shape and colour mean','The legend. size: what makes a node bigger. fill: what colours its body. ring: what colours its outline. hue: which facet drives the colour wheel when the graph is grouped by a facet.','agent','Requirements §2.2 (2026-09-15): the legend is the user''s to change.','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','intent_colors','{"delete": "red", "leaving": "amber", "missing": "gray_dashed", "planned": "purple_dashed", "arriving": "blue", "in_place": "green"}'::jsonb,'{"delete": "red", "leaving": "amber", "missing": "gray_dashed", "planned": "purple_dashed", "arriving": "blue", "in_place": "green"}'::jsonb,'json',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Intent colours','The colour each intent state carries in the graph and the table: staying put, leaving this topic, arriving at this topic, to be deleted, a topic that should have a page and has none, and a page that exists only on paper.','agent','Requirements §2.7 and §5 (2026-09-15).','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','intent_review_mode','"one_by_one"'::jsonb,'"one_by_one"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["one_by_one", "accept_all", "batch"]'::jsonb,'Proposed page intents: how they are reviewed','one_by_one: decide each proposed intent. accept_all: one button for the lot. batch: select several and decide together.','agent','Requirements §4 U5 and §5 (2026-09-15).','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','map_agent_change_mode','"propose"'::jsonb,'"propose"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["apply", "propose", "ask"]'::jsonb,'Map agent: what it may change','apply: its edits land straight away. propose: its edits arrive as proposals to accept. ask: it asks before each change. A map-wide agent proposes by default because its reach is the whole map.','agent','Requirements §2.4 (2026-09-15), first guess.','2026-12-16'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','mapping_batch_size','50'::jsonb,'50'::jsonb,'integer','pages','1'::numeric,'500'::numeric,NULL::jsonb,'Mapper: pages per call','How many page summaries are sent to the mapper in one call against the outline overview.','agent','First guess from the topical-map doctrine (2026-09-14).','2026-12-14'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
