insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','neighborhood_min_nodes','25'::jsonb,'25'::jsonb,'integer','topics','1'::numeric,'1000'::numeric,NULL::jsonb,'Outline neighborhood: minimum topics','Around the focus topic the outline shows children, siblings, then cousins, widening until at least this many topics are showing.','agent','First guess from the topical-map doctrine (2026-09-14). Not yet calibrated.','2026-12-14'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
