insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','proposal_mode','"auto_apply_initial"'::jsonb,'"auto_apply_initial"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["auto_apply", "approval", "auto_apply_initial"]'::jsonb,'Proposed topics: how they are applied','auto_apply: proposed topics become active immediately. approval: they wait as proposed until accepted. auto_apply_initial: auto-apply while a site is being mapped for the first time, approval afterward.','agent','Doctrine ruling: product choice belongs to the user; this is only the starting default.','2026-12-14'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
