insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('seo.topical_map','topic_description_max_chars','1200'::jsonb,'1200'::jsonb,'integer','characters','50'::numeric,'20000'::numeric,NULL::jsonb,'Topic description: storage cap','Longest description a map topic may store. AI-written descriptions are naturally short; this is a guard, not a target.','agent','First guess from the topical-map doctrine (2026-09-14).','2026-12-14'::date,'4801fce9-3a2e-4c62-b47e-99e06c13b3b2'::uuid,'{organization,brand,site,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('shape_system.structured_document','optional_fields','"omit"'::jsonb,'"omit"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["omit", "note", "show"]'::jsonb,'Fields that do not apply','What a rendered structured document does with a field that has no value. "omit" hides it and keeps a quiet count one click from the full list; "note" shows the field with a "does not apply" mark; "show" renders every field as authored. A review desk auditing a form wants "show"; a person reading advice wants "omit".','agent','Replaces the code default DEFAULT_OPTIONAL_FIELD_POLICY = "omit" in document-presentation.tsx, which the useEffectiveKnob read fell back to because no row existed.','2026-10-13'::date,'2023f930-d49b-4060-a405-ba853d57ace8'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('surfaces.menus','auto_collapse_threshold','20'::jsonb,'20'::jsonb,'integer','rows','5'::numeric,'100'::numeric,NULL::jsonb,'Menu rows before categories fold','A categorized menu shows all of its rows up to this many. Past it, the less-used categories fold into sub-menus so the list still fits on one screen without scrolling. About 17 rows fit in the desktop panel on a small laptop screen.','agent','Replaces AUTO_COLLAPSE_THRESHOLD = 20 in matrx-frontend components/official/AdvancedMenu.tsx (KNOB MIRROR: a synchronous render path).','2026-10-13'::date,'16f543fb-3cb4-4e91-a0b0-9fbf4923f43c'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('tables.density','mode','"normal"'::jsonb,'"normal"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["condensed", "normal", "spacious"]'::jsonb,'Table density','Controls the spacing of shared data tables. Normal is the standard presentation; condensed fits more rows and spacious provides larger controls and rows.','agent','Normal matches the 36px reference controls while retaining the approved 8px table region spacing. Condensed reduces visual control and row sizes; spacious increases them.','2026-10-29'::date,'16f543fb-3cb4-4e91-a0b0-9fbf4923f43c'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{"help": "Choose how compact shared data tables appear. Your organization may set a default; your choice applies only to you in this organization.", "group": "Table presentation", "order": 1, "control": "segmented"}'::jsonb,'instant','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('tables.pagination','approved_by','""'::jsonb,'""'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Approving owner','Required when Load more replaces automatic page loading. Name the owner who approved the exception.','agent','Manual table pagination is an exception and must record its reason and approving owner.','2026-10-28'::date,'16f543fb-3cb4-4e91-a0b0-9fbf4923f43c'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{"help": "Required only when manual loading is selected. Name the owner who approved the exception.", "group": "Automatic loading exception", "order": 5, "control": "text"}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('tables.pagination','intent_timeout_ms','1200'::jsonb,'1200'::jsonb,'integer','milliseconds','100'::numeric,'3000'::numeric,NULL::jsonb,'Scroll gesture recognition window','How long a wheel, touch, keyboard, or scrollbar gesture may authorize the following downward scroll. Each successful request consumes that gesture.','agent','1200 milliseconds allows touch momentum while bounding how long unrelated programmatic scrolling could follow the input.','2026-10-27'::date,'16f543fb-3cb4-4e91-a0b0-9fbf4923f43c'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('tables.pagination','mode','"scroll"'::jsonb,'"scroll"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["scroll", "manual"]'::jsonb,'Load the next table page','Scroll loads one additional page after deliberate downward scrolling near the bottom. Manual requires Load more. Applies only to tables connected to a paginated source.','agent','User requested automatic fetching only after physical scrolling. Manual remains available for preference, accessibility, and unscrollable lists.','2026-10-27'::date,'16f543fb-3cb4-4e91-a0b0-9fbf4923f43c'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('tables.pagination','reason','""'::jsonb,'""'::jsonb,'string',NULL,NULL::numeric,NULL::numeric,NULL::jsonb,'Reason automatic loading is disabled','Required when Load more replaces automatic page loading. Explain the source, accessibility, or operational boundary.','agent','Manual table pagination is an exception and must record its reason and approving owner.','2026-10-28'::date,'16f543fb-3cb4-4e91-a0b0-9fbf4923f43c'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{"help": "Required only when manual loading is selected. Explain why automatic page loading is not safe or appropriate.", "group": "Automatic loading exception", "order": 4, "control": "textarea"}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('tables.pagination','threshold_px','96'::jsonb,'96'::jsonb,'integer','pixels','0'::numeric,'400'::numeric,NULL::jsonb,'Distance from the bottom to load more rows','A new page may load when deliberate scrolling reaches this distance from the bottom. Existing rows remain visible while the page loads.','agent','96 pixels approximates two compact table rows, providing a small loading runway without prefetching distant pages.','2026-10-27'::date,'16f543fb-3cb4-4e91-a0b0-9fbf4923f43c'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('tool_call_visualization','schema_label_max_depth','12'::jsonb,'12'::jsonb,'integer','levels','1'::numeric,'64'::numeric,NULL::jsonb,'Deepest schema level labelled','How many nested levels of a tool''s result schema are walked to find field titles. A schema that refers to itself forever must not hang the screen.','agent','Replaces MAX_DEPTH = 12 in matrx-frontend features/tool-call-visualization/result-fields/schema-labels.ts (KNOB MIRROR: a synchronous recursion guard).','2026-10-13'::date,'7e6f5a07-44a4-4568-8f1b-c035cd7bdb13'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('ui.detail','default_presentation','"window"'::jsonb,'"window"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["window", "docked", "page"]'::jsonb,'Open record details as','How a record''s details open when you click it anywhere on the platform: a floating window you can move and dock to the tray, a panel docked to the side of what you are working on, or a full page. The same content shows in all three, and every one offers the other two.','agent','Notion''s per-database "Open pages in" setting (side peek / center peek / full page) and Linear''s peek are the reference; Arman 2026-09-17: "The default is the window."','2026-10-31'::date,'16f543fb-3cb4-4e91-a0b0-9fbf4923f43c'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{"help": "Window keeps you where you are and can be minimized to the tray. Docked sits beside your work and resizes. Page takes the whole screen. Your organization may set a default; your choice applies only to you.", "group": "Record details", "order": 1, "control": "segmented"}'::jsonb,'instant','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('unfolding','distill_window_steps','3'::jsonb,'3'::jsonb,'integer','moments','1'::numeric,'12'::numeric,NULL::jsonb,'Moments read together','When a case is read for rules, this is how many consecutive moments are read at once — always knowing only what was known at the time. Fewer moments means sharper, narrower rules; more moments means rules that span a longer stretch of the case.','agent','A decision and its payoff in a case narrative are typically one to three moments apart (order the test, get the result, see what it changed), so three consecutive moments is the smallest window that can carry a complete "in this state, do this, because it buys that". One moment alone shows a fact and an action with no consequence; the whole case at once is the flat read this lane exists to replace.','2026-10-12'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('unfolding','max_disclosure_steps','12'::jsonb,'12'::jsonb,'integer','requests','1'::numeric,'40'::numeric,NULL::jsonb,'Questions a Masterwork may ask a case','When a Masterwork works through a sealed case, this is the most questions it may ask of that case before it has to commit to an answer. It is the ceiling that stops a run asking forever.','agent','The unfolded reference case reaches its answer in twelve moments, and a practitioner who cannot converge in about that many deliberate questions is not converging. Each request costs a model call, so this doubles as the blast-radius backstop on the disclosure loop.','2026-10-12'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('unfolding','opening_steps','1'::jsonb,'1'::jsonb,'integer','moments','0'::numeric,'5'::numeric,NULL::jsonb,'Moments given for free at the start','How much of a sealed case a Masterwork is handed before it has to start asking: the presenting picture every practitioner is given before deciding anything. Raise it to make the exam easier, lower it to make the opening starker.','agent','One moment mirrors real practice: the presenting picture, and nothing else, is what a practitioner walks in with. Zero would ask a desk to reason from an empty page; more than one hands over findings the practitioner would have had to go and get.','2026-10-12'::date,'451c7c73-7e3b-4e2e-9166-eb4807f2caea'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('vault.browser_login','list_item_cap','25'::jsonb,'25'::jsonb,'integer','saved logins','1'::numeric,'500'::numeric,NULL::jsonb,'Saved logins shown in one list','When an agent asks to see the saved logins it may use, this is how many it gets in one answer. Each one is a short summary line — name, site, whether it has an authenticator app — and anything past this number is left out with a note telling the agent to search by site or name instead. Raising it makes a browse longer and more expensive; lowering it pushes agents to search.','agent','Chosen 2026-09-13 after a live agent asked twice, two minutes apart, whether a GitHub login existed and got 36,319 characters of full vault inventory both times (conversation 99d5b990, 06:07 and 06:09). The answer is now a summary line per item plus query/host filters; 25 summary lines are ~4,600 characters — a cheap browse — while the filters make the unfiltered list a fallback rather than the normal path. Org-overridable because how large a vault is, and how much of it an agent should see at once, is the tenant''s business; the platform range 1-500 stays the ceiling.','2026-12-13'::date,'7b6f5aed-4c9a-4e57-82ca-5aab28a0bc44'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
