insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('vault.native','max_matches','100'::jsonb,'100'::jsonb,'integer','matches','1'::numeric,'200'::numeric,NULL::jsonb,'Maximum native password metadata matches','Maximum value-free credential item and service-identifier matches returned to the native provider.','agent','Native direct-list wire limit from the accepted password contract.','2026-12-15'::date,'7b6f5aed-4c9a-4e57-82ca-5aab28a0bc44'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('vault.native','max_service_identifiers','32'::jsonb,'32'::jsonb,'integer','identifiers','1'::numeric,'128'::numeric,NULL::jsonb,'Maximum native password service identifiers','Maximum AuthenticationServices service identifiers accepted by one native password request.','agent','Native direct-list wire limit from the accepted password contract.','2026-12-15'::date,'7b6f5aed-4c9a-4e57-82ca-5aab28a0bc44'::uuid,'{organization,user}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow','idempotency_retention_hours','24'::jsonb,'24'::jsonb,'integer','hours','1'::numeric,'720'::numeric,NULL::jsonb,'Idempotency claim retention','How long an X-Idempotency-Key claim on run-creation routes (workflow runs, trigger fires) is retained before a replay stops being recognised.','agent','Matches the previous DDL default (now() + 24h) on workflow.idempotency.expires_at, so turning the gate on changes no retention behaviour.','2026-11-24'::date,'fb19f8c1-01f4-43cc-a1db-c46657f1206b'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.checkpoint_write','max_retries','2'::jsonb,'2'::jsonb,'integer','attempts','0'::numeric,'10'::numeric,NULL::jsonb,'How many extra tries a progress-save gets before the run stops','If saving a step''s progress times out, we try again. Each save is stamped with its own id, so a repeat can never create a second copy — if the first attempt actually got through, we find the record already there and carry on. 0 means one timeout ends the run.','agent','Chosen 2026-09-12. Two extra attempts cover the transient database-load window that killed run 053e8b72 without letting a genuinely broken write stall a run for minutes. Higher belongs to a structural problem (a checkpoint too big to store, which the warn_bytes alarm names), never to a bigger retry count.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.checkpoint_write','retry_backoff_ms','250'::jsonb,'250'::jsonb,'integer','milliseconds','1'::numeric,'10000'::numeric,NULL::jsonb,'How long to wait before retrying a progress-save','The first pause before trying a failed progress-save again. It doubles on each further try, and the actual wait is a random amount up to that ceiling so several runs that failed together do not all come back at the same instant.','agent','Chosen 2026-09-12. The failure being retried is server-side load, not a lock cycle, so the pause only has to let the queue drain; 250ms then 500ms adds under a second to a run that would otherwise have failed outright. Full jitter is the standard de-synchroniser for N runs that timed out in the same window.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.checkpoint_write','statement_timeout_ms','30000'::jsonb,'30000'::jsonb,'integer','milliseconds','1000'::numeric,'600000'::numeric,NULL::jsonb,'How long the database gets to save one step of a running workflow','Each time a workflow finishes a step it saves its progress so the run can survive a restart. This is how long that single save is allowed to take before we give up on it and try again. Too low and a big run fails under load; too high and one stuck save holds a database connection that other work needs.','agent','Chosen 2026-09-12 after run 053e8b72 lost a paid-for run to this exact write. Measured live: the equivalent checkpoints on three sibling runs were 1.0-1.2 MB and committed in 2-3s, so 30s is ~10x the observed cost. The previous effective ceiling was the pool command_timeout (10s), which nothing could raise for this write alone.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.checkpoint_write','warn_bytes','1048576'::jsonb,'1048576'::jsonb,'integer','bytes','1024'::numeric,'1073741824'::numeric,NULL::jsonb,'The size at which a saved step raises an alarm in our logs','A workflow that fans one job out over many items currently stores every item''s full input inside the saved step. Past this size we record a loud warning naming the steps that grew it, so the platform team can move those payloads to file storage instead. It never blocks the run.','agent','Chosen 2026-09-12 as one megabyte, just under the 1.0-1.2 MB step-3 checkpoints measured on the Newsroom Desk runs, so the very shape that failed is flagged from the first occurrence while ordinary checkpoints (5 bytes to ~190 KB) stay silent. It is an alarm threshold, not a limit.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.conductor','apply_mode','"auto"'::jsonb,'"auto"'::jsonb,'enum',NULL,NULL::numeric,NULL::numeric,'["auto", "review"]'::jsonb,'How the Conductor''s changes reach the canvas','When you build a workflow with the Conductor, it changes steps and connections for you. "As it goes" puts each change on the canvas the moment it is made, highlighted, with an Undo offered. "Show me first" saves the change but leaves your canvas as it was until you press Apply in the chat — or Take it back. Either way nothing is lost.','agent','Default auto: the Conductor already announces every change, reveals it on the canvas and offers Undo, so the extra confirmation buys nothing for a Creator working alone and costs a click per change. review is offered for organizations whose workflows are shared or consequential enough that an agent should show its work before the canvas moves. Chosen 2026-09-17 by the session that built Conductor mode; Arman has NOT reviewed this default.','2026-12-17'::date,'fb19f8c1-01f4-43cc-a1db-c46657f1206b'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{"help": "Applies the next time a workflow is opened with the Conductor. Changes are always saved; this only decides when your canvas shows them.", "group": "Workflow Studio", "order": 10, "control": "select", "options": [{"label": "As it goes (recommended)", "value": "auto"}, {"label": "Show me first", "value": "review"}]}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.dry_run','predicate_preview_row_limit','25'::jsonb,'25'::jsonb,'integer','rows','1'::numeric,'1000'::numeric,NULL::jsonb,'Rows in a gate preview','How many per-item rows a workflow gate''s dry-run preview carries. The author only needs enough to see the shape of the answer; the preview says when it truncated.','agent','Replaces PREDICATE_PREVIEW_ROW_LIMIT = 25 in matrx-graph dry_run.py; host-bound through configure_dry_run_knobs, package default is a KNOB MIRROR.','2026-10-13'::date,'8d269aff-22e8-4d8a-ae97-0f95bb29f154'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.recovery','auto_resume_max_attempts','3'::jsonb,'3'::jsonb,'integer','attempts','0'::numeric,'25'::numeric,NULL::jsonb,'How many times we restart the same dropped workflow before asking a person to look','Each restart re-runs the one step that was interrupted, which costs real money. If a workflow is dropped and restarted this many times and still does not get through, the platform stops and reports it instead of paying for another attempt. Everything it finished is still saved. 0 turns automatic restarting off entirely.','agent','Chosen 2026-09-12. The row also carries workflow.run.max_recovery_retries (default 25), but that ceiling counts EVERY recovery action including a person clicking Retry; unattended restarts need their own, much smaller budget and the smaller of the two wins. Three covers the realistic cause — a run unlucky enough to be caught by two or three consecutive deploys — while a fourth failure means something structural that another attempt will not fix (the Newsroom Desk run that produced this file would have burned 25 attempts at ~26 minutes each). Maximum 25 so it can never exceed the column cap it lives under.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.recovery','reconcile_interval_seconds','300'::jsonb,'300'::jsonb,'integer','seconds','30'::numeric,'3600'::numeric,NULL::jsonb,'How often we look for workflows that were dropped and can be continued','The sweep that finds workflows whose machine died and restarts them from their last saved point. It also runs immediately whenever a worker starts, so a replacement heals the casualties of its own deploy right away; this is the cadence in between.','agent','Chosen 2026-09-12, holding the cadence the worker loop already ran at. Deploys land about every 20 minutes, so a five-minute sweep recovers a casualty well within one deploy window while costing one small query per pass. Minimum 30s because a tighter loop adds database load without shortening the recovery a person perceives (the resume still has to be claimed and re-executed) on conflict (feature,key) do nothing; maximum 3600s because an hour of an unrecovered run is indistinguishable from losing it.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.recovery','reconcile_max_batch','25'::jsonb,'25'::jsonb,'integer','runs','1'::numeric,'500'::numeric,NULL::jsonb,'How many dropped workflows one pass may restart at once','When a whole machine goes down, many workflows may need restarting together. This caps how many one pass brings back, so a large backlog is worked through steadily instead of all landing on the workers at the same instant. The rest are picked up by the following passes.','agent','Chosen 2026-09-12, holding the ceiling the sweep already used. Each resumed run re-executes only the step it was interrupted on, but 25 of those starting in the same second is already a real load spike on the workers and their model providers; at a five-minute cadence 25 per pass still drains 300 runs an hour. Minimum 1 (an operator can deliberately trickle a recovery) on conflict (feature,key) do nothing; maximum 500, above which the remedy is more workers, not a bigger stampede.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.recovery','reconcile_window_seconds','172800'::jsonb,'172800'::jsonb,'integer','seconds','3600'::numeric,'604800'::numeric,NULL::jsonb,'How far back a dropped workflow is still worth restarting by itself','A workflow dropped days ago is usually no longer wanted, and starting it up again unasked is a surprise rather than a rescue. Past this age the platform stops restarting it automatically; the run and everything it finished stay on file and a person can still continue it.','agent','Chosen 2026-09-12, holding the 48 hours the sweep already used. Two days covers a weekend outage (a Friday-evening casualty is still recovered on Monday morning) without resurrecting work whose inputs or intent have moved on. Minimum one hour so the window can never be shorter than the runs it protects; maximum seven days because past a week the honest answer is a person deciding, not a sweep.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.recovery','shutdown_drain_seconds','20'::jsonb,'20'::jsonb,'integer','seconds','0'::numeric,'240'::numeric,NULL::jsonb,'How long a server being replaced waits for the workflows on it to reach a safe point','When a server is replaced, workflows running on it are given this long to finish what they are in the middle of. Anything still going is then handed back deliberately, so the next worker continues it from its last saved point immediately instead of waiting out the silence window above. Waiting longer makes every deploy slower for everyone.','agent','Chosen 2026-09-12. This budget is not meant to let an AI step finish (those run minutes) — it is meant to let a step that is ALREADY finishing commit its checkpoint, and to leave time for each interrupted run to write the marker that makes it resumable. 20s sits far above a checkpoint write and far below the 290s graceful-shutdown budget the process has, so it never becomes the reason a deploy is slow. 0 disables waiting (runs are handed back at once) on conflict (feature,key) do nothing; maximum 240s keeps it under that shutdown budget with room for every other drain in the lifespan. Read once per shutdown, so a change applies to the next deploy.','2026-12-12'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean);
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.recovery','stale_heartbeat_seconds','900'::jsonb,'900'::jsonb,'integer','seconds','60'::numeric,'7200'::numeric,NULL::jsonb,'How long a running workflow may go completely silent before we call it dropped','While a workflow is working it reports in constantly — every step, and every second or so while an AI step is writing. This is how long total silence has to last before the platform decides the machine running it is gone. It then brings the workflow back from its last saved point; only if that keeps failing is the run reported as failed.','agent','Chosen 2026-09-12, holding the value the in-app sweeper already used (the standalone script had drifted to 15 minutes; both now read this row). Reporting cadence is ~1.5s while anything at all happens, so ten minutes is roughly 400 missed signals — far past any plausible pause — while still shorter than the ~20-minute deploy interval, so a run dropped by one deploy is recovered before the next one lands. Minimum 60s because anything tighter starts racing slow first-token latency on a large model; maximum 7200s because a run nobody notices for two hours is an outage, not a delay. Propagation is next_load in its literal sense: the sweeper builds its SQL predicate once at process start, so a change lands on the next deploy or restart rather than mid-process. RAISED 2026-09-15 from 600s to 900s so the in-process step wall clock (workflow.step_clock.default_step_seconds, 600s) always fires first and names the step that stopped; this watchdog goes back to being what it is for — the backstop for a run whose process is genuinely gone.','2026-12-15'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.run_result','min_preview_chars','24'::jsonb,'24'::jsonb,'integer','characters','1'::numeric,'500'::numeric,NULL::jsonb,'Shortest text shown as a run preview','A text in a run result only counts as a preview sentence when it is at least this long; shorter strings are flags, not answers.','agent','Replaces MIN_PREVIEW_CHARS = 24 in matrx-frontend features/workflow-runtime/run-result/presented-result.ts (KNOB MIRROR: a synchronous pure function).','2026-10-13'::date,'33efef53-75f6-4008-b861-6dc862f7fcbf'::uuid,'{organization}'::text[],'any',NULL::jsonb,'{}'::jsonb,'next_load','f'::boolean) on conflict (feature,key) do nothing;
insert into platform.feature_knob (feature,key,value,default_value,value_type,unit,min_value,max_value,allowed_values,label,description,set_by,basis,review_due,taxonomy_node_id,overridable_by,override_direction,bound_value,ui,propagation,public_read) values ('workflow.step_clock','default_step_seconds','600'::jsonb,'600'::jsonb,'integer','seconds','5'::numeric,'86400'::numeric,NULL::jsonb,'How long one step of a workflow may run before it is stopped','Every step of a workflow — an AI step, a tool call, a fetch — gets this long to finish. If it passes the limit the step is stopped and the run reports which step it was and why, instead of sitting there looking busy for ever. A workflow whose author set a time limit on a particular step keeps that one; this is what every other step gets.','agent','Chosen 2026-09-15 from measurement, not taste. The longest healthy AI step observed on this platform is a large structured answer at roughly two to three minutes; the Masterwork Conductor step that provoked this row runs in ~82s normally and the agent tool-dispatch ceiling beside it is already 120s. Ten minutes is therefore four to seven times the honest worst case — wide enough that a legitimately slow model, a retried tool or a long fan-out item never trips it — while being a fraction of the 18m52s that actually happened. Minimum 5s because anything tighter cannot survive first-token latency on a large model; maximum 86400s because a step that may run for more than a day is a background job, not a step, and should be modelled as one. Propagation is instant: the scheduler reads the value per attempt through a 60-second knob cache, so raising it rescues runs that have not started their step yet without a deploy.','2026-12-15'::date,NULL::uuid,'{}'::text[],'any',NULL::jsonb,'{}'::jsonb,'instant','f'::boolean) on conflict (feature,key) do nothing;
